# Helper function for monitoring reports
def generate_monitoring_report(monitoring_data: Dict) -> str:
    """Generate basic monitoring report"""
    report = []
    report.append("\n" + "="*80)
    report.append("BIAS SCORE MONITORING REPORT")
    report.append("="*80)

    if 'bias_score_progression' in monitoring_data:
        scores = monitoring_data['bias_score_progression']
        report.append("\nBias Score Progression:")
        for stage, score in scores.items():
            if score is not None:
                report.append(f"  • {stage}: {score:.4f}")

    return "\n".join(report)

# ============================================================================
# DELIMITER-AWARE CSV LOADING
# ============================================================================

def smart_read_csv(path_or_buffer, **kwargs):
    """Load a CSV, auto-detecting its delimiter instead of assuming comma.

    Root cause this fixes: every pd.read_csv() call in this file used
    to assume comma-separated values, pandas' default. Real-world
    datasets aren't always comma-delimited -- found on Business/
    bank-full.csv (the genuine UCI Bank Marketing dataset), which is
    semicolon-delimited. Loading it with the comma default doesn't
    raise an error; it silently "succeeds" with exactly ONE column
    whose name is the entire header row jammed together (e.g.
    'age;"job";"marital";...;"y"'), and every row becomes one giant
    string value under that column. This looks like a working load --
    no exception, a real record count -- right up until target-column
    selection can't find 'y' (or any real column) at all. This is
    exactly the class of silent-wrong-behavior-instead-of-a-clear-
    error this project has treated as a bug everywhere else (see
    Workstream G's target-not-found fix, the fully-null protected-
    column guard, and the target-column auto-detection removal itself
    -- all share the same principle: fail loudly and clearly rather
    than silently produce a technically-valid-looking wrong result).

    Strategy: sniff the delimiter from a text sample using csv.Sniffer
    against the delimiters real-world exports actually use (comma,
    semicolon, tab, pipe), falling back to pandas' own sep=None/
    engine='python' auto-detection if sniffing is inconclusive. As
    defense in depth, if the result STILL has exactly one column,
    raise a clear ValueError naming the likely delimiter mismatch
    instead of silently returning a single-column dataframe -- a
    genuine one-column CSV is rare enough that erring on the side of
    "ask" rather than "assume" is the safer default, same reasoning
    already applied to target-column selection.

    Accepts anything pd.read_csv accepts (a path, or a file-like
    object such as io.BytesIO) so every existing call site can switch
    to this with no other changes. Any additional kwargs are passed
    through to pd.read_csv, but a caller-supplied `sep` is honored
    as-is (no sniffing) since an explicit delimiter is the user
    overriding auto-detection, exactly like target_column.
    """
    if "sep" in kwargs or "delimiter" in kwargs:
        return pd.read_csv(path_or_buffer, **kwargs)

    # Get a text sample to sniff, without consuming a file-like object
    # the caller still needs pd.read_csv to read from afterwards.
    sample = ""
    seekable_buffer = hasattr(path_or_buffer, "read") and hasattr(path_or_buffer, "seek")
    try:
        if seekable_buffer:
            start = path_or_buffer.tell()
            raw = path_or_buffer.read(8192)
            path_or_buffer.seek(start)
            sample = raw.decode("utf-8", errors="ignore") if isinstance(raw, bytes) else raw
        elif isinstance(path_or_buffer, str) and os.path.exists(path_or_buffer):
            with open(path_or_buffer, "r", encoding="utf-8", errors="ignore") as f:
                sample = f.read(8192)
    except Exception:
        sample = ""  # sniffing is best-effort; fall through to pandas' own detection

    detected_sep = None
    if sample:
        try:
            dialect = csv.Sniffer().sniff(sample, delimiters=",;\t|")
            detected_sep = dialect.delimiter
        except csv.Error:
            detected_sep = None  # inconclusive -- let pandas try sep=None below

    if detected_sep:
        df = pd.read_csv(path_or_buffer, sep=detected_sep, **kwargs)
    else:
        # csv.Sniffer was inconclusive among the known real-world
        # delimiters -- do NOT fall back to pandas' own unrestricted
        # sep=None auto-detection here. That mode considers ANY
        # character a candidate delimiter and, on a genuinely
        # single-column file of ordinary text with no real delimiter,
        # will invent a spurious split on some character that merely
        # happens to appear often (found via testing: a plain-text
        # single-column file got wrongly split on the letter 't').
        # Assuming the pandas default (comma) is the safer fallback;
        # the single-column check below still catches a real mismatch
        # if this guess is wrong.
        df = pd.read_csv(path_or_buffer, **kwargs)

    if len(df.columns) == 1:
        collapsed_name = str(df.columns[0])
        other_delim_hits = {d: collapsed_name.count(d) for d in (";", ",", "\t", "|") if d != (detected_sep or "")}
        likely_delim = max(other_delim_hits, key=other_delim_hits.get) if other_delim_hits else None
        preview = collapsed_name[:120] + ("..." if len(collapsed_name) > 120 else "")

        if likely_delim and other_delim_hits.get(likely_delim, 0) >= 2:
            # Real evidence of a delimiter mismatch, not just a genuinely
            # single-column file -- fail loudly rather than silently
            # handing back a garbage single-column dataframe.
            raise ValueError(
                f"This file loaded as a single column ('{preview}'), and that "
                f"column's name contains multiple '{likely_delim}' characters -- "
                f"this strongly suggests the file actually uses '{likely_delim}' "
                f"as its delimiter, not a comma. Please re-run specifying it "
                f"explicitly (e.g. sep='{likely_delim}')."
            )
        else:
            # No positive evidence of a delimiter bug -- could genuinely be
            # a single-column file. Don't hard-block it (downstream mapping
            # will fail clearly on its own if there's no usable target or
            # protected attribute), but flag it since it's an unusual shape
            # for a bias-audit dataset.
            logger.warning(
                f"   ⚠️  Loaded file has only one column ('{preview}'). If "
                f"this wasn't expected, the file may use a delimiter other "
                f"than comma."
            )

    return df


# ============================================================================
# CONTINUOUS PROTECTED-ATTRIBUTE BUCKETING
# ============================================================================

def _quantile_bucket_numeric_column(
    series: pd.Series, max_bins: int = 4, min_bin_size: int = 50
) -> Tuple[Optional[pd.Series], Optional[Dict]]:
    """Bucket a numeric column into a small number of quantile-based
    groups, for columns whose raw granularity is too fine for reliable
    bias measurement (each individual value its own "group").

    Root cause this fixes: raw per-year Age (and raw per-dollar Income)
    treated every distinct value as its own comparison group, repeatedly
    found across Phase 5 real-data validation to produce many groups
    with only a handful of samples -- structurally exempting exactly
    the groups most likely to show real disparity from ever clearing
    the minimum-group-size floor (NC, Business, German Credit, likely
    Heart Disease, Education/bar_pass, and Governance's raw income
    reaching min_group_size=1 and a negative-dollar-value "group" after
    SVM). Quantile bucketing groups the ACTUAL observed distribution
    into ranges rather than isolating each raw value, which also
    naturally absorbs outliers/edge values (e.g. a negative income from
    ACS PUMS's business-loss convention) into a sensible range instead
    of surfacing them as their own nonsensical singleton group.

    Strategy: pick the LARGEST number of quantile bins (from max_bins
    down to 2) whose smallest resulting bin still clears min_bin_size --
    quartiles (4) by default, matching the standard convention for
    income/wealth-distribution analysis in economics and policy
    literature, automatically narrowing for smaller datasets rather
    than using a fixed bin count regardless of sample size. Returns
    (None, None) if even 2 bins can't clear the floor (dataset too
    small for bucketing to help) -- caller falls back to its existing
    skip-with-a-reason behavior in that case, unchanged.

    Uses pandas' own qcut with duplicates='dropped' to handle skewed
    distributions where quantile boundaries collide (e.g. many
    identical values clustered at one end) -- silently produces fewer
    bins than requested in that case rather than raising, which the
    bin-size check below already accounts for.

    Returns (bucketed_series, info) where bucketed_series holds
    human-readable range labels (e.g. '18-24', '-6,000-22,300') and
    info records how many bins were used and their boundaries, for
    transparency in the mapping justification.
    """
    numeric = pd.to_numeric(series, errors="coerce")
    valid = numeric.dropna()
    if len(valid) < min_bin_size * 2:
        return None, None  # too few values for even 2 viable bins

    for n_bins in range(max_bins, 1, -1):
        try:
            binned = pd.qcut(numeric, q=n_bins, duplicates="drop")
        except (ValueError, IndexError):
            continue
        bin_sizes = binned.value_counts()
        if bin_sizes.empty or bin_sizes.min() < min_bin_size:
            continue

        def _fmt(edge: float) -> str:
            return f"{edge:,.0f}" if abs(edge) >= 1 else f"{edge:.2f}"

        label_map = {
            interval: f"{_fmt(interval.left)}-{_fmt(interval.right)}"
            for interval in binned.cat.categories
        }
        labeled = binned.map(label_map)
        # Preserve the original Series' NaNs/index rather than qcut's
        # own (which drops non-numeric-coercible rows silently).
        result = pd.Series(index=series.index, dtype=object)
        result.loc[valid.index] = labeled.loc[valid.index]
        return result, {
            "n_bins": len(label_map),
            "requested_bins": max_bins,
            "bin_labels": sorted(label_map.values()),
            "min_bin_size": int(bin_sizes.min()),
        }

    return None, None  # even 2 bins couldn't clear min_bin_size


# ============================================================================
# TARGET COLUMN NORMALIZATION
# ============================================================================

def coerce_binary_target(df: pd.DataFrame, column: str):
    """Normalize a target/outcome column to a clean {0, 1} int column.

    Every bias-scoring path in this pipeline (PreMitigationAuditor,
    DisparityEngine.score, VisualizationEngine, SVMFairnessEnforcer --
    dozens of call sites) computes group disparity as a difference in
    .mean() positive rate, which silently assumes the target is already
    numeric 0/1. Real-world outcome columns are often boolean, Yes/No
    strings, or categorical with more than two values (e.g. this
    project's North Carolina traffic-stop data, where the 'outcome'
    column has 3 categories: warning/citation/arrest) -- calling .mean()
    on those raises a raw TypeError deep inside pandas, with no
    indication of what actually went wrong or how to fix it.

    This coerces once, centrally, right after the target column is
    finalized -- so every downstream .mean() call just works -- instead
    of patching dozens of individual call sites. If the column can't be
    safely reduced to two categories, it fails fast with an actionable
    message instead of a stack trace after the (possibly very large)
    dataset has already been loaded and mapped.

    Returns (coerced_series, mapping) where mapping is None if the
    column was already clean numeric 0/1, or a dict describing which
    original value became 0 and which became 1 (recorded in
    audit_trail.json for transparency -- this is a real analytical
    decision, not just a technical detail).
    """
    # Deliberately casting to plain float64 here, NOT pandas' nullable
    # "Int64"/"Float64" dtypes. Nullable dtypes represent missing values
    # as pd.NA, whose __bool__ raises TypeError ("boolean value of NA is
    # ambiguous") the instant any downstream code does something as
    # ordinary as `if mean_rate == 0:` -- and this codebase does that in
    # several places (PreMitigationAuditor._measure_fairness among
    # them). A plain float64 represents missing values as an ordinary
    # np.nan, which compares as False and never raises. Any rows with a
    # genuinely missing target become NaN either way and get skipped by
    # the .mean()/.groupby() calls downstream (skipna=True is pandas'
    # default) -- the only difference is whether checking that fact
    # crashes the pipeline or not.
    series = df[column]
    non_null = series.dropna()

    if pd.api.types.is_bool_dtype(series):
        _check_target_coverage(non_null, column)
        return series.astype(float), None

    if pd.api.types.is_numeric_dtype(series) and set(non_null.unique()) <= {0, 1}:
        _check_target_coverage(non_null, column)
        return series.astype(float), None

    uniques = sorted(non_null.unique(), key=str)
    if len(uniques) != 2:
        preview = uniques[:5]
        raise ValueError(
            f"Target column '{column}' has {len(uniques)} unique value(s) "
            f"({preview}{'...' if len(uniques) > 5 else ''}), not 2. "
            f"BiasClean's bias scoring is a difference in positive rate "
            f"between groups, which requires a binary (two-category) "
            f"outcome -- it can't be computed on a multi-category column. "
            f"Either pick a different target column (e.g. a Yes/No or "
            f"True/False field), or preprocess this one into a binary flag "
            f"first, e.g.:\n"
            f"    df['{column}_binary'] = (df['{column}'] == '<the value "
            f"that should count as the positive outcome>')"
        )

    _check_target_coverage(non_null, column)

    mapping = {uniques[0]: 0, uniques[1]: 1}
    coerced = series.map(mapping).astype(float)
    return coerced, mapping


MIN_TARGET_CLASS_SIZE = 50  # matches ConstraintValidator.min_samples_per_group


def _check_target_coverage(non_null: pd.Series, column: str) -> None:
    """
    v3.6.8: a column can have exactly two distinct non-null values while
    having almost NO actual data -- e.g. opafy25nid.csv's 'TTSC1_60' (2
    non-null rows out of 66,662; it's 60 columns deep into a 111-column
    repeated-measures block, populated only for the rare person with that
    many episodes). Previously this was accepted as a fully valid binary
    target through ALL THREE of coerce_binary_target's return paths --
    bool dtype, already-clean 0/1 numeric, and the generic two-value
    mapping -- with no coverage check anywhere. bias_scores correctly
    came back NaN (nothing to compute), but the pipeline still produced a
    complete-looking "Not Audited, Review recommended" report with charts
    and a Deployment Decision section -- nothing told a no-code user the
    analysis measured essentially nothing. This mirrors the
    min_samples_per_group=50 floor ConstraintValidator already enforces
    for protected attributes, which had no equivalent on the target
    column itself. Called from all three return paths in
    coerce_binary_target so a column can't bypass the guard just by
    already being represented as 0/1 or bool.
    """
    counts = non_null.value_counts()
    if len(counts) == 0:
        min_class_size = 0
    else:
        min_class_size = int(counts.min())
    if min_class_size < MIN_TARGET_CLASS_SIZE:
        raise ValueError(
            f"Target column '{column}' has only {len(non_null)} non-missing "
            f"value(s) total across its categories (smallest category: "
            f"{min_class_size} sample(s), recommended minimum: "
            f"{MIN_TARGET_CLASS_SIZE}). This is too little data to compute "
            f"a reliable bias score -- accepting it would produce a NaN or "
            f"meaningless result while still looking like a completed "
            f"analysis. Either pick a target column with adequate coverage, "
            f"or investigate why this column is almost entirely missing "
            f"(e.g. a wide-format repeated-measures column populated for "
            f"only a few rows)."
        )


# ============================================================================
# JSON SERIALIZATION HELPER
# ============================================================================

def json_serializer(obj):
    """
    Custom JSON serializer for numpy types, pandas objects, and other non-serializable objects.
    To be used as default=json_serializer in json.dump() calls.
    """
    # Handle numpy types
    if isinstance(obj, np.integer):
        return int(obj)
    elif isinstance(obj, np.floating):
        return float(obj)
    elif isinstance(obj, np.ndarray):
        return obj.tolist()
    elif isinstance(obj, np.bool_):
        return bool(obj)  # Convert numpy bool to Python bool
    elif isinstance(obj, bool):
        return obj  # Python bool is already JSON serializable

    # Handle pandas/missing values
    elif pd.isna(obj):
        return None
    elif isinstance(obj, pd.Timestamp):
        return obj.isoformat()

    # Handle datetime objects
    elif hasattr(obj, 'isoformat'):
        return obj.isoformat()

    # Handle other common types
    elif isinstance(obj, (pd.Series, pd.DataFrame)):
        return obj.to_dict()
    elif isinstance(obj, set):
        return list(obj)

    # For everything else, use string representation
    try:
        return str(obj)
    except:
        raise TypeError(f"Object of type {type(obj).__name__} is not JSON serializable: {obj}")

# ============================================================================
# BIASCLEAN v3.0 CONFIGURATION
# ============================================================================

class BiasCleanConfig:
    """Empirical thresholds from v2.7 codebase"""

    # Operational modes
    MODE_AUDIT_FIRST = "audit_first"
    MODE_LEGACY = "legacy"
    MODE_AUDIT_ONLY = "audit_only"

    DEFAULT_MODE = MODE_AUDIT_FIRST

    # v2.7-derived thresholds (lines 510, 512, 546, 918)
    THRESHOLDS = {
        "min_total_records": 500,      # line 510: ConstraintValidator
        "min_samples_per_group": 50,   # line 510: ConstraintValidator
        "max_missing_rate": 0.3,       # line 512: ConstraintValidator
        "pos_rate_lower": 0.05,        # line 546: validate_outcome
        "pos_rate_upper": 0.95,        # line 546: validate_outcome
        "min_group_calc": 10,          # line 918: disparity calculation
        "harm_threshold": 0.05,        # practical significance threshold
        # v3.10.11: a genuine outcome varying independently across 7
        # unrelated protected characteristics essentially never shows
        # zero disparity on every single one at once -- this pattern is
        # far more consistent with a mis-selected, leaked, or otherwise
        # meaningless target column than with real fairness. Same lesson
        # as the amended Justice/COMPAS report's Finding 5 (is_recid): a
        # technically valid column choice can still be semantically
        # wrong, and suspiciously clean results deserve the same
        # scrutiny as suspiciously bad ones, not less.
        "suspiciously_uniform_disparity": 0.01,
    }

    SVM_DEFAULT = False  # matches v2.7 line 2520: test_rebalancing_only = True

config = BiasCleanConfig()

# ============================================================================
# PRE-MITIGATION AUDITOR (v3.0 NEW)
# ============================================================================

class PreMitigationAuditor:
    """
    Audit dataset before any mitigation using v2.7's own methodology.
    Returns traffic-light recommendation.
    """

    def __init__(self, domain_weights: dict):
        self.weights = domain_weights

    def audit(self, df: pd.DataFrame, target: str, feature_map: dict) -> dict:
        """Complete pre-mitigation audit"""
        logger.info(f"\n{'='*80}")
        logger.info("BIASCLEAN v3.0: PRE-MITIGATION AUDIT")
        logger.info(f"{'='*80}")

        results = {
            "data_quality": self._check_data_quality(df, target, feature_map),
            "baseline_fairness": self._measure_fairness(df, target, feature_map),
            "vulnerable_subgroups": self._find_vulnerable_groups(df, target, feature_map),
        }

        results["recommendation"] = self._generate_recommendation(results)

        self._print_summary(results)
        return results

    def _check_data_quality(self, df, target, feature_map) -> dict:
        """v2.7's ConstraintValidator logic"""
        issues = []
        warnings = []

        # Sample size check (v2.7 line 510)
        n = len(df)
        if n < config.THRESHOLDS["min_total_records"]:
            issues.append(f"Insufficient records: {n} < {config.THRESHOLDS['min_total_records']}")

        # Class balance (v2.7 line 546)
        if target in df.columns:
            pos_rate = df[target].mean()
            if not (config.THRESHOLDS["pos_rate_lower"] <= pos_rate <= config.THRESHOLDS["pos_rate_upper"]):
                warnings.append(f"Class imbalance: {pos_rate:.1%} positive")

        # Missing data (v2.7 line 512)
        missing_pct = df.isnull().sum().sum() / (n * len(df.columns))
        if missing_pct > config.THRESHOLDS["max_missing_rate"]:
            issues.append(f"Excessive missing data: {missing_pct:.1%}")

        # Group sizes (v2.7 line 510)
        min_group_sizes = []
        for col in feature_map.values():
            if col in df.columns:
                sizes = df[col].value_counts()
                min_group_sizes.append(sizes.min())

        if min_group_sizes:
            overall_min = min(min_group_sizes)
            if overall_min < config.THRESHOLDS["min_samples_per_group"]:
                warnings.append(f"Small groups: min size = {overall_min}")

        return {
            "blocking_issues": issues,
            "warnings": warnings,
            "n_records": n,
            "missing_pct": missing_pct,
            "quality_ok": len(issues) == 0
        }

    def _measure_fairness(self, df, target, feature_map) -> dict:
        """v2.7's coefficient-of-variation disparity (lines 906-935)"""
        per_feature = {}

        for feature, col in feature_map.items():
            if col not in df.columns:
                continue

            # Calculate group rates (v2.7 line 918: >=10 samples)
            group_rates = {}
            for group in df[col].dropna().unique():
                group_data = df[df[col] == group]
                if len(group_data) >= config.THRESHOLDS["min_group_calc"]:
                    rate = group_data[target].mean()
                    group_rates[str(group)] = rate

            if len(group_rates) < 2:
                continue

            # CV disparity (v2.7 lines 931-932)
            rates = np.array(list(group_rates.values()))
            mean_rate = np.mean(rates)

            if mean_rate == 0:
                cv = 0.0
            else:
                cv = np.std(rates) / mean_rate
                cv = min(cv, 1.0)  # v2.7 cap

            per_feature[feature] = {
                "disparity": float(cv),
                "weight": self.weights.get(feature, 0.05),
                "weighted": cv * self.weights.get(feature, 0.05),
                "n_groups": len(group_rates)
            }

        total_disparity = sum(f["weighted"] for f in per_feature.values())

        # See config.THRESHOLDS["suspiciously_uniform_disparity"]: every
        # computed feature landing below this at once is the tell, not
        # any single feature being low on its own (a dataset can
        # legitimately be unbiased on ONE characteristic).
        suspiciously_uniform = (
            len(per_feature) >= 2
            and all(f["disparity"] < config.THRESHOLDS["suspiciously_uniform_disparity"] for f in per_feature.values())
        )

        return {
            "per_feature": per_feature,
            "aggregate_bias": total_disparity,
            "n_features": len(per_feature),
            "suspiciously_uniform": suspiciously_uniform
        }

    def _find_vulnerable_groups(self, df, target, feature_map) -> dict:
        """Identify groups at risk during mitigation"""
        vulnerable = []
        overall_rate = df[target].mean()

        for feature, col in feature_map.items():
            if col not in df.columns:
                continue

            for group in df[col].dropna().unique():
                group_data = df[df[col] == group]
                group_rate = group_data[target].mean()

                risk_factors = []
                if len(group_data) < config.THRESHOLDS["min_samples_per_group"]:
                    risk_factors.append("small_sample")
                if group_rate < overall_rate * 0.8:
                    risk_factors.append("disadvantaged")

                if risk_factors:
                    vulnerable.append({
                        "feature": feature,
                        "group": str(group),
                        "size": len(group_data),
                        "rate": group_rate,
                        "risks": risk_factors
                    })

        return {
            "groups": vulnerable,
            "count": len(vulnerable)
        }

    def _generate_recommendation(self, results: dict) -> dict:
        """Traffic-light recommendation"""
        issues = results["data_quality"]["blocking_issues"]
        bias = results["baseline_fairness"]["aggregate_bias"]
        vulnerable = results["vulnerable_subgroups"]["count"]

        # RED conditions
        if issues:
            return {
                "traffic_light": "🔴 RED",
                "action": "BLOCKED - Address data quality",
                "rationale": issues,
                "proceed": False
            }

        if bias > 0.30:
            return {
                "traffic_light": "🔴 RED",
                "action": "BLOCKED - Severe baseline bias",
                "rationale": [f"Bias score {bias:.3f} > 0.30"],
                "proceed": False
            }

        suspiciously_uniform = results["baseline_fairness"].get("suspiciously_uniform", False)

        # YELLOW conditions
        if bias > 0.15 or vulnerable > 0 or suspiciously_uniform:
            return {
                "traffic_light": "🟡 YELLOW",
                "action": "REVIEW REQUIRED",
                "rationale": [
                    f"Moderate bias: {bias:.3f}" if bias > 0.15 else None,
                    f"Vulnerable groups: {vulnerable}" if vulnerable > 0 else None,
                    "Near-zero disparity on every protected feature at once -- double-check this is the "
                    "correct target column, not a near-duplicate, ID-like, or otherwise leaked column"
                    if suspiciously_uniform else None
                ],
                "proceed": True  # Allow with caution
            }

        # GREEN
        return {
            "traffic_light": "🟢 GREEN",
            "action": "PROCEED WITH MITIGATION",
            "rationale": [f"Acceptable baseline: bias={bias:.3f}, vulnerable={vulnerable}"],
            "proceed": True
        }

    def _print_summary(self, results: dict):
        """Concise audit summary"""
        rec = results["recommendation"]
        logger.info(f"\n  Audit Complete: {rec['traffic_light']}")
        logger.info(f"  Recommendation: {rec['action']}")
        logger.info(f"  Records: {results['data_quality']['n_records']:,}")
        logger.info(f"  Bias Score: {results['baseline_fairness']['aggregate_bias']:.3f}")
        logger.info(f"  Vulnerable Groups: {results['vulnerable_subgroups']['count']}")
        logger.info(f"{'='*80}")

