# ============================================================================
# 1. HIERARCHICAL MAPPER (Domain-Aware - 7 DOMAINS)
# ============================================================================

class HierarchicalMapper:
    """3-tier hierarchical feature mapper: Universal → Domain → Jurisdiction"""

    def __init__(self, domain="justice"):
        self.domain = domain
        self.config = DOMAIN_CONFIGS.get(domain, DOMAIN_CONFIGS["justice"])

        # Universal ontology (highest priority) - SAME FOR ALL DOMAINS
        self.universal_ontology = {
            "Age": {
                # v3.10.6 (open item 8): added "agep", the ACS/Census PUMS
                # variable code for age. Stress-tested against a broad
                # plausible-column-name list (district/distance/cost/
                # test_score/etc.) with zero false-positive collisions
                # under the whole-token boundary rule.
                "patterns": ["age", "birth_year", "dob", "date_of_birth", "age_at", "years_old", "agep"],
                "data_types": ["int64", "float64"]
            },
            "Ethnicity": {
                # v3.10.6 (open item 8): added "rac1p", the ACS/Census PUMS
                # race code. Deliberately did NOT add "hisp" (Hispanic-
                # origin) here -- ACS represents race (RAC1P) and Hispanic
                # origin (HISP) as two distinct variables, and this
                # pipeline currently has only one Ethnicity slot (open
                # item 3, unresolved). Adding "hisp" now would silently
                # recreate that exact problem under a new column name
                # instead of waiting for item 3's real fix (a separate
                # Race vs. Hispanic-origin category).
                "patterns": ["race", "ethnicity", "ethnic", "racial", "rac1p"],
                "value_mappings": {
                    "African-American": ["black", "african american", "aa", "afr_am"],
                    "Caucasian": ["white", "caucasian", "european"],
                    "Hispanic": ["latino", "latina", "latinx", "hispanic"],
                    "Asian": ["asian", "pacific islander", "api"],
                    "Native American": ["native", "indigenous", "american indian"],
                    "Other": ["other", "mixed", "multiracial"]
                }
            },
            "Gender": {
                # No change needed for open item 8: ACS's SEX variable
                # already matches the existing "sex" pattern exactly.
                "patterns": ["sex", "gender"],
                "value_mappings": {
                    "Male": ["m", "male", "man", "men"],
                    "Female": ["f", "female", "woman", "women"]
                }
            },
            "SocioeconomicStatus": {
                # v3.10.6 (open item 8): added "pincp" (total person's
                # income) and "povpip" (income-to-poverty ratio), the
                # ACS/Census PUMS variable codes. Both stress-tested clean.
                "patterns": ["income", "salary", "wage", "earnings", "wealth", "poverty", "ses", "pincp", "povpip"],
                "data_types": ["int64", "float64"]
            },
            "Region": {
                # v3.10.6 (open item 8): added "puma" (ACS's Public Use
                # Microdata Area code, stress-tested clean). Deliberately
                # did NOT add "st" (ACS's own State code): stress-testing
                # found it collides with plausible real column names like
                # st_number and postal_st under the whole-token boundary
                # rule. The existing "state" pattern already covers the
                # common case (and is what Governance's own validated
                # dataset uses after renaming), so this gap is accepted
                # rather than fixed with an unsafe short token.
                "patterns": ["region", "state", "county", "zipcode", "postcode", "location", "puma"],
                "data_types": ["object"]
            },
            "MigrationStatus": {
                # v3.10.6 (open item 8): added "cit" (ACS citizenship
                # status code) and "nativity" (ACS nativity code). Both
                # stress-tested clean against plausible column names
                # (citation_count, city_name, etc. -- none false-matched).
                "patterns": ["migration", "immigrant", "citizenship", "visa", "resident", "cit", "nativity"],
                "data_types": ["object"]
            },
            "DisabilityStatus": {
                # v3.10.6 (open item 8): added "dis" (ACS disability
                # status code). Stress-tested clean against plausible
                # column names (district, distance, dispatch_time,
                # dissolved, etc. -- none false-matched under the
                # whole-token boundary rule).
                "patterns": ["disability", "handicap", "impairment", "condition", "dis"],
                "data_types": ["object"]
            }
        }

        # Domain-specific ontologies (7 DOMAINS)
        self.domain_ontologies = {
            "justice": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    "SocioeconomicStatus": ["prior", "count", "criminal_history", "arrest", "convict"],
                    "Region": ["charge", "offense", "county", "jurisdiction", "district"],
                    "MigrationStatus": ["citizenship", "origin", "nationality"]
                },
                "exclusion_patterns": ["id", "name", "case", "number", "docket", "person_id", "defendant_id"]
            },
            "health": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    "SocioeconomicStatus": ["bmi", "smoking", "history", "medication", "treatment"],
                    "DisabilityStatus": ["disability", "handicap", "impairment", "condition"],
                    "Region": ["postcode", "zipcode", "location", "clinic", "hospital"]
                },
                "exclusion_patterns": ["id", "name", "patient_id", "ssn", "mrn", "record_id"]
            },
            "finance": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    # v3.10.3: added savings/property/housing/employment.
                    # Root cause: German Credit's own SavingsAccountBonds,
                    # Property, Housing, and PresentEmploymentSince columns
                    # are genuine, direct wealth/socioeconomic-status
                    # signals -- the kind of feature this famous benchmark
                    # dataset is specifically known for showing real
                    # disparity on -- but none of them contained any of
                    # the original 6 keywords, so SocioeconomicStatus (the
                    # highest-weighted feature in this domain, 0.30) was
                    # only ever catching InstallmentRatePctOfDisposableIncome,
                    # a loan-structuring ratio, not a genuine wealth proxy
                    # (see the "0.0000 bias, 0.00% improvement" first-run
                    # result on a dataset famous for real, documented bias).
                    "SocioeconomicStatus": ["income", "salary", "debt", "balance", "asset", "liability", "savings", "property", "housing", "employment", "job"],
                    "Region": ["postcode", "zipcode", "state", "county", "branch"],
                    # v3.10.6: added foreign_worker/foreign_national/
                    # foreign_born (open item 4). Root cause: German
                    # Credit's own ForeignWorker column -- a real,
                    # documented protected-attribute proxy in this
                    # benchmark dataset -- went unrecognized by every
                    # existing MigrationStatus keyword. A bare "foreign"
                    # stem was considered and rejected: _pattern_matches'
                    # whole-token rule would also match a plausible
                    # Finance column like ForeignExchangeRate, an FX/
                    # currency concept with nothing to do with immigration
                    # status -- a real semantic false-positive risk, not
                    # a matching-logic bug. These three explicit compound
                    # patterns close the German Credit gap without that
                    # ambiguity. Scoped to Finance only.
                    "MigrationStatus": ["citizenship", "visa", "resident", "immigration", "foreign_worker", "foreign_national", "foreign_born"]
                },
                "exclusion_patterns": ["id", "name", "applicant_id", "ssn", "account", "customer_id"]
            },
            "hiring": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    # v3.10.9 FIX: "experience" removed (Hamid's decision,
                    # real-data case: years_experience on OpenIntro_resume.csv
                    # newly cleared item 5's confidence-scaling threshold and
                    # got mapped to SocioeconomicStatus for the first time --
                    # years of work experience is a job-relevant
                    # qualification, not a genuine socioeconomic-status
                    # proxy the way education/qualification/degree/salary
                    # are. Same category of judgment call as Finance's
                    # foreign/ForeignExchangeRate false-positive risk:
                    # matching logic worked correctly, the keyword itself
                    # was just the wrong one for what it's meant to detect.
                    "SocioeconomicStatus": ["education", "qualification", "degree", "salary"],
                    "DisabilityStatus": ["disability", "accommodation", "accessibility"],
                    "Region": ["location", "postcode", "office", "branch"],
                    "MigrationStatus": ["visa", "citizenship", "residency", "work_permit"]
                },
                "exclusion_patterns": ["id", "name", "candidate_id", "applicant_id", "employee_id", "ssn"]
            },
            "education": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    # v3.10.6: added "imd"/"deprivation" (open item 4,
                    # Education's share of it). Root cause: studentInfo
                    # (OULAD)'s own imd_band column -- the UK's official
                    # socioeconomic deprivation index, the standard SES
                    # metric this exact dataset directly provides -- went
                    # unrecognized by every existing SocioeconomicStatus
                    # keyword, leaving zero SES coverage on a UK dataset
                    # for the UK-weighted domain that weights SES second-
                    # highest (0.25). Both new tokens are whole-token-safe
                    # under _pattern_matches' boundary rule. Scoped to
                    # Education only.
                    "SocioeconomicStatus": ["income", "parent_income", "scholarship", "fee", "financial_aid", "imd", "deprivation"],
                    "DisabilityStatus": ["disability", "learning_difficulty", "special_needs", "support"],
                    "Region": ["postcode", "school_district", "catchment", "borough"],
                    "MigrationStatus": ["first_language", "english_additional", "immigrant", "asylum"]
                },
                "exclusion_patterns": ["id", "name", "student_id", "pupil_id", "upi", "nino"]
            },
            "business": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    "SocioeconomicStatus": ["revenue", "profit", "turnover", "assets", "employees", "capital"],
                    "Region": ["location", "jurisdiction", "market", "territory", "area", "zone"],
                    "MigrationStatus": ["ownership", "origin", "international", "foreign", "domestic"]
                },
                "exclusion_patterns": ["id", "name", "company_id", "business_id", "tax_id", "vat", "registration", "timestamp"]
            },
            "governance": {
                "outcome_patterns": self.config["outcome_patterns"],
                "contextual_patterns": {
                    "SocioeconomicStatus": ["donation", "contribution", "endorsement", "support", "campaign_budget"],
                    "Region": ["constituency", "district", "ward", "borough", "riding", "precinct"],
                    "MigrationStatus": ["citizenship", "residency", "eligibility", "nationality"]
                },
                "exclusion_patterns": ["id", "name", "candidate_id", "official_id", "member_id", "voter_id", "ballot_id"]
            }
        }

        # Get domain-specific ontology
        self.domain_ontology = self.domain_ontologies.get(domain, self.domain_ontologies["justice"])

    @staticmethod
    def _pattern_matches(pattern: str, col_lower: str, prefix_ok: bool = False) -> bool:
        """Whole-token match: pattern must be bounded by the start/end
        of the string or a non-alphanumeric separator (e.g. underscore)
        on both sides. Plain substring containment (`pattern in
        col_lower`) let short fragments like "age" or "id" match inside
        unrelated words -- e.g. "average_income" and "wage_bracket" were
        misclassified as the Age attribute instead of
        SocioeconomicStatus, and any column containing "id" anywhere
        (e.g. "Valid_Response", "Residence_Type") was wrongly excluded
        as an identifier column. This still correctly matches genuine
        cases like "member_age", "age_group", "wage_bracket" (against
        the "wage" pattern), and "patient_id".

        prefix_ok=True relaxes only the RIGHT-hand boundary, so the
        pattern can match as the start of a longer word (still anchored
        on the left). This is needed because several domain
        outcome_patterns are deliberate word stems, not whole words --
        "recid" is meant to catch "recidivism"/"recidivist"/"is_recid",
        and "violat" is meant to catch "violation"/"violated". With the
        strict whole-token rule, a column literally named
        "Recidivism_Within_3years" fails to match "recid" (because
        "ivism" follows it with no separator), silently falls through to
        Unknown, and a real dataset then has its numeric-but-meaningless
        train/test split flag ("Training_Sample") picked as the target
        instead -- confirmed root cause of a GREEN "no bias" result on
        the NIJ Recidivism Challenge dataset that was actually auditing
        the wrong column entirely. The left boundary is still enforced,
        which is what actually prevents cross-word false positives
        ("id" cannot match inside "residence" or "valid" either way)."""
        right = r'(?:$|[^a-z0-9])' if not prefix_ok else ''
        return re.search(r'(?:^|[^a-z0-9])' + re.escape(pattern) + right, col_lower) is not None

    def map_column(self, column_name: str, sample_values: pd.Series) -> Dict:
        """Map a single column using 3-tier hierarchical rules"""
        # v3.10.2: insert word-boundaries at camelCase/PascalCase
        # transitions before matching, not just at non-alphanumeric
        # separators. Root cause found on the German Credit dataset
        # (Finance): its cleaned-up column names use PascalCase with no
        # underscores at all ('AgeInYears', 'PersonalStatusAndSex',
        # 'ForeignWorker'). The word-boundary check every tier relies on
        # (_pattern_matches) only treats non-alphanumeric characters as
        # boundaries -- deliberately, to stop 'age' from false-matching
        # inside 'wage'/'stage'/'garage' (see that method's docstring).
        # But with zero separators anywhere in the column name, 'age' in
        # 'AgeInYears' and 'sex' in 'PersonalStatusAndSex' never sit at
        # a recognized boundary either, so they fall through to Unknown
        # exactly like a real false positive would -- 20 of 21 columns
        # in that dataset mapped to nothing, producing a report that
        # looked like a clean "0.0000 bias / 0 significant" result but
        # had actually audited zero protected attributes. Splitting on
        # case transitions (lower->upper, and the acronym case
        # UPPER->Upper e.g. 'HTTPResponse'->'HTTP Response') restores a
        # real boundary for PascalCase/camelCase names without weakening
        # the existing wage/stage/garage protection at all -- those stay
        # single lowercase runs with no case transition to split on.
        # Purely additive: snake_case, space-separated, and already-
        # lowercase column names are unaffected (no case transitions to
        # find), so every previously-correct mapping stays identical.
        spaced_name = re.sub(r'(?<=[a-z0-9])(?=[A-Z])|(?<=[A-Z])(?=[A-Z][a-z])', ' ', column_name)
        col_lower = spaced_name.lower()

        # TIER 1: Universal attributes (highest priority)
        for feature, config in self.universal_ontology.items():
            for pattern in config["patterns"]:
                if self._pattern_matches(pattern, col_lower):
                    # Validate with sample values
                    value_score = self._validate_values(sample_values, config)
                    confidence = 0.85 + (value_score * 0.1)

                    return {
                        "feature": feature,
                        "confidence": min(confidence, 0.98),
                        "tier": "universal",
                        "justification": f"Column name '{column_name}' matches universal {feature} pattern",
                        "pattern_matched": pattern
                    }

        # TIER 2: Domain-specific (outcome detection)
        #
        # v3.6.3 FIX: every outcome_patterns match used to get the exact
        # same flat confidence (0.90), regardless of which pattern
        # matched or where it sits in the domain's outcome_patterns list.
        # Real-data finding on the NIJ Recidivism Forecasting Challenge
        # dataset: 8 different columns all matched an outcome pattern at
        # identical 0.90 confidence -- 'Recidivism_Within_3years' (the
        # actual challenge label, matches 'recid') PLUS three unrelated
        # supervision-violation flags ('Violations_ElectronicMonitoring',
        # 'Violations_Instruction', etc., matching the much more generic
        # 'violat') PLUS the three Recidivism_Arrest_YearN columns. With
        # every candidate tied at the same confidence, final target
        # selection (see the outcome_candidates sort in
        # UniversalBiasClean's target-detection block) falls through to
        # whichever one happens to sort first -- Python's stable sort on
        # a tie preserves dict/column order, which is pure file-layout
        # accident, not signal. Auto-detect silently picked
        # 'Violations_ElectronicMonitoring' -- a real, plausible-looking
        # column, not an obviously-wrong one like the original
        # 'Training_Sample' bug -- meaning the entire report would have
        # quietly been about supervision violations while every label,
        # domain context, and the dataset's own name say "recidivism."
        # The domain_ontology's outcome_patterns lists were already
        # ordered specific-to-generic ("recid", "reoffend", "rearrest"
        # before "violat" before the universal "outcome"/"target"/
        # "label" catch-alls) -- that ordering just wasn't doing
        # anything besides per-column pattern search order. Now it also
        # sets confidence: earlier-listed (more specific) patterns score
        # higher, so ties break by domain-intended semantic priority
        # instead of column position. Step size (0.005) is small enough
        # that even the longest outcome_patterns list (Governance, 11
        # entries) never drops below 0.85 -- still comfortably above the
        # 0.80 default auto-approval threshold, so this only changes
        # ordering among tied candidates, not which ones are eligible.
        for pattern_index, pattern in enumerate(self.domain_ontology["outcome_patterns"]):
            if self._pattern_matches(pattern, col_lower, prefix_ok=True):
                if sample_values.nunique() == 2:  # Binary outcome
                    return {
                        "feature": "__outcome__",
                        "confidence": max(0.80, 0.90 - pattern_index * 0.005),
                        "tier": "domain",
                        "justification": f"Binary outcome variable with pattern '{pattern}'",
                        "is_outcome": True
                    }
                else:
                    return {
                        "feature": "__outcome__",
                        "confidence": max(0.60, 0.70 - pattern_index * 0.005),
                        "tier": "domain",
                        "justification": f"Potential outcome variable (requires binarization)",
                        "requires_binarization": True
                    }

        # TIER 2: Contextual features (DOMAIN-SPECIFIC)
        for feature_type, patterns in self.domain_ontology["contextual_patterns"].items():
            for pattern in patterns:
                if self._pattern_matches(pattern, col_lower):
                    return {
                        "feature": feature_type,
                        "confidence": 0.75,
                        "tier": "domain",
                        "justification": f"Matches {feature_type} pattern '{pattern}'"
                    }

        # Exclusion patterns
        for pattern in self.domain_ontology["exclusion_patterns"]:
            if self._pattern_matches(pattern, col_lower):
                return {
                    "feature": "__exclude__",
                    "confidence": 0.85,
                    "tier": "exclusion",
                    "justification": f"Identifier/administrative column (pattern: '{pattern}')"
                }

        # No match found
        return {
            "feature": None,
            "confidence": 0.20,
            "tier": "unknown",
            "justification": "No semantic pattern match found - requires manual review"
        }

        # No match found
        return {
            "feature": None,
            "confidence": 0.20,
            "tier": "unknown",
            "justification": "No semantic pattern match found - requires manual review"
        }

    def _validate_values(self, sample_values: pd.Series, config: Dict) -> float:
        """Validate sample values against expected patterns"""
        if "value_mappings" in config:
            expected_values = set()
            for canonical, aliases in config["value_mappings"].items():
                expected_values.update([v.lower() for v in aliases])

            sample_set = set([str(v).lower() for v in sample_values.dropna().head(50)])
            if sample_set:
                overlap = len(sample_set & expected_values) / len(sample_set)
                return overlap

        if "data_types" in config and pd.api.types.is_numeric_dtype(sample_values):
            return 1.0

        return 0.5

    def map_dataset(self, df: pd.DataFrame) -> Dict[str, Dict]:
        """Map all columns in dataset"""
        mappings = {}
        for column in df.columns:
            sample = df[column].dropna()
            mappings[column] = self.map_column(column, sample)
        return mappings

# ============================================================================
# 2. CONSTRAINT VALIDATOR
# ============================================================================

class ConstraintValidator:
    """Statistical constraint validation for reliable fairness analysis"""

    def __init__(self):
        self.min_samples_per_group = 50
        self.min_total_records = 500
        self.max_missing_rate = 0.3

    def validate_outcome(self, df: pd.DataFrame, column: str) -> Dict:
        """Validate outcome variable suitability"""
        result = {
            "valid": True,
            "warnings": [],
            "errors": [],
            "statistics": {}
        }

        if column not in df.columns:
            result["valid"] = False
            result["errors"].append(f"Column '{column}' not found in dataset")
            return result

        clean_series = df[column].dropna()
        unique_count = clean_series.nunique()

        result["statistics"]["unique_values"] = unique_count
        result["statistics"]["total_samples"] = len(clean_series)

        # Must be binary
        if unique_count != 2:
            result["warnings"].append(f"Outcome has {unique_count} unique values (expected: 2)")
            if unique_count > 5:
                result["valid"] = False
                result["errors"].append("Too many unique values for binary outcome")

        # Check balance
        if unique_count == 2:
            positive_rate = clean_series.mean()
            result["statistics"]["positive_rate"] = positive_rate

            if not (0.05 <= positive_rate <= 0.95):
                result["warnings"].append(f"Class imbalance: {positive_rate:.1%} positive rate")

        # Check missing values
        missing_rate = df[column].isna().mean()
        result["statistics"]["missing_rate"] = missing_rate

        if missing_rate > 0.1:
            result["warnings"].append(f"High missing rate: {missing_rate:.1%}")

        return result

    def validate_protected_attribute(self, df: pd.DataFrame, column: str,
                                     target: str, feature_type: str = None) -> Dict:
        """Validate protected attribute for fairness analysis"""
        result = {
            "valid": True,
            "warnings": [],
            "errors": [],
            "statistics": {}
        }

        if column not in df.columns or target not in df.columns:
            result["valid"] = False
            result["errors"].append("Required columns not found")
            return result

        clean_data = df[[column, target]].dropna()

        # Workstream G (Phase 4): a protected attribute column that's
        # entirely missing -- or entirely non-overlapping with the
        # target's own missing values -- previously fell through this
        # function's later checks in a way that looked harmless but
        # wasn't. value_counts() on the resulting empty clean_data
        # returns an empty Series, whose .min() is NaN (not an
        # exception); `NaN < self.min_samples_per_group` then silently
        # evaluates to False, so the "Small group size" warning never
        # fires. The crosstab a few lines below DOES raise on zero rows,
        # but that's caught by this function's own broad except and
        # surfaces only as a generic warning ("Statistical test failed:
        # No data; `observed` has size 0.") -- a warning, not an error,
        # so it does NOT block auto-approval (auto_approve_high_
        # confidence only refuses on validation['errors'], never on
        # warnings). A column with literally zero usable rows could
        # therefore be silently auto-approved and passed on to
        # rebalancing, where groupby(column) on an all-missing column
        # produces zero groups and rebalancing becomes a silent no-op --
        # nothing tells a no-code user their protected-attribute mapping
        # measured nothing at all. Checked explicitly and early, before
        # any of the value_counts/crosstab logic that previously masked
        # it, with a specific, actionable message rather than a
        # leaked-through scipy/pandas exception string.
        if len(clean_data) == 0:
            result["valid"] = False
            result["errors"].append(
                f"Protected attribute column '{column}' has no rows where "
                f"both it and the target column '{target}' are non-missing "
                f"-- there is no overlapping data to compute a group "
                f"disparity from. This column cannot be used for fairness "
                f"analysis; check whether '{column}' was populated "
                f"correctly for this dataset (e.g. an entirely blank "
                f"column, or a column populated only for rows where the "
                f"target itself is missing)."
            )
            result["statistics"]["min_group_size"] = 0
            result["statistics"]["n_groups"] = 0
            return result

        # Check sample size per group
        value_counts = clean_data[column].value_counts()
        min_samples = value_counts.min()
        n_groups = len(value_counts)

        result["statistics"]["min_group_size"] = min_samples
        result["statistics"]["n_groups"] = n_groups

        if min_samples < self.min_samples_per_group:
            result["warnings"].append(
                f"Small group size: {min_samples} samples (recommended: {self.min_samples_per_group}+)"
            )

        # Check statistical relationship with outcome
        try:
            contingency = pd.crosstab(clean_data[column], clean_data[target])

            if contingency.shape == (2, 2):
                _, p_value = fisher_exact(contingency)
                test_used = "fisher-exact"
            else:
                chi2, p_value, _, _ = chi2_contingency(contingency)
                test_used = "chi-square"

            result["statistics"]["p_value"] = p_value
            result["statistics"]["test_used"] = test_used

            if p_value >= 0.05:
                result["warnings"].append(
                    f"Weak statistical relationship with outcome (p={p_value:.4f})"
                )

        except Exception as e:
            result["warnings"].append(f"Statistical test failed: {str(e)}")

        return result

# ============================================================================
# 3. USER CONFIRMATION UI (AUTO-APPROVAL MODE)
# ============================================================================

class MappingConfirmationUI:
    """CLI interface for mapping approval with auto-approval capability"""

    def __init__(self):
        self.approved_mappings = {}
        self.rejected_mappings = []

    def auto_approve_high_confidence(self, proposals: Dict,
                                    threshold: float = 0.80,
                                    total_records: Optional[int] = None) -> Dict:
        """Auto-approve high-confidence mappings for production"""
        logger.info(f"\n{'='*80}")
        logger.info(f"AUTO-APPROVAL MODE (Confidence Threshold: {threshold:.0%})")
        logger.info(f"{'='*80}\n")

        approved_count = 0
        rejected_count = 0

        # v3.6.9: cardinality guard, closing the gap already flagged as a
        # "future cardinality guard" in the v3.6.6 changelog. Found on
        # ok_oklahoma_city_2023_01_26.csv (945,107 real rows): 'location'
        # has 204,447 distinct values -- essentially unique per row, not
        # a real category -- yet tied with 'vehicle_registration_state'
        # for Region and won the tie (both carried the pipeline's own
        # "Small group size" warning, so the v3.6.7 tie-break fix had no
        # way to distinguish "catastrophically bad" from "one rare
        # out-of-state plate"; that fix checks warning PRESENCE, not
        # severity). The practical symptom was the pipeline appearing to
        # hang: per-group statistics across 204K+ near-singleton groups
        # on 945K rows took long enough to look indistinguishable from a
        # genuine deadlock. Rejecting excessive-cardinality candidates
        # here removes them before any of that computation runs, fixing
        # both the wrong-column selection AND the slowdown at the root,
        # rather than just picking a better tie-break winner after the
        # fact.
        #
        # v3.7.1: the original threshold (reject if average group size
        # would be below the 50-sample floor, i.e. n_groups >
        # total_records/50) was too strict for small datasets and broke a
        # previously-correct, previously-validated result. Found on
        # communities_prepared.csv (1,994 real rows): 'state' has 46
        # groups, averaging ~43 samples each -- comfortably usable, and
        # the exact column that correctly won this dataset's Region
        # mapping under v3.6.7 -- but 46 > 1994/50 (=39.9), so the guard
        # rejected it outright, and with EVERY other column in this
        # 130-column file also rejected on confidence grounds, the
        # pipeline had zero approved mappings and crashed entirely
        # ("No mappings approved"). The gap between a genuinely
        # pathological column and a merely-somewhat-fine-grained one on a
        # small dataset is large -- OK City's location averaged 4.6
        # samples/group; Communities & Crime's state averaged 43 -- so the
        # threshold now requires the average to fall below HALF the
        # floor (25, not 50) before rejecting, which keeps location
        # rejected (4.6 << 25) while correctly re-admitting state
        # (43 > 25). The per-group 50-sample floor itself is unchanged
        # and still governs which INDIVIDUAL groups get excluded from
        # actual rebalancing -- this only changes whether a column is
        # considered a viable CATEGORY at all.
        MIN_SAMPLES_PER_GROUP = 50  # matches ConstraintValidator.min_samples_per_group
        CARDINALITY_REJECTION_FLOOR = MIN_SAMPLES_PER_GROUP / 2  # v3.7.1: 25, not 50
        max_supportable_groups = (
            total_records / CARDINALITY_REJECTION_FLOOR if total_records else None
        )

        for column, candidates in proposals.items():
            if not candidates:
                self.rejected_mappings.append(column)
                rejected_count += 1
                continue

            best = max(candidates, key=lambda x: x["confidence"])
            validation = best.get("validation", {})
            confidence = best["confidence"]
            feature = best["feature"]
            n_groups = validation.get("statistics", {}).get("n_groups")

            excessive_cardinality = bool(
                max_supportable_groups and n_groups and n_groups > max_supportable_groups
            )


            # Auto-approve criteria
            should_approve = (
                confidence >= threshold and
                validation.get("valid", True) and
                feature not in [None, "__exclude__"] and
                len(validation.get("errors", [])) == 0 and
                not excessive_cardinality
            )

            if should_approve:
                self.approved_mappings[column] = {
                    **best,
                    "auto_approved": True,
                    "threshold_used": threshold
                }

                icon = "✅"
                logger.info(f"{icon} {column:25} → {feature:20} ({confidence:.0%})")
                approved_count += 1
            else:
                self.rejected_mappings.append(column)

                # Determine reason
                reasons = []
                if confidence < threshold:
                    reasons.append(f"low confidence ({confidence:.0%})")
                if not validation.get("valid", True):
                    reasons.append("validation failed")
                if feature in [None, "__exclude__"]:
                    reasons.append("excluded/unknown")
                if validation.get("errors"):
                    reasons.append("has errors")
                if excessive_cardinality:
                    reasons.append(
                        f"excessive cardinality ({n_groups} groups across "
                        f"{total_records} rows -- max supportable at "
                        f"{int(CARDINALITY_REJECTION_FLOOR)}-sample floor: "
                        f"{int(max_supportable_groups)})"
                    )

                icon = "⏭️"
                logger.info(f"{icon} {column:25}   SKIPPED ({', '.join(reasons)})")
                rejected_count += 1

        logger.info(f"\n{'='*80}")
        logger.info(f"MAPPING SUMMARY")
        logger.info(f"{'='*80}")
        logger.info(f"✅ Approved: {approved_count} columns")
        logger.warning(f"⏭️  Skipped:  {rejected_count} columns")
        logger.info(f"{'='*80}\n")

        return self.approved_mappings

# ============================================================================
# 4. BIASCLEAN ENGINE (FIXED - Weight-Based Prioritization)
# ============================================================================

class BiasCleanEngine:
    """Core bias detection and mitigation engine with proper weight prioritization"""

    def __init__(self, domain_weights: Dict[str, float]):
        self.domain_weights = domain_weights
        self._feature_map = {}
        self._target_column = None
        # v3.2.0: per-run bookkeeping for Preferential Sampling + the
        # group-size floor, reset at the start of every transform_industry()
        # call. Read by UniversalBiasClean after rebalancing to populate
        # audit_trail.json's excluded_small_groups / rebalance_method blocks.
        self.rebalance_log = []

    def score(self, df: pd.DataFrame, target_column: str) -> float:
        """Calculate weighted bias score (0-1, lower is better).

        Straight weighted sum over whatever features are genuinely
        computed -- no count-based renormalization. The previous
        "normalization = len(weights) / meaningful_features" step
        conflated "feature not computed" with "feature computed as
        zero" and rescaled the total by feature COUNT rather than by
        weight, which could make genuinely successful mitigation
        (multiple features fixed to zero disparity) look like it barely
        improved, since the shrinking "meaningful" count inflated the
        remaining features' contribution to compensate.
        """
        total_score = 0.0
        for feature, weight in self.domain_weights.items():
            disparity = self._calculate_disparity(df, feature, target_column)
            total_score += weight * disparity
        return total_score

    def _calculate_disparity(self, df: pd.DataFrame, feature: str,
                           target_column: str) -> float:
        """Calculate outcome disparity for a protected feature"""
        column = self._feature_map.get(feature)
        if not column or column not in df.columns or target_column not in df.columns:
            return 0.0

        try:
            group_rates = {}
            for group in df[column].unique():
                if pd.isna(group):
                    continue
                group_data = df[df[column] == group]
                if len(group_data) >= 10:
                    rate = group_data[target_column].mean()
                    group_rates[str(group)] = rate

            if len(group_rates) < 2:
                return 0.0

            rates = np.array(list(group_rates.values()))
            mean_rate = np.mean(rates)

            if mean_rate == 0:
                return 0.0
            cv_disparity = np.std(rates) / mean_rate
            return min(cv_disparity, 1.0)

        except Exception:
            return 0.0

    def transform_industry(self, df: pd.DataFrame,
                         diagnostic_results: Dict, rebalance_method: str = "reweighing") -> pd.DataFrame:
        """Apply bias mitigation with PROPER weight-prioritized rebalancing.

        v3.3.0: rebalance_method selects the per-feature resampling
        technique -- 'preferential' (Preferential Sampling, Kamiran &
        Calders 2012, default since 3.2.0) or 'reweighing' (the SAME
        paper's other technique: compute the classic reweighing ratio
        W(g,y) = P(g)*P(y)/P(g,y) per protected-group/label cell, then
        realize it as row resampling so the result is a corrected
        dataframe directly comparable to 'preferential' via the same
        composite-score evaluation).

        v3.7.0: df_optimized carries a temporary '_biasclean_row_uid'
        column (dropped before return) through every feature's pass, and
        self._protected_row_uids accumulates the uids of every row
        belonging to a group any feature has excluded as too small to
        rebalance. Both persist across the whole per-feature loop below --
        see _rebalance_feature_reweighing's docstring for why this is
        needed (cross-feature row overlap perturbing an excluded group's
        composition), found on real COMPAS data during the Phase 3
        AIF360/Aequitas benchmark."""
        if not diagnostic_results.get("requires_mitigation", False):
            return df.copy()

        df_optimized = df.copy()
        df_optimized["_biasclean_row_uid"] = range(len(df_optimized))
        self._protected_row_uids = set()
        target = self._target_column or diagnostic_results.get("target_column_used")

        # Get features with significant bias, sorted by weight (highest first)
        biased_features = []
        for feature, test_result in diagnostic_results.get("feature_tests", {}).items():
            if test_result.get("significant_bias", False):
                weight = self.domain_weights.get(feature, 0.05)
                biased_features.append((feature, weight))

        # FIXED: Sort by weight descending (highest weight = highest priority)
        biased_features.sort(key=lambda x: x[1], reverse=True)

        logger.info(f"\n   WEIGHT-PRIORITIZED MITIGATION ORDER:")
        logger.info(f"   {'Feature':<25} {'Weight':<10} {'Priority'} ")
        logger.info(f"   {'-'*25} {'-'*10} {'-'*8}")
        for i, (feature, weight) in enumerate(biased_features, 1):
            logger.info(f"   {feature:<25} {weight:<10.2f} #{i}")

        # v3.10.5: REBALANCE-STAGE FUSE -- actively excludes and reverts
        # any feature whose rebalancing produces an actionable reversal,
        # instead of only flagging it (the v3.4.0 "regulator flag"
        # behavior this replaces). Root cause of why a flag-only response
        # wasn't enough: the thermostat (_max_correction_without_crossing)
        # already prevents each feature's OWN pass from overshooting past
        # parity -- but a LATER feature's pass can still perturb an
        # EARLIER feature's already-finalized row composition through
        # row-level overlap (the same interaction _protected_row_uids
        # exists to guard against for too-small-excluded groups, but not
        # for groups that WERE successfully rebalanced). By the time the
        # old single end-of-loop check ran, multiple features' effects
        # were already compounded together, making a clean per-feature
        # undo intractable -- which is exactly why v3.4.0 deliberately
        # scoped this to "flag for manual review" rather than auto-revert.
        #
        # Real-data motivation: Governance/ACS PublicCoverage (renamed
        # columns) showed the disadvantaged group flip for Ethnicity, Age,
        # and SocioeconomicStatus after rebalancing -- correctly flagged,
        # but the flagged (reversed) result was still what got delivered
        # as "final". Hamid's explicit direction: this is not acceptable
        # for a thermostat/fuse design built specifically to prevent the
        # pipeline from creating new victims -- it needs fixing, not just
        # disclosing.
        #
        # Fix: rather than trying to surgically subtract one feature's
        # compounded contribution from a multi-feature-perturbed final
        # state (the intractable problem above), restart the ENTIRE
        # sequential pass from the true original data (df_before_any)
        # with the reversed feature's column excluded from correction
        # entirely. This is a clean, well-defined operation precisely
        # because it never asks "what would this feature's effect have
        # been in isolation" -- it recomputes every remaining feature's
        # correction fresh, now correctly accounting for one less
        # source of row-level interaction. Iterates (bounded) since
        # excluding one feature can occasionally surface a reversal in
        # a different feature that previously looked clean.
        MAX_REBALANCE_ATTEMPTS = min(len(biased_features) + 1, 8)
        remaining_features = list(biased_features)
        self.rebalance_excluded_features = []  # [{feature, reason, disadvantaged_before, disadvantaged_after}]
        df_optimized = None
        self.reversal_checks = {}
        df_before_any = df.copy()

        for attempt in range(1, MAX_REBALANCE_ATTEMPTS + 1):
            df_attempt = df_before_any.copy()
            self.rebalance_log = []
            self._protected_row_uids = set()
            for feature, weight in remaining_features:
                column = self._feature_map.get(feature)
                if column and column in df_attempt.columns:
                    if rebalance_method == "reweighing":
                        df_attempt = self._rebalance_feature_reweighing(
                            df_attempt, column, target, weight, feature_name=feature
                        )
                    else:
                        df_attempt = self._rebalance_feature_weighted(
                            df_attempt, column, target, weight, feature_name=feature
                        )

            # v3.2.0: reversal detection. Every earlier release only checked
            # whether a disparity's MAGNITUDE shrank or grew; nothing checked
            # whether the same group stayed disadvantaged. A gap that shrinks
            # toward zero and a gap that overshoots past zero into the
            # opposite group look identical to a magnitude-only check --
            # confirmed on real COMPAS data that Preferential Sampling alone
            # (no size floor) could flip Ethnicity's disadvantaged group.
            attempt_reversal_checks = {}
            threshold_by_feature = {
                e.get("feature"): e.get("disparity_threshold")
                for e in self.rebalance_log if e.get("disparity_threshold") is not None
            }
            actionable_this_attempt = []
            for feature, weight in remaining_features:
                column = self._feature_map.get(feature)
                if column and column in df_attempt.columns:
                    check = self._detect_reversal(
                        df_before_any.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                        df_attempt.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                        column, target
                    )
                    attempt_reversal_checks[feature] = check
                    if check and check.get("reversed"):
                        threshold = threshold_by_feature.get(feature)
                        gap = check.get("after_gap")
                        if threshold is None or gap is None or gap >= threshold:
                            actionable_this_attempt.append((feature, check))

            df_optimized = df_attempt
            self.reversal_checks = attempt_reversal_checks

            if not actionable_this_attempt:
                break  # clean -- no actionable reversal among the features we tried this attempt

            if attempt == MAX_REBALANCE_ATTEMPTS:
                # Attempt cap reached -- fall back to the old, honest
                # last-resort behavior: keep this result and let
                # process_dataset's rebalance_gate flag whatever's left
                # for manual review, same as pre-v3.10.5 behavior. This
                # should be rare in practice (most real cases have 1-3
                # biased features, resolving within 1-2 exclusions).
                logger.warning(f"\n   ⛔ REBALANCE FUSE: reached the retry limit "
                      f"({MAX_REBALANCE_ATTEMPTS} attempts) still finding an actionable "
                      f"reversal -- falling back to flagging for manual review rather than "
                      f"further exclusion.")
                break

            for feature, check in actionable_this_attempt:
                logger.warning(f"\n   ⛔ REBALANCE FUSE: '{feature}' reversed the disadvantaged "
                      f"group ('{check.get('disadvantaged_before')}' -> "
                      f"'{check.get('disadvantaged_after')}') -- excluding this feature from "
                      f"mitigation and reverting to its original (uncorrected) values, then "
                      f"redoing the remaining feature(s)' rebalancing from scratch.")
                self.rebalance_excluded_features.append({
                    "feature": feature,
                    "reason": "excluded after its rebalancing reversed the disadvantaged group; "
                              "reverted to original (uncorrected) values for this feature",
                    "disadvantaged_before": check.get("disadvantaged_before"),
                    "disadvantaged_after": check.get("disadvantaged_after"),
                })
            excluded_this_round = {f for f, _ in actionable_this_attempt}
            remaining_features = [(f, w) for f, w in remaining_features if f not in excluded_this_round]
            # Deliberately no early-return here even if remaining_features
            # is now empty: the NEXT loop iteration still needs to run (it
            # will trivially produce df_before_any unchanged, since the
            # inner per-feature loop has nothing left to iterate) so that
            # df_optimized actually reflects the fully-reverted state,
            # not the previous attempt's dataframe with the now-excluded
            # feature's bad rebalancing still baked into its row values.

        # v3.10.6 FIX (open item 10): once a feature is fuse-excluded, it
        # drops out of `remaining_features` and is never reversal-checked
        # again -- but df_optimized's final ROW composition still shifts
        # from df_before_any as a side effect of every OTHER feature's
        # resampling (rows get duplicated/removed for their sake), which
        # can silently move an excluded feature's own group rates even
        # though its column values are never touched. Real-data case:
        # Governance's Age was excluded/reverted by the fuse, yet still
        # showed disparity worsening -9.6% (0.1717->0.1883) purely from
        # other features' resampling, and Ethnicity's worst group shifted
        # (6.0->5.0) the same way -- neither was caught by anything,
        # since exclusion was previously treated as "this feature is now
        # safe to ignore." This post-hoc check runs the same
        # _detect_reversal used for included features, but AFTER
        # df_optimized is fully settled, purely diagnostically -- it
        # never re-excludes or re-reverts anything (that would risk an
        # unbounded cascade), it just records what happened so it's
        # visible in audit_trail.json and the report instead of silently
        # unmonitored.
        for entry in self.rebalance_excluded_features:
            column = self._feature_map.get(entry["feature"])
            if not column or column not in df_optimized.columns:
                continue
            drift_check = self._detect_reversal(
                df_before_any.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                df_optimized.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                column, target
            )
            # Also compute the feature's OWN before-state gap (by comparing
            # df_before_any against itself) so a magnitude-only drift --
            # gap widening with no outright group flip, e.g. Age's case
            # above -- is caught too, not just a worst-group reversal.
            before_self_check = self._detect_reversal(
                df_before_any.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                df_before_any.drop(columns=["_biasclean_row_uid"], errors="ignore"),
                column, target
            )
            if drift_check:
                before_gap = (before_self_check or {}).get("after_gap")
                after_gap = drift_check.get("after_gap")
                gap_widened = (
                    isinstance(before_gap, (int, float)) and isinstance(after_gap, (int, float))
                    and after_gap > before_gap
                )
                worst_group_shifted = bool(drift_check.get("reversed"))
                if worst_group_shifted or gap_widened:
                    logger.warning(
                        f"\n   ⚠️  POST-EXCLUSION DRIFT: '{entry['feature']}' was excluded and "
                        f"reverted, but its own disparity still moved as a side effect of other "
                        f"features' resampling (worst group: '{drift_check.get('disadvantaged_before')}' "
                        f"-> '{drift_check.get('disadvantaged_after')}', gap: "
                        f"{before_gap if before_gap is not None else '?'} -> {after_gap if after_gap is not None else '?'})."
                    )
                entry["post_exclusion_drift"] = {
                    "worst_group_before": drift_check.get("disadvantaged_before"),
                    "worst_group_after": drift_check.get("disadvantaged_after"),
                    "worst_group_shifted": worst_group_shifted,
                    "gap_before": before_gap,
                    "gap_after": after_gap,
                    "gap_widened": gap_widened,
                }

        return df_optimized.drop(columns=["_biasclean_row_uid"], errors="ignore")

    def _rank_by_boundary_distance(self, df: pd.DataFrame, target: str,
                                   exclude_cols: List[str]) -> Optional[pd.Series]:
        """Preferential Sampling's ranker (Kamiran & Calders, KAIS 2012):
        score every row by how close a simple classifier puts it to the
        decision boundary (P(target=1) near 0.5), using only the
        dataset's own non-protected numeric columns. Rows nearest the
        boundary are the ones Preferential Sampling duplicates/removes
        first -- borderline cases are the ones most likely to have been
        mis-labeled by whatever produced the original disparity, per the
        paper's rationale, instead of a uniform-random pick.

        Returns None (caller falls back to the old v3.1.x uniform-random
        selection, with a console note) whenever ranking isn't viable:
        no numeric predictive column, too few rows, or a single-class
        target in this slice. This must never raise or crash the
        pipeline -- BiasClean runs across arbitrary real-world schemas
        in 7 domains, most of which won't look like COMPAS."""
        try:
            numeric_cols = [
                c for c in df.select_dtypes(include=[np.number]).columns
                if c != target and c not in exclude_cols
            ]
            # Real-world data quality gate, not just a type check: a
            # numeric-dtype column can still be useless for ranking --
            # entirely (or almost entirely) missing (e.g. COMPAS's
            # 'violent_recid', 100% NaN, which crashed the very first real
            # run of this: fillna(median) on an all-NaN column is still
            # NaN, and LogisticRegression rejects NaN inputs outright), or
            # an identifier column with no predictive meaning. Reuses the
            # pipeline's own max_missing_rate threshold rather than
            # inventing a new one.
            usable_cols = [
                c for c in numeric_cols
                if df[c].isna().mean() <= config.THRESHOLDS["max_missing_rate"]
                and not re.search(r'(^id$|_id$|^index$)', c, re.IGNORECASE)
            ]
            if not usable_cols or len(df) < 20:
                return None
            y = df[target]
            if y.nunique() < 2:
                return None
            X = df[usable_cols].apply(lambda s: s.fillna(s.median()))
            if X.isna().any().any():
                return None  # a column was constant/all-NaN even after the filter above
            clf = LogisticRegression(max_iter=1000)
            clf.fit(X, y)
            proba = clf.predict_proba(X)[:, 1]
            return pd.Series(np.abs(proba - 0.5), index=df.index)
        except Exception as e:
            logger.info(f"       (Preferential Sampling ranker unavailable ({e}); "
                  f"falling back to uniform-random selection for this feature)")
            return None

    def _detect_reversal(self, df_before: pd.DataFrame, df_after: pd.DataFrame,
                        column: str, target: str, min_group_calc: int = 10,
                        target_before: Optional[str] = None) -> Optional[Dict]:
        """Did the SAME group stay disadvantaged (lowest outcome rate)
        before and after mitigation, or did it flip to a different group?
        A magnitude-only disparity check (max rate - min rate) cannot
        tell these apart -- both a shrinking gap and a gap that overshot
        past zero into the opposite group show up as "the number went
        down." Returns None if either side doesn't have >=2 groups with
        enough samples to compute a rate at all (same viability floor
        used elsewhere for group-rate calculations).

        `target` is used for df_after; `target_before` (defaults to the
        same as `target`) is used for df_before -- needed for the
        post-SVM check, where df_before is self.original_df (which only
        has the real outcome column, e.g. 'is_recid') and df_after is
        self.corrected_df (which additionally has the engineered
        'svm_fair_target' column that df_before was never given). Passing
        the same column name for both when it only exists on one side
        raised a bare KeyError here on the very first real SVM run this
        was tested against -- which the SVM block's own try/except then
        silently swallowed as "SVM enforcement failed", discarding a
        successful SVM result and reproducing the exact bias_scores.final
        vs. stage_bias_scores.final mismatch the 3.1.2 fix exists to
        prevent. This method must never raise -- reversal detection is a
        diagnostic add-on, not allowed to take down SVM enforcement."""
        target_before = target_before or target

        def disadvantaged(df, col_name):
            if col_name not in df.columns:
                return None, {}
            rates = {}
            for g, sub in df.groupby(column):
                if len(sub) >= min_group_calc:
                    rates[g] = sub[col_name].mean()
            if len(rates) < 2:
                return None, {}
            return min(rates, key=rates.get), rates

        try:
            before, _rates_before = disadvantaged(df_before, target_before)
            after, rates_after = disadvantaged(df_after, target)
        except Exception as e:
            logger.warning(f"       (Reversal check unavailable for '{column}': {e})")
            return None
        if before is None or after is None:
            return None
        # v3.4.0: also report the AFTER-state max-min gap (rate points), so
        # a caller can tell a genuine large overcorrection apart from a
        # near-parity rank-order flip among several close groups -- e.g.
        # three groups that all converged within ~2.5 points of each other
        # and of the population mean can still technically swap "who's
        # lowest" from rounding noise alone, without that being the kind
        # of overshoot the Fairness Regulator exists to catch.
        after_gap = (max(rates_after.values()) - min(rates_after.values())) if rates_after else None
        return {
            "disadvantaged_before": str(before),
            "disadvantaged_after": str(after),
            "reversed": bool(before != after),
            "after_gap": after_gap,
        }

    def _max_correction_without_crossing(self, positives: float, group_size: float,
                                        overall_mean: float, direction: str) -> int:
        """v3.4.0 Fairness Regulator ('the thermostat').

        Real-data root cause this exists to fix: on COMPAS (target=
        is_recid, rebalance_method='reweighing'), the Age feature's
        disadvantaged group flipped from 'Greater than 45' (34.1% base
        rate) to 'Less than 25' (59.7% base rate, i.e. the group that
        STARTED most advantaged) after rebalancing -- reversal_checks
        flagged it correctly, but nothing had stopped the correction
        from crossing past parity in the first place. Root cause:
        Reweighing's per-(group,label) cell targets are each rounded to
        a whole number of rows independently; near parity, that
        rounding noise is enough to flip which of several near-tied
        groups is technically lowest, even though the ratio itself
        mathematically targets exact convergence to the population mean
        (Kamiran & Calders, KAIS 2012) -- it was never designed to
        overshoot PAST it. This is also a documented general risk in
        the bias-mitigation literature, not unique to this
        implementation: "fairness interventions may reverse the
        disparity problem" (see the 3.4.0 changelog for citations).

        This is the actual regulator: given a group's current positive
        count and size, and the direction a correction is about to move
        it ('add' more positives to raise a low group, or 'remove'
        positives to lower a high group), return the MAXIMUM row count
        that can be applied without the resulting rate crossing PAST
        overall_mean. Landing exactly AT the mean is allowed (that's
        the correction's own goal); going beyond it into the opposite
        group's territory is what creates a reversal, and is capped
        off -- like a thermostat cutting the heat the instant the room
        hits the setpoint, not overshooting into overheating.

        Callers clip their own naive (weight-derived, or W(g,y)-ratio-
        derived) target against this ceiling; they never raise it.
        """
        safe_mean = min(max(overall_mean, 1e-6), 1 - 1e-6)
        if group_size <= 0:
            return 0
        if direction == "add":
            # (positives + n) / (group_size + n) <= safe_mean
            max_n = (safe_mean * group_size - positives) / (1 - safe_mean)
        elif direction == "remove":
            # (positives - n) / (group_size - n) >= safe_mean
            max_n = (positives - safe_mean * group_size) / (1 - safe_mean)
        else:
            raise ValueError(f"direction must be 'add' or 'remove', got {direction!r}")
        return max(0, int(np.floor(max_n)))

    def _rebalance_feature_weighted(self, df: pd.DataFrame, column: str,
                                   target: str, weight: float,
                                   feature_name: Optional[str] = None) -> pd.DataFrame:
        """Rebalance a specific feature with weight-dependent intensity.

        v3.2.0: row SELECTION within a group is now Preferential Sampling
        (rank by decision-boundary distance) instead of uniform-random,
        and any group below config.THRESHOLDS['min_samples_per_group']
        (50) is now a hard exclusion, not just an audit-phase warning --
        see the 3.2.0 changelog entry for why (the Asian n=32 COMPAS
        subgroup was flagged as small in the audit but still silently
        rebalanced, and reversed under Preferential Sampling alone)."""
        df_balanced = df.copy()
        group_stats = df.groupby(column)[target].agg(["mean", "count"])
        overall_mean = df[target].mean()

        # FIXED: Use domain-specific max weight for normalization
        max_domain_weight = max(self.domain_weights.values()) if self.domain_weights else 0.25

        # Weight factor normalized to domain max (reflects relative importance)
        weight_factor = weight / max_domain_weight

        # Disparity threshold: higher weight = lower threshold (catch more cases)
        disparity_threshold = 0.08 * (1.5 - weight_factor)  # Range: 0.04 to 0.12

        # Removal rate: higher weight = more removal
        removal_rate = 0.05 * (1.0 + weight_factor)  # Range: 0.05 to 0.10

        # Addition rate: higher weight = more addition
        addition_rate = 0.08 * (1.0 + weight_factor)  # Range: 0.08 to 0.16

        # Minimum group size: higher weight = lower threshold (weight-derived,
        # range 15-30) -- v3.2.0: now floored against the audit's own
        # min_samples_per_group=50 threshold, so a group can no longer be
        # flagged as statistically too small in the audit and then still
        # get automatically resampled by a more permissive threshold here.
        weight_derived_min = int(30 * (1.0 - weight_factor * 0.5))  # Range: 15 to 30
        min_group_size = max(weight_derived_min, config.THRESHOLDS["min_samples_per_group"])

        # v3.2.0: fit one ranker per feature call, reused for both the
        # removal and addition branches below. Protected/mapped columns
        # are excluded from the ranker's inputs so it can't use another
        # protected attribute as a predictive proxy for this one.
        protected_cols = list(self._feature_map.values())
        boundary_dist = self._rank_by_boundary_distance(df, target, exclude_cols=protected_cols)
        method_used = "preferential_sampling" if boundary_dist is not None else "uniform_random"

        logger.info(f"\n     Rebalancing '{column}' (weight: {weight:.2f}, factor: {weight_factor:.2f})")
        logger.info(f"       • Disparity threshold: {disparity_threshold:.3f}")
        logger.info(f"       • Removal rate: {removal_rate:.3f}, Addition rate: {addition_rate:.3f}")
        logger.info(f"       • Min group size: {min_group_size} (weight-derived {weight_derived_min}, "
              f"floored at audit's min_samples_per_group={config.THRESHOLDS['min_samples_per_group']})")
        logger.info(f"       • Selection method: {method_used}")

        total_removed = 0
        total_added = 0
        excluded_small_groups = []
        regulator_capped = []

        for group, stats in group_stats.iterrows():
            group_mean = stats["mean"]
            group_size = stats["count"]

            disparate = abs(group_mean - overall_mean) > disparity_threshold
            if disparate and group_size <= min_group_size:
                excluded_small_groups.append({
                    "feature": feature_name, "column": column, "group": str(group),
                    "size": int(group_size), "floor": min_group_size,
                    "reason": "disparate but below the minimum-group-size floor -- excluded "
                              "from automatic rebalancing, needs manual review",
                })
                continue

            # Use weight-adjusted thresholds
            if disparate and group_size > min_group_size:
                group_mask = df[column] == group

                if group_mean > overall_mean:  # High outcome group
                    positives = df[group_mask & (df[target] == 1)]
                    if len(positives) > 10:
                        # Weight-dependent removal
                        remove_n = min(len(positives) // 10, int(group_size * removal_rate))
                        # v3.4.0 Fairness Regulator: never remove past the
                        # point where this group's rate would cross below
                        # overall_mean -- that's the group becoming the NEW
                        # disadvantaged one, not just "less advantaged".
                        cap = self._max_correction_without_crossing(
                            positives=len(positives), group_size=group_size,
                            overall_mean=overall_mean, direction="remove",
                        )
                        if remove_n > cap:
                            regulator_capped.append({
                                "feature": feature_name, "column": column, "group": str(group),
                                "naive_target": remove_n, "regulator_capped_to": cap,
                            })
                            remove_n = cap
                        if remove_n > 0:
                            if boundary_dist is not None:
                                # Preferential Sampling: remove the positives
                                # CLOSEST to the decision boundary first.
                                remove_idx = boundary_dist.loc[positives.index].nsmallest(remove_n).index
                            else:
                                remove_idx = positives.sample(n=remove_n, random_state=42).index
                            df_balanced = df_balanced.drop(remove_idx)
                            total_removed += remove_n

                else:  # Low outcome group
                    positives = df[group_mask & (df[target] == 1)]
                    if len(positives) > 5:
                        # Weight-dependent addition
                        add_n = min(len(positives) // 5, int(group_size * addition_rate))
                        # v3.4.0 Fairness Regulator: never add past the point
                        # where this group's rate would cross above
                        # overall_mean -- that's the group becoming the NEW
                        # advantaged one, the exact overshoot found on real
                        # COMPAS data (Age: 'Less than 25' went from most
                        # advantaged pre-mitigation to disadvantaged post-
                        # rebalancing under the un-clipped formula).
                        cap = self._max_correction_without_crossing(
                            positives=len(positives), group_size=group_size,
                            overall_mean=overall_mean, direction="add",
                        )
                        if add_n > cap:
                            regulator_capped.append({
                                "feature": feature_name, "column": column, "group": str(group),
                                "naive_target": add_n, "regulator_capped_to": cap,
                            })
                            add_n = cap
                        if add_n > 0:
                            if boundary_dist is not None:
                                # Preferential Sampling: duplicate the
                                # positives CLOSEST to the decision
                                # boundary first, with replacement if the
                                # borderline pool is smaller than add_n.
                                ranked = boundary_dist.loc[positives.index].sort_values().index
                                if add_n <= len(ranked):
                                    add_idx = ranked[:add_n]
                                else:
                                    add_idx = list(ranked) + list(
                                        np.random.RandomState(42).choice(ranked, add_n - len(ranked), replace=True)
                                    )
                                add_samples = positives.loc[add_idx]
                            else:
                                add_samples = positives.sample(n=add_n, replace=True, random_state=42)
                            # NOTE: no ignore_index=True here. remove_idx (used
                            # a few lines above, and by every later group in
                            # this same loop) is computed against the
                            # untouched input `df`'s index labels, not
                            # df_balanced's. ignore_index=True used to
                            # renumber df_balanced to a fresh 0..N-1 range on
                            # every addition, so any removal processed *after*
                            # an addition (for a different group in the same
                            # column) tried to drop index labels that had
                            # already been wiped out -- a real crash on any
                            # dataset large enough to need both an addition
                            # and a removal within one feature's rebalancing
                            # pass (e.g. the NC statewide data, ~100 counties).
                            # Keeping the original index means oversampled
                            # rows can carry duplicate index labels, which is
                            # harmless here: nothing downstream depends on
                            # this dataframe's index being unique or
                            # sequential (CSV export uses index=False, and
                            # the SVM stage resets its own index defensively
                            # before using positional lookups).
                            df_balanced = pd.concat([df_balanced, add_samples])
                            total_added += add_n

        if excluded_small_groups:
            for g in excluded_small_groups:
                logger.warning(f"       ⚠️  Excluded '{g['group']}' (n={g['size']}) -- below the "
                      f"minimum-group-size floor ({min_group_size}); needs manual review")

        if regulator_capped:
            for g in regulator_capped:
                logger.warning(f"       🌡️  Regulator capped '{g['group']}': wanted to correct "
                      f"{g['naive_target']} rows, capped to {g['regulator_capped_to']} "
                      f"to avoid crossing past the population mean")

        logger.info(f"       • Samples removed: {total_removed}, Samples added: {total_added}")

        self.rebalance_log.append({
            "feature": feature_name, "column": column, "method": method_used,
            "total_removed": total_removed, "total_added": total_added,
            "excluded_small_groups": excluded_small_groups,
            "regulator_capped": regulator_capped,
            # v3.4.0: same threshold this method already uses to decide "is
            # this feature disparate enough to touch" -- reused downstream
            # by the rebalance_gate backstop as the materiality bar for
            # "is a residual reversal big enough to be an actionable
            # regulator failure, or just near-parity rounding noise".
            "disparity_threshold": disparity_threshold,
        })

        return df_balanced

    # Keep original method for backward compatibility
    def _rebalance_feature(self, df: pd.DataFrame, column: str,
                          target: str) -> pd.DataFrame:
        """Original rebalancing (uses default weight = 0.05)"""
        return self._rebalance_feature_weighted(df, column, target, weight=0.05)

    def _rebalance_feature_reweighing(self, df: pd.DataFrame, column: str,
                                     target: str, weight: float,
                                     feature_name: Optional[str] = None) -> pd.DataFrame:
        """Reweighing (Kamiran & Calders, KAIS 2012) realized as row
        resampling. The classic formula computes, per (protected-group,
        label) cell, the ratio between the INDEPENDENT expectation (if
        group and label were unrelated) and the OBSERVED joint
        probability:

            W(g, y) = P(G=g) * P(Y=y) / P(G=g, Y=y)

        W > 1 means that cell is underrepresented relative to what
        independence would predict (e.g. too few positive outcomes in
        a disadvantaged group) and should be duplicated toward that
        target; W < 1 means overrepresented and should be thinned.
        Kamiran & Calders' own use of this ratio is as a SAMPLE WEIGHT
        fed to a downstream classifier's fit() -- it does not itself
        produce a resampled dataframe. To make it directly comparable
        to Preferential Sampling via the same corrected-dataframe /
        composite-score evaluation the rest of this pipeline uses, the
        ratio is realized here as a resampling target: each cell's row
        count is adjusted toward round(count * W) via uniform-random
        add/remove (deliberately uniform, not boundary-ranked -- that
        selection rule is Preferential Sampling's own distinct
        contribution, not Reweighing's; mixing them would blur the
        comparison). Same group-size floor as _rebalance_feature_weighted."""
        df_balanced = df.copy()
        n_total = len(df)
        overall_mean = df[target].mean()
        group_stats = df.groupby(column)[target].agg(["mean", "count"])

        max_domain_weight = max(self.domain_weights.values()) if self.domain_weights else 0.25
        weight_factor = weight / max_domain_weight
        disparity_threshold = 0.08 * (1.5 - weight_factor)
        weight_derived_min = int(30 * (1.0 - weight_factor * 0.5))
        min_group_size = max(weight_derived_min, config.THRESHOLDS["min_samples_per_group"])

        p_y1 = overall_mean
        p_y0 = 1 - overall_mean

        logger.info(f"\n     Reweighing '{column}' (weight: {weight:.2f}, factor: {weight_factor:.2f})")
        logger.info(f"       • Min group size: {min_group_size} (floored at "
              f"config.THRESHOLDS['min_samples_per_group']={config.THRESHOLDS['min_samples_per_group']})")

        total_removed = total_added = 0
        excluded_small_groups = []
        regulator_capped = []

        for group, stats in group_stats.iterrows():
            group_mean, group_size = stats["mean"], stats["count"]
            disparate = abs(group_mean - overall_mean) > disparity_threshold
            if not disparate:
                continue
            if group_size <= min_group_size:
                excluded_small_groups.append({
                    "feature": feature_name, "column": column, "group": str(group),
                    "size": int(group_size), "floor": min_group_size,
                    "reason": "disparate but below the minimum-group-size floor -- excluded "
                              "from automatic rebalancing, needs manual review",
                })
                # v3.7.0: protect this group's rows from every LATER
                # feature's resampling too, not just this feature's own --
                # a group excluded here previously could still grow or
                # shrink when a later feature (e.g. Age) resampled a cell
                # that happened to overlap with it. Confirmed on real
                # COMPAS data: Asian went 32->33 and Native American
                # 18->21 despite both being excluded from Ethnicity's OWN
                # rebalancing, because Age's rebalancing pass (the only
                # other feature resampled) touched their rows as a side
                # effect. Keyed by the stable '_biasclean_row_uid' column,
                # not the pandas index, since duplicated rows share their
                # source row's index but each keeps a unique uid.
                if "_biasclean_row_uid" in df.columns:
                    self._protected_row_uids.update(
                        df.loc[df[column] == group, "_biasclean_row_uid"].tolist()
                    )
                continue

            p_g = group_size / n_total
            group_mask = df[column] == group

            # v3.4.0 Fairness Regulator: compute BOTH cells' naive targets
            # (label=1 and label=0) together first, before applying either,
            # so the group's RESULTING rate can be checked as a whole. The
            # classic W(g,y) ratio mathematically targets exact convergence
            # to overall_mean for every group -- it should never need to
            # overshoot past it -- but each cell's target is independently
            # rounded to a whole row count, and near parity that rounding
            # noise alone is enough to flip who's technically lowest among
            # several close groups (the real root cause found on COMPAS:
            # Age's disadvantaged group flipped from 'Greater than 45' to
            # 'Less than 25' this way). Clipping the realized (post-
            # rounding) targets back to land at, not past, overall_mean
            # fixes the rounding artifact the same way it fixes a genuine
            # overshoot -- one mechanism, one root cause either way.
            n1 = int((group_mask & (df[target] == 1)).sum())
            n0 = int((group_mask & (df[target] == 0)).sum())
            if n1 == 0 and n0 == 0:
                continue

            p_gy1 = n1 / n_total
            p_gy0 = n0 / n_total
            target_n1 = int(round(n1 * ((p_g * p_y1) / p_gy1))) if p_gy1 > 0 else n1
            target_n0 = int(round(n0 * ((p_g * p_y0) / p_gy0))) if p_gy0 > 0 else n0

            total_target = target_n1 + target_n0
            naive_new_rate = target_n1 / total_target if total_target > 0 else group_mean
            crosses_past_mean = (
                (group_mean <= overall_mean and naive_new_rate > overall_mean) or
                (group_mean > overall_mean and naive_new_rate < overall_mean)
            )
            if crosses_past_mean and total_target > 0:
                safe_mean = min(max(overall_mean, 1e-6), 1 - 1e-6)
                capped_n1 = int(round(total_target * safe_mean))
                capped_n0 = total_target - capped_n1
                regulator_capped.append({
                    "feature": feature_name, "column": column, "group": str(group),
                    "naive_target_rate": round(naive_new_rate, 4),
                    "regulator_capped_to_rate": round(capped_n1 / total_target, 4),
                })
                target_n1, target_n0 = capped_n1, capped_n0

            for label, n_cell, target_n in ((1, n1, target_n1), (0, n0, target_n0)):
                if n_cell == 0:
                    continue
                delta = target_n - n_cell
                cell_mask = group_mask & (df[target] == label)

                # v3.7.0: never pick a protected row (excluded by an
                # earlier feature, this run) as a duplication source or a
                # removal candidate -- see the excluded_small_groups
                # branch above for why. A protected row can still be
                # PRESENT in this cell (it stays exactly as it was); it
                # just can't be chosen as the row that changes.
                protected_uids = getattr(self, "_protected_row_uids", set())
                if protected_uids and "_biasclean_row_uid" in df.columns:
                    eligible_mask = cell_mask & (~df["_biasclean_row_uid"].isin(protected_uids))
                else:
                    eligible_mask = cell_mask

                if delta > 0:
                    # Underrepresented cell -- duplicate rows up toward target_n.
                    cell_rows = df[eligible_mask]
                    if len(cell_rows) == 0:
                        continue  # every candidate row is protected -- skip this cell
                    add_idx = np.random.RandomState(42).choice(cell_rows.index, delta, replace=True)
                    df_balanced = pd.concat([df_balanced, df.loc[add_idx]])
                    total_added += delta
                elif delta < 0:
                    # Overrepresented cell -- remove rows down toward target_n.
                    remove_n = min(-delta, n_cell - 1)  # never remove the whole cell
                    cell_rows = df[eligible_mask]
                    remove_n = min(remove_n, len(cell_rows))  # can't remove more than eligible
                    if remove_n > 0:
                        remove_idx = cell_rows.sample(n=remove_n, random_state=42).index
                        df_balanced = df_balanced.drop(remove_idx)
                        total_removed += remove_n

        if excluded_small_groups:
            for g in excluded_small_groups:
                logger.warning(f"       ⚠️  Excluded '{g['group']}' (n={g['size']}) -- below the "
                      f"minimum-group-size floor ({min_group_size}); needs manual review")
        if regulator_capped:
            for g in regulator_capped:
                logger.warning(f"       🌡️  Regulator capped '{g['group']}': naive target rate "
                      f"{g['naive_target_rate']:.3f} would cross past the population mean, "
                      f"capped to {g['regulator_capped_to_rate']:.3f}")
        logger.info(f"       • Samples removed: {total_removed}, Samples added: {total_added}")

        self.rebalance_log.append({
            "feature": feature_name, "column": column, "method": "reweighing",
            "total_removed": total_removed, "total_added": total_added,
            "excluded_small_groups": excluded_small_groups,
            "regulator_capped": regulator_capped,
            "disparity_threshold": disparity_threshold,
        })

        return df_balanced

    def validate_industry_readiness(self, df_before: pd.DataFrame,
                                   df_after: pd.DataFrame,
                                   diagnostic_results: Dict) -> Dict:
        """Validate mitigation results with proper disparity calculation"""
        validation = {
            "fairness_improvement": {},
            "absolute_disparity_reduction": {},
            "initial_disparities": {},
            "final_disparities": {},
            # PHASE 3.5, Workstream C: worst-single-group view, computed
            # alongside the existing mean/CV-based view so a report never
            # shows only the aggregate number -- see the method's own
            # comment for the North Carolina Ethnicity case that motivated
            # this.
            "initial_worst_group": {},
            "final_worst_group": {},
            "initial_worst_group_deviation": {},
            "final_worst_group_deviation": {},
            "worst_group_improvement_pct": {},
            "data_integrity": {
                "records_before": len(df_before),
                "records_after": len(df_after),
                "retention_rate": (len(df_after) / len(df_before)) * 100
            }
        }

        target = diagnostic_results.get("target_column_used")
        feature_tests = diagnostic_results.get("feature_tests", {})

        for feature, test_result in feature_tests.items():
            # Only calculate improvements for features that were actually mitigated
            if not test_result.get("significant_bias", False):
                continue

            # Get the actual column name from the test results
            column_name = test_result.get("column_name")
            if not column_name or column_name not in df_before.columns:
                continue

            # Calculate disparity using the actual column name
            before = self._calculate_disparity_direct(df_before, column_name, target)
            after = self._calculate_disparity_direct(df_after, column_name, target)

            validation["initial_disparities"][feature] = before
            validation["final_disparities"][feature] = after

            before_worst_group, before_worst_dev = self._calculate_worst_group_deviation_direct(
                df_before, column_name, target
            )
            after_worst_group, after_worst_dev = self._calculate_worst_group_deviation_direct(
                df_after, column_name, target
            )
            validation["initial_worst_group"][feature] = before_worst_group
            validation["final_worst_group"][feature] = after_worst_group
            validation["initial_worst_group_deviation"][feature] = before_worst_dev
            validation["final_worst_group_deviation"][feature] = after_worst_dev
            if before_worst_dev > 0:
                validation["worst_group_improvement_pct"][feature] = (
                    (before_worst_dev - after_worst_dev) / before_worst_dev
                ) * 100

            if before > 0:
                # Percentage improvement
                improvement = ((before - after) / before) * 100
                validation["fairness_improvement"][feature] = improvement

                # Absolute reduction
                absolute_reduction = before - after
                validation["absolute_disparity_reduction"][feature] = absolute_reduction

        return validation

    def _calculate_disparity_direct(self, df: pd.DataFrame, column: str,
                                  target_column: str) -> float:
        """Calculate disparity directly without feature map lookup"""
        if column not in df.columns or target_column not in df.columns:
            return 0.0

        try:
            group_rates = {}
            for group in df[column].unique():
                if pd.isna(group):
                    continue
                group_data = df[df[column] == group]
                if len(group_data) >= 10:
                    rate = group_data[target_column].mean()
                    group_rates[str(group)] = rate

            if len(group_rates) < 2:
                return 0.0

            rates = np.array(list(group_rates.values()))
            mean_rate = np.mean(rates)

            if mean_rate == 0:
                return 0.0

            cv_disparity = np.std(rates) / mean_rate
            return min(cv_disparity, 1.0)

        except Exception:
            return 0.0

    # PHASE 3.5, Workstream C: BiasClean's own disparity_final has always
    # been a coefficient-of-variation figure -- the spread across ALL
    # groups averaged together. That average can improve even while the
    # single worst-off group gets worse (confirmed on real data during the
    # Phase 3 benchmark: North Carolina's Ethnicity feature improved
    # +40.5% on this CV/mean basis while its single worst group actually
    # regressed -9.1%, and this was only caught because an external judge
    # happened to compute both views -- BiasClean's own reporting didn't).
    # This method reuses the exact same group-rate computation and 10-
    # sample floor as _calculate_disparity_direct above, so the two numbers
    # are always computed from an identical group definition and are
    # directly comparable -- this is a visibility addition, not a
    # different disparity definition; disparity_final's own meaning and
    # value are completely unchanged by this method's existence.
    def _calculate_worst_group_deviation_direct(self, df: pd.DataFrame, column: str,
                                                 target_column: str):
        """Return (worst_group_name, worst_group_relative_deviation) --
        the single group whose rate deviates furthest from the feature's
        own mean rate, as a fraction of that mean. None, 0.0 if there
        aren't at least 2 groups clearing the 10-sample floor."""
        if column not in df.columns or target_column not in df.columns:
            return None, 0.0

        try:
            group_rates = {}
            for group in df[column].unique():
                if pd.isna(group):
                    continue
                group_data = df[df[column] == group]
                if len(group_data) >= 10:
                    group_rates[str(group)] = group_data[target_column].mean()

            if len(group_rates) < 2:
                return None, 0.0

            mean_rate = np.mean(list(group_rates.values()))
            if mean_rate == 0:
                return None, 0.0

            worst_group, worst_rate = max(
                group_rates.items(), key=lambda kv: abs(kv[1] - mean_rate)
            )
            worst_deviation = min(abs(worst_rate - mean_rate) / mean_rate, 1.0)
            return worst_group, worst_deviation

        except Exception:
            return None, 0.0

    # PHASE 3.5, Workstream B: BiasClean's composite mitigation threshold
    # (0.05) is a single fixed number applied regardless of sample size or
    # group count -- a given percentage-point gap can be highly reliable
    # at n=20 million and pure noise at n=30, and the fixed threshold
    # can't tell the difference. This method implements the standard log
    # relative-risk confidence interval (the "Katz method"), a special
    # case of the general asymptotic result in Besse, del Barrio,
    # Gordaliza & Loubes, "Confidence Intervals for Testing Disparate
    # Impact in Fair Learning" (arXiv:1807.06362, 2018) -- their Theorem
    # 3.1 gives the exact asymptotic variance of a disparate-impact ratio
    # estimator via the delta method; for two disjoint groups (BiasClean's
    # case -- a group's rate is never counted in another group's
    # denominator), that reduces to this well-established closed form.
    # This is reporting-only for now, per the Phase 3.5 SOP: it adds a
    # second, sample-size-aware significance lens alongside the existing
    # fixed threshold, and does not yet change requires_mitigation's own
    # decision -- that migration (an explicit opt-in mode, matching the
    # Audit-First/Legacy/Audit-Only pattern already in this pipeline) is
    # deliberately a separate, later step so every existing result stays
    # reproducible under today's default in the meantime.
    def _worst_group_ratio_ci_direct(self, df: pd.DataFrame, column: str,
                                      target_column: str, alpha: float = 0.05,
                                      min_group_size: int = 10,
                                      effect_size_floor: float = 0.8):
        """Log relative-risk CI (Katz method) for the feature's worst
        group versus its largest (reference) group. Returns a dict:
        {reference_group, worst_group, ratio, ci_lower, ci_upper,
        ci_excludes_parity, practically_significant,
        dual_criteria_significant} or None if there aren't at least 2
        groups clearing min_group_size, or if either group's rate is 0 or
        1 (the log-ratio SE is undefined at the boundary -- BiasClean's
        own regulator-capping logic elsewhere in this file hits the same
        edge case for the same reason).

        ci_excludes_parity is True when the 95%-default CI does not
        contain 1.0 -- i.e. this specific group's gap is statistically
        distinguishable from chance at its own actual sample size, not
        merely large in raw percentage-point terms.

        PHASE 3.5, Workstream B part 2: ci_excludes_parity alone is not
        enough to decide whether a gap is worth acting on. Verified on
        real data (Oklahoma City, v3.9.1): a 0.2% gap at n=945,107 is
        statistically real (CI excludes parity) but not remotely
        practically meaningful -- the classic large-sample problem where
        statistical and practical significance diverge. practically_
        significant pairs the CI test with an effect-size floor that
        does NOT depend on sample size: effect_size_floor defaults to
        0.8, the "four-fifths rule" (Feldman et al. 2015; also Aequitas's
        own default threshold, tau=0.8) -- a group's ratio to the
        reference group must fall at or below 0.8 (or, symmetrically, at
        or above 1/0.8=1.25) to count as practically significant,
        regardless of how large n is. This project's own Phase 3 report
        (Section 3.3) already documents that the four-fifths rule's
        legal, not statistical, origin makes it a weak choice used ALONE
        (Watkins & Chen, 2024) -- but paired with a genuine statistical
        test rather than substituting for one, it is exactly the
        standard "statistically AND practically significant" combination
        used throughout applied statistics precisely to avoid a pure
        significance test flagging a trivial effect at large n.
        dual_criteria_significant is True only when BOTH criteria agree;
        this is the field intended to eventually inform requires_
        mitigation, once that migration is made (still not done as of
        this release -- see the changelog)."""
        if column not in df.columns or target_column not in df.columns:
            return None
        try:
            groups = {}
            for group in df[column].unique():
                if pd.isna(group):
                    continue
                group_data = df[df[column] == group]
                n = len(group_data)
                if n < min_group_size:
                    continue
                rate = group_data[target_column].mean()
                groups[str(group)] = (rate, n)

            if len(groups) < 2:
                return None

            reference_group = max(groups, key=lambda g: groups[g][1])
            p_ref, n_ref = groups[reference_group]
            if p_ref <= 0 or p_ref >= 1:
                return None

            worst_group, worst_ratio_dev = None, -1.0
            for g, (p_g, n_g) in groups.items():
                if g == reference_group or p_g <= 0 or p_g >= 1:
                    continue
                ratio = p_g / p_ref
                dev = abs(np.log(ratio)) if ratio > 0 else float("inf")
                if dev > worst_ratio_dev:
                    worst_group, worst_ratio_dev = g, dev

            if worst_group is None:
                return None

            p_worst, n_worst = groups[worst_group]
            ratio = p_worst / p_ref
            se_log_ratio = np.sqrt(
                (1 - p_worst) / (n_worst * p_worst) + (1 - p_ref) / (n_ref * p_ref)
            )
            z = norm.ppf(1 - alpha / 2)
            log_ratio = np.log(ratio)
            ci_lower = np.exp(log_ratio - z * se_log_ratio)
            ci_upper = np.exp(log_ratio + z * se_log_ratio)

            ci_excludes_parity = bool(ci_upper < 1.0 or ci_lower > 1.0)
            practically_significant = bool(
                ratio <= effect_size_floor or ratio >= (1.0 / effect_size_floor)
            )

            return {
                "reference_group": reference_group,
                "worst_group": worst_group,
                "ratio": ratio,
                "ci_lower": ci_lower,
                "ci_upper": ci_upper,
                "ci_excludes_parity": ci_excludes_parity,
                "practically_significant": practically_significant,
                "dual_criteria_significant": bool(ci_excludes_parity and practically_significant),
            }
        except Exception:
            return None

"""# Part 2"""

# ============================================================================
# 5. VISUALIZATION ENGINE
# ============================================================================
class VisualizationEngine:
    """Generate the bias-analysis charts as in-memory base64 PNGs for
    direct embedding in report.pdf, rather than writing separate .png
    files to disk. This is part of the v3.1 reporting consolidation:
    previously each chart was its own standalone file
    (disparity_comparison.png, fairness_improvements.png,
    data_integrity.png) alongside 11 other output files, which was easy
    for a user to partially lose track of when sharing results. Now
    there is nothing to lose -- the charts live inside the one report."""

    def __init__(self):
        sns.set_style("whitegrid")
        plt.rcParams['figure.figsize'] = (12, 6)

    def _fig_to_base64(self, fig) -> str:
        """Render a matplotlib figure to an in-memory base64 PNG string."""
        import io, base64
        buf = io.BytesIO()
        fig.savefig(buf, format='png', dpi=150, bbox_inches='tight')
        buf.seek(0)
        encoded = base64.b64encode(buf.read()).decode('ascii')
        plt.close(fig)
        return encoded

    def plot_disparity_comparison(self, original_df: pd.DataFrame,
                                  corrected_df: pd.DataFrame,
                                  feature_map: Dict, target: str) -> Optional[str]:
        """Before/after outcome rate comparison, one row per protected
        feature with its own axes. (Overlaying every feature on one
        shared axis -- the earlier behavior -- made features with
        different category counts collide on the same x-positions and
        only the last feature's category labels would display.)
        Returns a base64-encoded PNG, or None if there's nothing to plot."""
        plotted_features = [(feature, column) for feature, column in feature_map.items()
                            if column in original_df.columns and column in corrected_df.columns]
        if not plotted_features:
            return None

        n_features = len(plotted_features)
        fig, axes = plt.subplots(n_features, 2, figsize=(14, 4.5 * n_features), squeeze=False)

        for row, (feature, column) in enumerate(plotted_features):
            for col, (df, title) in enumerate([(original_df, "Before Mitigation"),
                                               (corrected_df, "After Mitigation")]):
                ax = axes[row][col]
                rates = df.groupby(column)[target].mean()
                rates.plot(kind='bar', ax=ax, alpha=0.8, color='#4C72B0')
                ax.set_title(f"{feature} — {title}", fontsize=12, fontweight='bold')
                ax.set_ylabel("Outcome Rate", fontsize=10)
                ax.set_xlabel(feature, fontsize=10)
                ax.axhline(y=df[target].mean(), color='#e74c3c', linestyle='--',
                          label='Overall Mean', alpha=0.6)
                ax.legend(loc='upper right', fontsize=8)
                plt.setp(ax.xaxis.get_majorticklabels(), rotation=40, ha='right', fontsize=8)

        plt.tight_layout()
        return self._fig_to_base64(fig)

    def plot_feature_improvements(self, validation_results: Dict) -> Optional[str]:
        """Bar chart of % improvement per protected feature. Returns a
        base64-encoded PNG, or None if there's nothing to plot."""
        improvements = validation_results.get("fairness_improvement", {})
        if not improvements:
            return None

        fig, ax = plt.subplots(figsize=(9, max(3, 0.8 * len(improvements) + 1)))

        features = list(improvements.keys())
        values = list(improvements.values())
        colors = ['#2ecc71' if v > 0 else '#e74c3c' for v in values]

        ax.barh(features, values, color=colors, alpha=0.85)
        ax.axvline(x=0, color='black', linestyle='-', linewidth=0.8)
        ax.set_xlabel('Improvement (%)', fontsize=11)
        ax.set_title('Fairness Improvement by Protected Feature',
                    fontsize=13, fontweight='bold')
        ax.grid(axis='x', alpha=0.3)

        for i, v in enumerate(values):
            ax.text(v + (1 if v > 0 else -1), i, f'{v:+.1f}%',
                   va='center', ha='left' if v > 0 else 'right', fontsize=9)

        plt.tight_layout()
        return self._fig_to_base64(fig)

    def plot_data_integrity(self, validation_results: Dict) -> Optional[str]:
        """Before/after record-count bar chart. Returns a base64-encoded PNG."""
        integrity = validation_results.get("data_integrity", {})

        fig, ax = plt.subplots(figsize=(7, 5))

        before = integrity.get("records_before", 0)
        after = integrity.get("records_after", 0)
        retention = integrity.get("retention_rate", 100)

        ax.bar(['Before Mitigation', 'After Mitigation'],
               [before, after], color=['#3498db', '#2ecc71'], alpha=0.85)

        ax.set_ylabel('Number of Records', fontsize=11)
        ax.set_title(f'Data Integrity: Record Count (Retention: {retention:.1f}%)',
                    fontsize=13, fontweight='bold')

        for i, v in enumerate([before, after]):
            ax.text(i, v + (max(before, after) * 0.02), f'{v:,}',
                   ha='center', va='bottom', fontsize=10)

        plt.tight_layout()
        return self._fig_to_base64(fig)

# ============================================================================
# 6. REPORT GENERATOR
# ============================================================================

class ReportGenerator:
    """Generate the BiasClean report package.

    v3.1 reporting redesign: this used to produce biasclean_report.html
    (a single technical/jargon-heavy page), a separate GOVERNANCE_REPORT.txt,
    and 3 separate chart PNGs -- on top of 6 more JSON files written
    elsewhere (see UniversalBiasClean._save_results). That's 11+ files
    for one run, several of them near-duplicates of each other, and it
    was easy for a user to open/share only some of them and miss the
    rest. This class now produces exactly ONE offline, printable PDF
    report (rendered from HTML/CSS via xhtml2pdf -- see generate_report)
    with two sections: a plain-language summary (traffic light, what
    was checked, charts, what to do next -- no jargon, no p-values) for
    people without a CS/stats background, and a "Technical Detail"
    section, starting on its own page, with the full statistical trail
    for whoever the case gets escalated to. The remaining raw numbers (everything that
    used to be spread across 6 separate v27_exports/*.json files) are
    merged into one audit_trail.json alongside the corrected dataset --
    that pair is the 3rd, machine-readable layer, not meant to be
    browsed file-by-file by a person.
    """

    def __init__(self, config=None):
        self.config = config or DOMAIN_CONFIGS["justice"]

    # ------------------------------------------------------------------
    # Plain-language helpers
    # ------------------------------------------------------------------

    @staticmethod
    def _humanize(name: str) -> str:
        """CamelCase -> spaced words, e.g. 'SocioeconomicStatus' -> 'Socioeconomic Status'."""
        return re.sub(r'(?<!^)(?=[A-Z])', ' ', name)

    @staticmethod
    def _plain_reason(reason: str) -> str:
        """Translate one PreMitigationAuditor rationale string into a
        plain-language sentence. Any pattern that isn't recognized is
        returned as-is rather than dropped, so nothing silently vanishes."""
        if not reason:
            return ""
        m = re.match(r"Insufficient records:\s*(\d+)\s*<\s*(\d+)", reason)
        if m:
            return (f"The dataset only has {m.group(1)} records, fewer than the {m.group(2)} "
                     f"needed for a statistically reliable analysis.")
        m = re.match(r"Excessive missing data:\s*([\d.]+)%", reason)
        if m:
            return f"{m.group(1)}% of the data is missing -- too much to analyze reliably."
        m = re.match(r"Bias score\s*([\d.]+)\s*>\s*0\.30", reason)
        if m:
            return f"The gap in outcomes between groups was severe (score {m.group(1)} of 1.0) before any correction."
        m = re.match(r"Moderate bias:\s*([\d.]+)", reason)
        if m:
            return f"There was a moderate gap in outcomes between groups (score {m.group(1)} of 1.0) before any correction."
        m = re.match(r"Vulnerable groups:\s*(\d+)", reason)
        if m:
            n = m.group(1)
            return (f"{n} smaller or disadvantaged group{'s' if n != '1' else ''} were flagged as "
                     f"deserving individual review before relying on the rebalanced data.")
        m = re.match(r"Acceptable baseline: bias=([\d.]+), vulnerable=(\d+)", reason)
        if m:
            return f"The starting gap between groups was small (score {m.group(1)}) with no vulnerable groups needing special attention."
        return reason

    @staticmethod
    def _detect_mapping_conflicts(mappings: Dict, selected_columns: Optional[Dict[str, str]] = None) -> List[str]:
        """Surface cases where more than one original column matched
        the same canonical feature (or more than one column matched as
        a candidate outcome variable).

        v3.10.4: this message used to assert the tie was "chosen by its
        position in the file rather than by confidence" -- unconditionally,
        even when it wasn't true. That claim was stale: it describes the
        pre-v3.6.7 last-wins-overwrite behavior, not the confidence-then-
        p-value-based ranking _select_best_column_per_feature has used
        since (file order is now only the last-resort fallback for a
        genuine coin-flip tie). Confirmed wrong on real data twice
        (HMDA's Ethnicity tie, German Credit's SocioeconomicStatus tie)
        -- both were actually decided by confidence/p-value, not position.
        Fixed: state which column was actually selected (from
        selected_columns, i.e. results['features'][feature]['column'])
        instead of asserting a specific, unverified mechanism.

        v3.10.6 (open item 3): for Ethnicity specifically, a losing
        candidate isn't always a redundant duplicate of the winner --
        HMDA's derived_race vs. derived_ethnicity tie is the real-data
        case that surfaced this: ACS/HMDA-style data represents race and
        Hispanic origin as two genuinely distinct variables, and this
        pipeline has only one weighted Ethnicity slot (adding a second
        would mean a new protected-attribute category with its own
        evidence-based weight, out of scope here -- see open item 3's
        resolution notes). Rather than silently dropping the non-selected
        candidate's own finding, its own p-value/significance (already
        computed during validation, just previously discarded after
        selection) is now surfaced alongside the winner's, so a reader
        can see whether the excluded column also shows a notable pattern
        worth a manual look -- informational only, doesn't change which
        column is used or add any new weight.
        """
        by_feature: Dict[str, list] = {}
        for col, m in mappings.items():
            feature = m.get("feature")
            if feature in (None, "__exclude__"):
                continue
            by_feature.setdefault(feature, []).append((col, m))
        warnings = []
        for feature, cols in by_feature.items():
            if len(cols) > 1:
                cols_sorted = sorted(cols, key=lambda x: x[1].get("confidence", 0), reverse=True)
                cols_str = ", ".join(f"{c} ({m.get('confidence', 0):.0%})" for c, m in cols_sorted)
                label = "the outcome variable" if feature == "__outcome__" else f"'{feature}'"
                winner = (selected_columns or {}).get(feature)
                winner_txt = (
                    f"'{winner}' was used for the actual analysis (based on statistical "
                    f"evidence and mapping confidence together, not simply which one was listed first)."
                    if winner else
                    "Only one is actually used for the analysis."
                )
                msg = (
                    f"{len(cols)} columns were all matched to {label}: {cols_str}. "
                    f"{winner_txt} Double-check this is the column you intended."
                )
                if feature not in ("__outcome__",) and winner:
                    for col, m in cols_sorted:
                        if col == winner:
                            continue
                        stats = (m.get("validation", {}) or {}).get("statistics", {}) or {}
                        p_value = stats.get("p_value")
                        if p_value is not None:
                            sig_txt = "statistically significant on its own" if p_value < 0.05 else "not statistically significant on its own"
                            msg += (
                                f" For transparency: the non-selected '{col}' was also individually "
                                f"tested (p={p_value:.4g}, {sig_txt}) -- this doesn't feed into the "
                                f"composite score above, but is worth a manual look if '{col}' "
                                f"represents a genuinely distinct concept (e.g. Hispanic origin vs. "
                                f"race) rather than a duplicate of '{winner}'."
                            )
                warnings.append(msg)
        return warnings

    def _plain_feature_findings(self, results: Dict) -> List[Dict]:
        """One plain-language finding per protected feature, sorted by
        domain weight (most important first)."""
        diagnostics = results.get("diagnostics", {})
        validation = results.get("validation", {})
        feature_map = results.get("feature_map", {})
        group_rates_initial = diagnostics.get("group_rates_initial", {})
        group_rates_final = results.get("group_rates_final", {})
        weights = self.config.get("weights", {})
        feature_tests = diagnostics.get("feature_tests", {})
        improvements = validation.get("fairness_improvement", {})

        findings = []
        for feature in sorted(feature_map.keys(), key=lambda f: weights.get(f, 0), reverse=True):
            rates_before = group_rates_initial.get(feature, {})
            if not rates_before or len(rates_before) < 2:
                continue
            rates_after = group_rates_final.get(feature, {})
            hi_group, hi_rate = max(rates_before.items(), key=lambda x: x[1])
            lo_group, lo_rate = min(rates_before.items(), key=lambda x: x[1])
            gap_before = (hi_rate - lo_rate) * 100
            gap_after = None
            if rates_after and len(rates_after) >= 2:
                gap_after = (max(rates_after.values()) - min(rates_after.values())) * 100
            findings.append({
                "feature": self._humanize(feature),
                "column": feature_map[feature],
                "hi_group": hi_group, "hi_rate": hi_rate * 100,
                "lo_group": lo_group, "lo_rate": lo_rate * 100,
                "gap_before": gap_before,
                "gap_after": gap_after,
                # v3.6.6 FIX: max()/min() both return the FIRST key they
                # encounter holding the extreme value. When every group's
                # rate is exactly tied (hi_rate == lo_rate, i.e. zero
                # variance -- confirmed on real Oklahoma City traffic-stop
                # data: outcome positive_rate 99.8%, so almost every
                # protected-feature group landed at ~100%), hi_group and
                # lo_group end up being the SAME key, and the template
                # below used to print "28.0 had a 100.0% outcome rate,
                # compared to 28.0 at 100.0%" -- a group compared to
                # itself, reading as a glitch to a no-code user. Flagged
                # here so the template can render an honest "no variation"
                # sentence instead of a self-comparison.
                "no_variation": hi_group == lo_group,
                "significant": feature_tests.get(feature, {}).get("significant_bias", False),
                "improved_pct": improvements.get(feature),
                "weight": weights.get(feature, 0.05),
            })
        return findings

    # ------------------------------------------------------------------
    # Main report
    # ------------------------------------------------------------------

    def generate_report(self, results: Dict, output_file: str = "biasclean_results/report.pdf",
                        charts: Dict[str, str] = None) -> str:
        """Build the single report as an offline, printable PDF (via
        xhtml2pdf, rendering the same HTML/CSS this method always
        built -- there's no separate PDF template to maintain). PDF
        rather than HTML because this is a scientific/governance
        document: it needs to print, paginate, and be archived/cited
        without a browser. `charts` maps a display title to a
        base64-encoded PNG string (from VisualizationEngine).

        The Summary and Technical Detail sections are both always
        visible here (no click-to-expand -- that's a browser-only
        interaction with no PDF equivalent); Technical Detail simply
        starts on its own page via a CSS page-break."""
        charts = charts or {}
        diagnostics = results.get("diagnostics", {})
        validation = results.get("validation", {})
        mappings = results.get("mappings", {})
        domain_weights = self.config.get("weights", {})
        deployment_info = results.get('deployment_info', {})
        deployment_decision = deployment_info.get('deployment_decision', {}) if deployment_info else {}
        audit = results.get('v3_audit') or results.get('audit') or {}
        rec = audit.get('recommendation', {})
        domain_label = self.config["report_labels"]["domain"]

        initial_bias = diagnostics.get("initial_bias_score", 0)
        final_bias = diagnostics.get("final_bias_score", initial_bias)
        improvement = ((initial_bias - final_bias) / initial_bias * 100) if initial_bias > 0 else 0

        traffic_light = rec.get('traffic_light', '')
        plain_action = {
            "🟢 GREEN": "No blocking concerns were found. The rebalanced data can move forward, "
                        "though a human review is still good practice.",
            "🟡 YELLOW": "Some concerns were found. Have someone with fairness/statistics expertise "
                         "review this before the data or any model built on it is used in production.",
            "🔴 RED": "Do not use this data or model yet. Serious problems were found that need to "
                      "be fixed first.",
        }.get(traffic_light, rec.get('action', 'Review recommended.'))
        badge_color = {"🟢 GREEN": "#2ecc71", "🟡 YELLOW": "#f39c12", "🔴 RED": "#e74c3c"}.get(traffic_light, "#95a5a6")
        # No emoji here -- the PDF renderer's default font has no
        # color-emoji glyphs, so an emoji renders as a blank/missing-glyph
        # box. The badge's background color already carries the
        # green/yellow/red meaning, so a plain text label is enough.
        light_word = {"🟢 GREEN": "Looks OK", "🟡 YELLOW": "Review Needed", "🔴 RED": "Do Not Use"}.get(traffic_light, re.sub(r'[^\w\s]', '', traffic_light).strip() or "Not Audited")

        plain_reasons = [self._plain_reason(r) for r in rec.get('rationale', []) if r]

        # BUG FIX (v3.1.3): "Why this recommendation" was sourced only from
        # the PRE-mitigation traffic-light audit's rationale (rec['rationale']),
        # which is computed before rebalancing/SVM ever run. SVM enforcement
        # happens later in the pipeline and its worsened-fairness finding
        # (already correctly captured in results['svm_validation'] and in
        # audit_trail.json's svm_enforcement block since the v3.1.2 fix) was
        # never fed back into this list. Net effect: a run where SVM made
        # bias dramatically WORSE (e.g. COMPAS: 0.066 -> 0.445, -370%) showed
        # the correct number on the summary page but then said "No specific
        # concerns were logged" directly underneath it -- the one plain-
        # language section a no-code user reads had no idea anything was
        # wrong. This affects both legacy and audit_first mode, since
        # plain_reasons is built the same way in either case.
        svm_validation_for_reasons = results.get('svm_validation', {})
        # v3.3.0: the validation gate now auto-rejects a worsening SVM result
        # and falls back to the rebalanced stage (see svm_gate below), so this
        # message is reworded to describe what WOULD have happened and that
        # the pipeline already protected against it, rather than telling the
        # user to manually consider disabling SVM.
        if svm_validation_for_reasons.get('svm_worsened_fairness'):
            pre_svm = svm_validation_for_reasons.get('pre_svm_bias_score')
            # v3.10.10 FIX: read raw_svm_bias_score (the actual classifier
            # output, set once and never overwritten) instead of
            # post_svm_bias_score, which the v3.6.2 gate-rejection fix
            # intentionally overwrites to match pre_svm_bias_score -- using
            # it here made this sentence always read "from X to X", hiding
            # the real regression the sentence exists to describe. Falls
            # back to post_svm_bias_score for older-shaped svm_validation
            # dicts (e.g. skipped/disabled paths) that never set the new key.
            post_svm = svm_validation_for_reasons.get(
                'raw_svm_bias_score', svm_validation_for_reasons.get('post_svm_bias_score')
            )
            pre_txt = f"{pre_svm:.3f}" if isinstance(pre_svm, (int, float)) else "unknown"
            post_txt = f"{post_svm:.3f}" if isinstance(post_svm, (int, float)) else "unknown"
            gate_caught_it = (results.get('svm_gate', {}) or {}).get('accepted') is False
            plain_reasons.append(
                f"SVM fairness enforcement made the measured bias score WORSE, not "
                f"better (from {pre_txt} after rebalancing to {post_txt} after SVM). " +
                (
                    "The v3.3.0 validation gate automatically caught this and REJECTED "
                    "the classifier result -- the final predictions use the rebalanced "
                    "stage, not the worse classifier output."
                    if gate_caught_it else
                    "This did not trigger the validation gate (see svm_gate in "
                    "audit_trail.json for why); review before relying on this result."
                )
            )

        # v3.3.0: surface a gate rejection even when svm_worsened_fairness
        # alone wasn't the trigger (e.g. rejected solely for a new reversal).
        svm_gate_for_reasons = results.get('svm_gate', {}) or {}
        if svm_gate_for_reasons.get('accepted') is False and not svm_validation_for_reasons.get('svm_worsened_fairness'):
            plain_reasons.append(
                f"VALIDATION GATE REJECTED THE CLASSIFIER RESULT: "
                f"{svm_gate_for_reasons.get('reason', 'see svm_gate in audit_trail.json')}. "
                f"The final predictions use the rebalanced stage instead."
            )

        # v3.10.4: surface an accurate reason in the plain-language "Why
        # this recommendation" section (the one part of the PDF a
        # no-code user is expected to actually read) when no mitigation
        # was attempted specifically because the combined score stayed
        # under 0.05 despite one or more individually significant
        # features -- otherwise this section falls back to "No specific
        # concerns were logged" directly underneath a "Significant
        # Biases: 2" figure elsewhere in the same report, the same
        # contradiction already fixed in the console log's Reason: line.
        # Only the composite-below-threshold reason is surfaced here
        # (not the genuine no-bias-at-all case), since that's the one
        # that reads as a false all-clear.
        if not svm_validation_for_reasons.get('svm_applied') and 'combined score' in (svm_validation_for_reasons.get('reason') or ''):
            plain_reasons.append(svm_validation_for_reasons['reason'])

        # v3.4.0: Fairness Regulator backstop -- surface it if the proactive
        # clip in rebalancing didn't fully prevent a reversal. Unlike the
        # SVM gate, this is a FLAG not an auto-fallback (see rebalance_gate's
        # docstring in the orchestrator for why), so the wording says
        # "needs manual review", not "the pipeline corrected this for you".
        rebalance_gate_for_reasons = results.get('rebalance_gate', {}) or {}
        if rebalance_gate_for_reasons.get('accepted') is False:
            plain_reasons.append(
                f"FAIRNESS REGULATOR FLAG: {rebalance_gate_for_reasons.get('reason', 'see rebalance_gate in audit_trail.json')}. "
                f"This was NOT automatically corrected -- review the flagged feature(s) before "
                f"relying on their rebalanced rates."
            )

        # BUG FIX / FEATURE (v3.2.0): same plain-language-injection pattern
        # as the SVM-worsened-fairness reason above, for reversal detection.
        # A magnitude-only disparity number can't distinguish "the gap
        # shrank toward zero" from "the gap overshot past zero into the
        # opposite group" -- both look like the number went down. Without
        # this, a reversed group would show up as an apparent improvement
        # with nothing in the plain-language summary to say who is now
        # actually disadvantaged.
        all_reversal_checks = dict(results.get('reversal_checks', {}) or {})
        for feature, svm_check in (results.get('svm_reversal_checks', {}) or {}).items():
            if svm_check:
                all_reversal_checks[f"{feature} (after SVM)"] = svm_check

        # BUG FIX (v3.5.1): this loop used to flag EVERY reversed check with
        # the same alarming "This is overcorrection, not fairness: review
        # before relying on this result" wording -- including rebalancing-
        # stage reversals that rebalance_gate's own materiality filter had
        # already judged as near-parity rounding noise (accepted=True,
        # listed in near_parity_reversals, NOT in reversed_features). Real
        # COMPAS run confirmed this: Age showed reversed=True with an
        # after_gap of 2.55 points against its own 7.2-point
        # disparity_threshold -- rebalance_gate correctly held it as
        # non-actionable, but the PDF's plain-language section printed the
        # same "overcorrection... review before relying on this result"
        # sentence as it would for a genuine, actionable reversal, directly
        # contradicting the gate's own verdict one section above it. Only
        # rebalancing-stage checks can be near-parity (svm_gate has no
        # materiality filter -- it's a hard accept/reject), so only the
        # non-"(after SVM)" entries are eligible for the softer wording.
        near_parity_features = set(rebalance_gate_for_reasons.get('near_parity_reversals', []) or [])
        disparity_threshold_by_feature = {
            entry.get('feature'): entry.get('disparity_threshold')
            for entry in (results.get('rebalance_log', []) or [])
            if entry.get('feature')
        }
        for feature, check in all_reversal_checks.items():
            if not (check and check.get('reversed')):
                continue
            is_svm_stage = '(after SVM)' in feature
            base_feature = feature.split(' (')[0]
            # v3.10.6 FIX (open item 9): SVM-stage reversals used to be
            # printed here unconditionally, even when svm_gate had
            # already REJECTED the SVM result entirely -- meaning the
            # delivered result uses the rebalanced stage, not SVM, so
            # these reversals never actually apply to what's being
            # recommended. Real-data case: Governance's classifier
            # collapsed and was rejected (5 new reversals: Age, Gender,
            # DisabilityStatus, MigrationStatus, Ethnicity), yet all 6
            # "(after SVM)" reversal lines still printed under "Why this
            # recommendation" with "review before relying on this
            # result" -- directly implying they're part of the delivered
            # output when they're from a discarded attempt. The earlier
            # "VALIDATION GATE REJECTED THE CLASSIFIER RESULT" message
            # (see svm_gate_for_reasons block above) already tells the
            # reader the SVM attempt was thrown out and why; individually
            # re-litigating each of its reversals here just contradicts
            # that message. Skipped entirely rather than reworded, so
            # this section reflects only what the delivered
            # (rebalanced-stage) result actually contains, per Hamid's
            # explicit framing of this open item.
            if is_svm_stage and svm_gate_for_reasons.get('accepted') is False:
                continue
            if not is_svm_stage and base_feature in near_parity_features:
                after_gap = check.get('after_gap')
                threshold = disparity_threshold_by_feature.get(base_feature)
                gap_txt = f"{after_gap * 100:.1f} percentage points" if isinstance(after_gap, (int, float)) else "a small amount"
                threshold_txt = (f" (below this feature's own {threshold * 100:.1f}-point disparity threshold)"
                                  if isinstance(threshold, (int, float)) else "")
                plain_reasons.append(
                    f"{self._humanize(base_feature)}: the disadvantaged group technically changed "
                    f"from '{check.get('disadvantaged_before')}' to '{check.get('disadvantaged_after')}' "
                    f"after rebalancing, but the gap between groups is now only {gap_txt}{threshold_txt} "
                    f"-- essentially parity, not a real reversal. The fairness regulator held this "
                    f"position and did not flag it as actionable."
                )
            else:
                plain_reasons.append(
                    f"{self._humanize(base_feature)}{' (after SVM)' if is_svm_stage else ''}: "
                    f"the disadvantaged group REVERSED, not just narrowed -- "
                    f"'{check.get('disadvantaged_before')}' had the lower outcome rate before "
                    f"mitigation, but '{check.get('disadvantaged_after')}' does now. This is "
                    f"overcorrection, not fairness: review before relying on this result."
                )

        selected_columns = {
            feature: fdata.get("column")
            for feature, fdata in (results.get("features", {}) or {}).items()
            if fdata.get("column")
        }
        mapping_conflicts = self._detect_mapping_conflicts(mappings, selected_columns)
        findings = self._plain_feature_findings(results)

        findings_html = ""
        for f in findings:
            gap_after_txt = ""
            if f["gap_after"] is not None:
                # v3.6.5 FIX: this used to be a plain narrowed/widened binary
                # ("narrowed" if strictly less, else "widened"), so a gap
                # that stayed EXACTLY the same (gap_after == gap_before)
                # fell into the "else" branch and was reported as
                # "widened" -- factually wrong, since nothing changed.
                # Found on real NIJ data (v3.6.4 confirmation run): mitigation
                # was correctly skipped (composite score under the 0.05
                # requires_mitigation threshold -- see the v3.6.4 changelog
                # entry), so gap_after == gap_before for every one of the 4
                # features, and report.pdf told a no-code reader "that gap
                # widened to 2.3 percentage points" for a gap that never
                # moved. Rounded display could also mask a genuine tiny
                # change (e.g. 2.34 -> 2.35 both display as "2.3"), so this
                # compares the ROUNDED (1-decimal) values -- the same
                # precision the reader actually sees -- so the wording can
                # never contradict its own displayed numbers (e.g. calling
                # it "widened to 2.3" when gap_before also displays as
                # "2.3"), whether the underlying floats are bit-identical
                # (no mitigation ran) or merely round to the same tenth.
                gap_before_r = round(f["gap_before"], 1)
                gap_after_r = round(f["gap_after"], 1)
                if gap_after_r == gap_before_r:
                    direction = "stayed essentially unchanged at"
                else:
                    direction = "narrowed to" if gap_after_r < gap_before_r else "widened to"
                gap_after_txt = f" After rebalancing, that gap {direction} <strong>{f['gap_after']:.1f} percentage points</strong>."
            sig_txt = ("This gap was unlikely to be due to chance." if f["significant"]
                       else "This gap could plausibly be due to chance alone.")
            if f.get("no_variation"):
                # v3.6.6: every group tied at the exact same rate -- state
                # that plainly instead of comparing a group to itself
                # (see the "no_variation" comment in _plain_feature_findings
                # for the real Oklahoma City data that surfaced this).
                comparison_txt = (
                    f"Before any correction, every group had the same "
                    f"<strong>{f['hi_rate']:.1f}%</strong> outcome rate — no gap to compare."
                )
            else:
                comparison_txt = (
                    f"Before any correction, <strong>{f['hi_group']}</strong> had a {f['hi_rate']:.1f}% outcome rate, "
                    f"compared to <strong>{f['lo_group']}</strong> at {f['lo_rate']:.1f}% — a gap of "
                    f"<strong>{f['gap_before']:.1f} percentage points</strong>.{gap_after_txt}"
                )
            findings_html += f"""
                <div class="finding-card">
                    <h4>{f['feature']} <span class="weight-badge">column: {f['column']}</span></h4>
                    <p>{comparison_txt}</p>
                    <p class="muted">{sig_txt}</p>
                </div>
            """
        if not findings_html:
            findings_html = "<p>No protected-feature comparisons were available to summarize.</p>"

        charts_html = ""
        for title, b64 in charts.items():
            if b64:
                charts_html += f"""
                <div class="chart-block">
                    <h4>{title}</h4>
                    <img src="data:image/png;base64,{b64}" alt="{title}" />
                </div>
                """

        conflicts_html = ""
        if mapping_conflicts:
            items = "".join(f"<li>{c}</li>" for c in mapping_conflicts)
            conflicts_html = f"""
                <div class="section warn-box">
                    <h3>Mapping ties detected</h3>
                    <p class="muted">More than one column matched the same category below. This doesn't mean
                    anything broke, but it's worth a quick sanity check.</p>
                    <ul>{items}</ul>
                </div>
            """

        reasons_html = "".join(f"<li>{r}</li>" for r in plain_reasons) or "<li>No specific concerns were logged.</li>"

        # ---- Technical section (same underlying numbers, full detail) ----
        tech_mapping_rows = ""
        for col, m in mappings.items():
            feature = m.get("feature", "Unknown")
            weight = domain_weights.get(feature, "N/A")
            weight_display = f"{weight:.2f}" if isinstance(weight, (int, float)) else weight
            tech_mapping_rows += (f"<tr><td>{col}</td><td><strong>{feature}</strong></td>"
                                  f"<td>{weight_display}</td><td>{m.get('confidence', 0) * 100:.0f}%</td>"
                                  f"<td>{m.get('tier', 'unknown')}</td></tr>")

        tech_test_rows = ""
        for feature, test in diagnostics.get("feature_tests", {}).items():
            weight = domain_weights.get(feature, "N/A")
            weight_display = f"{weight:.2f}" if isinstance(weight, (int, float)) else weight
            tech_test_rows += (f"<tr><td><strong>{feature}</strong></td><td>{weight_display}</td>"
                               f"<td>{test.get('test_used', 'N/A')}</td><td>{test.get('p_value', 1.0):.6f}</td>"
                               f"<td>{test.get('threshold_used', 0):.3f}</td>"
                               f"<td>{'Yes' if test.get('significant_bias') else 'No'}</td></tr>")

        tech_improvement_rows = ""
        for feature, imp in sorted(validation.get("fairness_improvement", {}).items(),
                                    key=lambda x: domain_weights.get(x[0], 0), reverse=True):
            weight = domain_weights.get(feature, "N/A")
            weight_display = f"{weight:.2f}" if isinstance(weight, (int, float)) else weight
            tech_improvement_rows += (f"<tr><td><strong>{feature}</strong></td><td>{weight_display}</td>"
                                      f"<td class=\"{'success' if imp > 0 else 'error'}\">{imp:+.1f}%</td></tr>")

        integrity = validation.get("data_integrity", {})
        deploy_reasons = "".join(f"<li>{r}</li>" for r in deployment_decision.get("reasons", []))
        deploy_warnings = "".join(f"<li>{w}</li>" for w in deployment_decision.get("warnings", []))

        # v3.6.1 FIX: built as a plain string here (not inline in the big
        # f-string below) specifically to avoid nesting double-quoted
        # literals inside an f-string that's itself delimited with """ --
        # see changelog for the syntax trap that caused. When
        # deployment_decision is empty (e.g. Legacy mode, which never runs
        # Phase 3.5's pre-mitigation audit), this now says so explicitly
        # instead of letting every deployment_decision.get(key, default)
        # fall back silently and render as if it were a real result.
        if deployment_decision:
            deployment_section_html = (
                f"<p><strong>Recommended:</strong> {'Yes' if deployment_decision.get('recommended') else 'No'} &nbsp;"
                f"<strong>Score:</strong> {deployment_decision.get('score', 0)}/100 &nbsp;"
                f"<strong>Confidence:</strong> {deployment_decision.get('confidence', 'low').upper()} &nbsp;"
                f"<strong>Risk level:</strong> {deployment_decision.get('risk_factors', {}).get('risk_level', 'unknown').upper()}</p>"
                + (f"<p><strong>Reasons:</strong></p><ul>{deploy_reasons}</ul>" if deploy_reasons else "")
                + (f"<p><strong>Warnings:</strong></p><ul>{deploy_warnings}</ul>" if deploy_warnings else "")
            )
        else:
            deployment_section_html = (
                "<p class='muted'>Not computed in this run -- deployment scoring only runs in "
                "Audit-First or Audit-Only mode (Phase 3.5 pre-mitigation audit). This run used a "
                "mode that skips that audit, so no score, confidence, or risk level was ever "
                "calculated. This is NOT a score of zero or failing -- treat it as not applicable, "
                "not as a result.</p>"
            )

        feature_interactions = results.get("feature_interactions", {})

        interactions_html = ""
        if feature_interactions:
            interactions_html = f"""
                <p><strong>Improved:</strong> {', '.join(feature_interactions.get('improved_features', [])) or 'none'}<br>
                <strong>Worsened:</strong> {', '.join(feature_interactions.get('worsened_features', [])) or 'none'}<br>
                <strong>Compensatory trade-off detected:</strong> {'Yes' if feature_interactions.get('compensatory_pattern_detected') else 'No'}</p>
                <p class="muted">{feature_interactions.get('note', '')}</p>
            """

        html_content = f"""<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<title>BiasClean Report - {domain_label}</title>
<style>
    @page {{ size: A4; margin: 2cm; }}
    body {{ font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; color: #222; }}
    .header {{ background-color: #5f6bc4; color: white; padding: 30px; border-radius: 10px; margin-bottom: 25px; }}
    .header p {{ margin: 4px 0; opacity: 0.9; }}
    .section {{ background: white; padding: 20px 25px; margin-bottom: 18px; border-radius: 8px; border: 1px solid #eee; page-break-inside: avoid; }}
    .badge {{ display: inline-block; padding: 10px 22px; border-radius: 24px; font-size: 20px; font-weight: bold; color: white; background: {badge_color}; }}
    .metric-table {{ width: 100%; border-collapse: separate; border-spacing: 8px 0; margin-top: 16px; }}
    .metric-table td {{ background: #f8f9fa; padding: 15px 25px; border-left: 4px solid #667eea; border-bottom: none; width: 33%; }}
    .metric-value {{ font-size: 24px; font-weight: bold; color: #333; }}
    .metric-label {{ font-size: 13px; color: #666; margin-top: 4px; }}
    .finding-card {{ border: 1px solid #eee; border-left: 4px solid #667eea; border-radius: 6px; padding: 14px 18px; margin-bottom: 14px; background: #fafbff; page-break-inside: avoid; }}
    .finding-card h4 {{ margin: 0 0 8px 0; }}
    .weight-badge {{ display: inline-block; background: #e3f2fd; color: #1976d2; padding: 2px 8px; border-radius: 12px; font-size: 11px; margin-left: 8px; font-weight: normal; }}
    .chart-block {{ margin: 20px 0; text-align: center; page-break-inside: avoid; }}
    .chart-block img {{ max-width: 100%; border-radius: 6px; border: 1px solid #eee; }}
    .warn-box {{ border-left: 4px solid #f39c12; background: #fffaf0; }}
    .muted {{ color: #666; font-size: 14px; }}
    table {{ width: 100%; border-collapse: collapse; margin-top: 12px; }}
    th, td {{ padding: 10px; text-align: left; border-bottom: 1px solid #ddd; font-size: 13px; }}
    th {{ background-color: #667eea; color: white; }}
    tr {{ page-break-inside: avoid; }}
    .success {{ color: #27ae60; font-weight: bold; }}
    .error {{ color: #e74c3c; font-weight: bold; }}
    .tech-section {{ page-break-before: always; }}
    .tech-header {{ font-size: 20px; font-weight: bold; padding: 12px 0; color: #444; border-bottom: 3px solid #667eea; margin-bottom: 18px; }}
    .footer {{ text-align: center; color: #888; margin-top: 30px; padding: 15px; font-size: 12px; }}
    .next-steps {{ background: #f0f4ff; border-radius: 6px; padding: 16px 20px; }}
</style>
</head>
<body>
    <div class="header">
        <h1>{self.config["report_labels"]["title"]}</h1>
        <p>Generated: {datetime.now().strftime('%Y-%m-%d %H:%M:%S')} &nbsp;|&nbsp; Domain: {domain_label}</p>
    </div>

    <div class="section">
        <h2>Summary</h2>
        <p><span class="badge">{light_word}</span></p>
        <p style="font-size:16px; margin-top:16px;">{plain_action}</p>
        <table class="metric-table"><tr>
            <td><div class="metric-value">{initial_bias:.2f} → {final_bias:.2f}</div><div class="metric-label">Overall bias score (0 = no gap, lower is better)</div></td>
            <td><div class="metric-value">{improvement:+.0f}%</div><div class="metric-label">Improvement after rebalancing</div></td>
            <td><div class="metric-value">{integrity.get('records_before', 0):,} → {integrity.get('records_after', 0):,}</div><div class="metric-label">Records before → after</div></td>
        </tr></table>
        <h3 style="margin-top:24px;">Why this recommendation</h3>
        <ul>{reasons_html}</ul>
    </div>

    <div class="section">
        <h2>What we found, in plain terms</h2>
        {findings_html}
    </div>

    {f'<div class="section">{charts_html}</div>' if charts_html else ''}

    {conflicts_html}

    <div class="section next-steps">
        <h3>Next steps</h3>
        <p>{'Consult a fairness/statistics expert and review the technical detail below before using this data or any model trained on it.' if traffic_light != '🟢 GREEN' else 'A human review is still recommended before deployment, even though no blocking issues were found.'}</p>
    </div>

    <div class="tech-section">
        <div class="tech-header">Technical Detail (for expert / escalation review)</div>

        <div class="section">
            <h3>Deployment Decision</h3>
            {deployment_section_html}
        </div>

        <div class="section">
            <h3>Feature Mappings &amp; Weights</h3>
            <table><tr><th>Original Column</th><th>Mapped Feature</th><th>Weight</th><th>Confidence</th><th>Tier</th></tr>
            {tech_mapping_rows}</table>
        </div>

        <div class="section">
            <h3>Statistical Tests</h3>
            <table><tr><th>Feature</th><th>Weight</th><th>Test Used</th><th>P-Value</th><th>Threshold Used</th><th>Significant</th></tr>
            {tech_test_rows}</table>
        </div>

        <div class="section">
            <h3>Fairness Improvement by Feature</h3>
            <table><tr><th>Feature</th><th>Weight</th><th>Improvement</th></tr>
            {tech_improvement_rows}</table>
        </div>

        <div class="section">
            <h3>Feature Interactions / Trade-offs</h3>
            {interactions_html or '<p class="muted">No interaction data available.</p>'}
        </div>

        <div class="section">
            <h3>Data Integrity</h3>
            <p>Records before: {integrity.get('records_before', 0):,} &nbsp;|&nbsp; Records after: {integrity.get('records_after', 0):,} &nbsp;|&nbsp; Retention: {integrity.get('retention_rate', 100):.1f}%</p>
        </div>

        <div class="section">
            <p class="muted">Full machine-readable numbers (per-stage bias scores, per-group rates, sampling attribution log)
            are available in <code>biasclean_results/audit_trail.json</code>, alongside <code>corrected_dataset.csv</code>.</p>
        </div>
    </div>

    <div class="footer">
        <p>Generated by BiasClean — Hierarchical Taxonomy + Constraint Validation Framework</p>
        <p>Full data package: report.pdf (this file) · corrected_dataset.csv · audit_trail.json</p>
    </div>
</body>
</html>
"""

        os.makedirs(os.path.dirname(output_file) or ".", exist_ok=True)

        # Render straight from the HTML/CSS above to PDF -- one source
        # of truth for both the on-screen layout and the printed
        # document, no separate PDF template to keep in sync.
        #
        # Uses xhtml2pdf, not WeasyPrint. WeasyPrint needs native
        # Pango/Cairo/GDK-Pixbuf libraries installed at the OS level --
        # `pip install weasyprint` succeeds, but rendering then throws
        # an OSError the moment it's actually used, because those
        # native libraries aren't on the system. That's an install step
        # per OS that this tool can't do for the user, and it kept
        # failing in the field. xhtml2pdf is pure Python (built on
        # reportlab) -- zero native dependencies, so if `pip install`
        # succeeds, rendering works too. Trade-off: weaker CSS support
        # (no gradients/inline-block/flexbox), which is why the CSS
        # above uses a plain background color + an actual <table> for
        # the metrics row instead of relying on those.
        #
        # Still falls back to writing the .html directly if PDF
        # rendering throws for any reason, so a broken dependency never
        # means the user gets NO report at all.
        try:
            from xhtml2pdf import pisa
            with open(output_file, "wb") as f:
                result = pisa.CreatePDF(html_content, dest=f)
            if result.err:
                raise RuntimeError(f"xhtml2pdf reported {result.err} rendering error(s)")
            logger.info(f"Report saved to: {output_file}")
            return output_file
        except Exception as e:
            fallback_file = re.sub(r'\.pdf$', '.html', output_file, flags=re.IGNORECASE)
            if fallback_file == output_file:
                fallback_file = output_file + ".html"
            with open(fallback_file, 'w', encoding='utf-8') as f:
                f.write(html_content)
            if isinstance(e, ImportError):
                logger.warning(f"   ⚠️  xhtml2pdf not installed (pip install xhtml2pdf) -- wrote {fallback_file} instead.")
            else:
                logger.warning(f"   ⚠️  PDF rendering failed ({e}) -- wrote {fallback_file} instead.")
            return fallback_file

    def print_console_report(self, results: Dict):
        """Print comprehensive console report with v2.7 enhancements"""
        logger.info("\n" + "="*80)
        logger.info(f"BIASCLEAN ANALYSIS REPORT v{__version__}")
        logger.info("="*80)

        diagnostics = results.get("diagnostics", {})
        validation = results.get("validation", {})
        deployment_info = results.get("deployment_info", {})
        deployment_decision = deployment_info.get('deployment_decision', {}) if deployment_info else {}

        # v2.7 Enhanced data
        monitoring = results.get("monitoring", {})
        enhanced_analysis = monitoring.get("enhanced_analysis", {})

        # Executive Summary
        logger.info("\n📊 EXECUTIVE SUMMARY")
        logger.info("-"*80)

        initial_bias = diagnostics.get("initial_bias_score", 0)
        final_bias = diagnostics.get("final_bias_score", initial_bias)
        improvement = ((initial_bias - final_bias) / initial_bias * 100) if initial_bias > 0 else 0

        logger.info(f"Initial Bias Score:     {initial_bias:.4f}")
        logger.info(f"Final Bias Score:       {final_bias:.4f}")
        logger.info(f"Overall Improvement:    {improvement:+.1f}%")
        logger.info(f"Significant Biases:     {diagnostics.get('significant_bias_count', 0)}")

        # v2.7: Deployment Decision
        if deployment_decision:
            logger.info("\n🎯 DEPLOYMENT DECISION (v2.7)")
            logger.info("-"*80)
            recommendation = deployment_decision.get("recommended", False)
            score = deployment_decision.get("score", 0)
            confidence = deployment_decision.get("confidence", "low")

            status_icon = "✅" if recommendation else "❌"
            logger.info(f"{status_icon} Recommendation:    {'DEPLOY' if recommendation else 'DO NOT DEPLOY'}")
            logger.info(f"  Score:              {score}/100")
            logger.info(f"  Confidence:         {confidence.upper()}")

            reasons = deployment_decision.get("reasons", [])
            if reasons:
                logger.info(f"  Reasons:")
                for reason in reasons[:3]:  # Show top 3 reasons
                    logger.info(f"    • {reason}")

            warnings = deployment_decision.get("warnings", [])
            if warnings:
                logger.info(f"  Warnings:")
                for warning in warnings[:3]:  # Show top 3 warnings
                    logger.warning(f"    ⚠️  {warning}")

        # Data Integrity
        integrity = validation.get("data_integrity", {})
        logger.info(f"\n💾 DATA INTEGRITY")
        logger.info("-"*80)
        logger.info(f"Records Before:         {integrity.get('records_before', 0):,}")
        logger.info(f"Records After:          {integrity.get('records_after', 0):,}")
        logger.info(f"Retention Rate:         {integrity.get('retention_rate', 100):.1f}%")

        # v2.7: Enhanced Monitoring Summary
        if enhanced_analysis:
            logger.info(f"\n🔍 v2.7 ENHANCED MONITORING")
            logger.info("-"*80)

            # Feature-level tracking
            feature_export = enhanced_analysis.get('feature_level_export', {})
            if feature_export.get('features'):
                logger.info(f"Feature-level tracking: {len(feature_export.get('features', {}))} features across 3 stages")

            # Group rates
            group_export = enhanced_analysis.get('group_rates_export', {})
            if group_export:
                logger.info(f"Group rates analysis:  Available for all protected groups")

            # Statistical confidence
            stats_export = enhanced_analysis.get('statistical_confidence_export', {})
            if stats_export:
                logger.info(f"Statistical confidence: Bootstrap confidence intervals calculated")

            # Sampling attribution
            sampling_export = enhanced_analysis.get('sampling_attribution_export', {})
            if sampling_export:
                logger.info(f"Sampling attribution:  Tracked rebalancing and SVM changes")

            # Trade-off analysis
            trade_offs = enhanced_analysis.get('trade_off_analysis', {})
            if trade_offs:
                logger.info(f"Trade-off analysis:    {len(trade_offs)} feature interactions analyzed")

        # Feature Improvements with Weights
        improvements = validation.get("fairness_improvement", {})
        if improvements:
            logger.info(f"\n📈 FAIRNESS IMPROVEMENTS BY FEATURE (Weight-Prioritized)")
            logger.info("-"*80)
            # Sort by weight
            sorted_improvements = sorted(
                improvements.items(),
                key=lambda x: self.config["weights"].get(x[0], 0),
                reverse=True
            )
            for feature, imp_value in sorted_improvements:
                weight = self.config["weights"].get(feature, "N/A")
                icon = "✅" if imp_value > 0 else "⚠️"
                weight_display = f"{weight:.2f}" if isinstance(weight, (int, float)) else weight
                logger.info(f"{icon} {feature:25} Weight: {weight_display:<6} {imp_value:+.1f}%")

        # Statistical Tests
        feature_tests = diagnostics.get("feature_tests", {})
        if feature_tests:
            logger.info(f"\n🧪 STATISTICAL TESTS")
            logger.info("-"*80)
            # Sort by weight
            sorted_tests = sorted(
                feature_tests.items(),
                key=lambda x: self.config["weights"].get(x[0], 0),
                reverse=True
            )
            for feature, test in sorted_tests[:5]:  # Show top 5
                p_val = test.get("p_value", 1.0)
                sig = test.get("significant_bias", False)
                weight = self.config["weights"].get(feature, "N/A")
                weight_display = f"{weight:.2f}" if isinstance(weight, (int, float)) else weight
                sig_icon = "🔴" if sig else "🟢"
                logger.info(f"{sig_icon} {feature:25} p={p_val:.6f}  Weight: {weight_display}")

        # Mappings Summary
        mappings = results.get("mappings", {})
        logger.info(f"\n🗺️  FEATURE MAPPINGS")
        logger.info("-"*80)
        logger.info(f"Total Approved:         {len(mappings)}")

        tier_counts = {}
        for mapping in mappings.values():
            tier = mapping.get("tier", "unknown")
            tier_counts[tier] = tier_counts.get(tier, 0) + 1

        for tier, count in tier_counts.items():
            icon = "🏆" if tier == "universal" else "🎯" if tier == "domain" else "📝"
            logger.info(f"  {icon} {tier.title():15}  {count}")

        # Output files summary -- v3.1 consolidation: exactly 3 files
        # now (report.pdf + corrected_dataset.csv + audit_trail.json),
        # replacing the earlier spread of 11+ separate files.
        logger.info(f"\n💾 OUTPUT FILES")
        logger.info("-"*80)
        logger.info("  • biasclean_results/report.pdf            - Summary (plain-language) + Technical Detail (expert)")
        logger.info("  • biasclean_results/corrected_dataset.csv - Rebalanced dataset")
        logger.info("  • biasclean_results/audit_trail.json      - Full machine-readable numbers for reproducibility/compliance")

        logger.info(f"\n" + "="*80)
        logger.info("PIPELINE COMPLETE")
        logger.info("="*80)

# ============================================================================
# 6.5. SVM FAIRNESS ENFORCER (INTEGRATED FROM svmfairnessenforcer.py)
# ============================================================================

class SVMFairnessEnforcer:
    """
    SVM-based fairness enforcement module for integration into BiasClean pipeline.
    Implements margin-based boundary adjustment with domain-aware feature weighting.
    """

    def __init__(self, domain_weights: Dict[str, float], random_state: int = 42,
                 svm_method: str = "fair_reduction", fairness_constraint: str = "equalized_odds"):
        """
        Initialize SVM fairness enforcer with domain-specific weights.

        Args:
            domain_weights: Dictionary of feature importance weights from DOMAIN_CONFIGS
            random_state: Random seed for reproducibility
            svm_method: v3.3.0 -- "fair_reduction" (default) wraps this
                same SVC in fairlearn's ExponentiatedGradient (Agarwal
                et al., ICML 2018), which retrains it to optimize
                accuracy SUBJECT TO an explicit fairness constraint --
                fixing the root problem the old "legacy" path had (no
                fairness term anywhere in training, so nothing stopped
                it from making things worse). "legacy" is the original
                vanilla-SVM behavior, kept for direct comparison.
            fairness_constraint: "equalized_odds" (default, Hardt/
                Price/Srebro 2016) or "demographic_parity". Only used
                when svm_method="fair_reduction".
        """
        self.domain_weights = domain_weights
        self.random_state = random_state
        self.svm_method = svm_method
        self.fairness_constraint = fairness_constraint
        self.model = None
        self.feature_columns = None

        # SVM configuration optimized for fairness-aware classification - FIXED
        self.svm_config = {
            'kernel': 'linear',      # FIXED: Linear for interpretability & SPEED
            'C': 0.01,               # FIXED: Strong regularization
            'probability': True,
            'class_weight': 'balanced',  # KEEP this for now
            'random_state': self.random_state
            # REMOVE max_iter and cache_size for compatibility
        }

    def _prepare_features(self, df: pd.DataFrame, feature_map: Dict[str, str],
                          target_column: str, group_column: Optional[str] = None,
                          all_protected_columns: Optional[List[str]] = None) -> Tuple[pd.DataFrame, np.ndarray, np.ndarray]:
        """
        Prepare features for SVM training with proper leakage prevention.
        Protected attributes are EXCLUDED from features to prevent direct bias.

        Args:
            df: Input DataFrame (BiasClean corrected data)
            feature_map: Mapping of protected features to column names (ONE
                column per canonical feature -- see all_protected_columns)
            target_column: Target outcome variable
            group_column: Protected attribute for fairness monitoring (optional)
            all_protected_columns: v3.5.0 -- feature_map only remembers ONE
                raw column per canonical feature, so when several raw
                columns are approved-mapped to the SAME feature (e.g. real
                COMPAS: 'dob', 'age', AND 'age_cat' all map to "Age", but
                feature_map only keeps 'age_cat'), the others silently kept
                reaching the classifier as ordinary predictors -- a real
                protected-attribute leak through an unmapped alias column,
                found by directly inspecting what the classifier was
                actually training on (['id', 'age', 'c_days_from_compas']
                on real COMPAS data -- 'age' should never have been there).
                Pass every approved-mapped raw column here (from
                UniversalBiasClean.all_protected_columns) so ALL of them get
                excluded, not just the one feature_map happens to remember.

        Returns:
            Tuple of (feature_matrix, target_labels, group_labels)
        """
        X = df.copy()

        # Step 1: Extract and remove target variable (CRITICAL: prevents data leakage)
        if target_column not in X.columns:
            raise ValueError(f"Target column '{target_column}' not found in DataFrame")
        y = X[target_column].astype(int).values
        X = X.drop(columns=[target_column])

        # Step 2: Extract group labels for fairness monitoring (DO NOT retain as feature)
        group_labels = None
        protected_columns = []

        if group_column and group_column in X.columns:
            group_labels = X[group_column].astype(str).values

        # Step 3: Identify ALL protected attribute columns for exclusion --
        # both feature_map's one-per-feature columns AND (v3.5.0) every
        # OTHER raw column approved-mapped to the same or any other
        # protected feature (see all_protected_columns docstring above).
        for protected_feature, column_name in feature_map.items():
            if column_name in X.columns and column_name not in protected_columns:
                protected_columns.append(column_name)
        for column_name in (all_protected_columns or []):
            if column_name in X.columns and column_name not in protected_columns:
                protected_columns.append(column_name)

        # Step 4: Identify and remove problematic columns
        exclude_cols = []

        # ================================
        # EDUCATION DOMAIN LEAKAGE FIX
        # ================================
        # In OULAD, y_true is derived directly from final_result (Pass/Fail/Withdrawn/Distinction)
        # If final_result stays in X, SVM sees the label proxy → 100% accuracy (leakage).
        if 'final_result' in X.columns:
            exclude_cols.append('final_result')


        # Remove identifier columns. v3.5.0 FIX: the substring list below
        # ('_id', 'id_', ...) never matched a column literally named just
        # "id" (no underscore) -- found by directly inspecting what the SVM
        # was actually training on for real COMPAS data: ['id', 'age',
        # 'c_days_from_compas']. A raw row identifier was reaching the
        # classifier as an ordinary numeric feature. _rank_by_boundary_
        # distance already handles this correctly via a whole-word regex
        # (r'(^id$|_id$|^index$)') -- reused here for consistency instead
        # of maintaining two different id-detection rules in one file.
        id_patterns = ['_id', 'id_', 'name', 'date', 'time', 'timestamp', 'case_number']
        for col in X.columns:
            col_lower = col.lower()
            if any(pattern in col_lower for pattern in id_patterns) or \
               re.search(r'(^id$|^index$)', col_lower):
                exclude_cols.append(col)

        # Remove high-cardinality string columns (>50 unique values)
        for col in X.select_dtypes(include=['object']).columns:
            if col not in exclude_cols and X[col].nunique() > 50:
                exclude_cols.append(col)

        # Remove COMPAS-specific leakage features
        leakage_patterns = [
            'decile', 'score_text', 'c_charge_degree', 'r_charge_degree',
            'v_score_text', 'type_of_assessment', 'v_type_of_assessment',
            'two_year_recid', 'violent_recid', 'is_violent_recid',
            'vr_charge_degree', 'v_decile_score', 'event', 'r_days_from_arrest',
            # NEW ADDITIONS CRITICAL FOR FAIRNESS:
            'svm_',  # Excludes svm_margin, svm_y_pred, etc.
            'event', 'end', 'start',  # Time-based leakage
            'priors_count', 'juv_',  # Direct recidivism predictors
            'charge_',  # Charge-related leakage
            '_date', '_time'  # Temporal data
        ]
        for col in X.columns:
            col_lower = col.lower()
            if any(pattern in col_lower for pattern in leakage_patterns):
                exclude_cols.append(col)

        # Remove date columns that encode outcome timing
        date_patterns = ['_date', '_in', '_out', 'screening', 'custody']
        for col in X.columns:
            col_lower = col.lower()
            if any(pattern in col_lower for pattern in date_patterns):
                exclude_cols.append(col)

        # Remove criminal history features that directly predict recidivism
        criminal_history = ['priors_count', 'juv_fel_count', 'juv_misd_count',
                          'juv_other_count', 'priors_count.1']
        for col in criminal_history:
            if col in X.columns:
                exclude_cols.append(col)

        # CRITICAL FIX: Remove SVM-related columns that shouldn't exist yet
        # (These would be leftovers from previous runs or test data issues)
        svm_leakage_patterns = ['svm_', '_margin', '_prob', '_pred', 'margin_']
        for col in X.columns:
            col_lower = col.lower()
            if any(pattern in col_lower for pattern in svm_leakage_patterns):
                if col not in exclude_cols:
                    exclude_cols.append(col)

        # Remove time-based leakage columns (duplicate check for safety)
        time_patterns = ['event', 'end', 'start', '_date', '_time', 'timestamp']
        for col in X.columns:
            col_lower = col.lower()
            if any(pattern in col_lower for pattern in time_patterns):
                if col not in exclude_cols:
                    exclude_cols.append(col)

        # CRITICAL FIX: Exclude ALL protected attribute columns from features
        for protected_col in protected_columns:
            if protected_col not in exclude_cols and protected_col in X.columns:
                exclude_cols.append(protected_col)

        # v3.6.0 STATISTICAL LEAKAGE CHECK: near-perfect target-proxy columns
        # that no name-based pattern list could anticipate. Real-data finding
        # (NC statewide traffic stops, 20.3M rows, target='citation_issued'):
        # 'outcome' (3-category: citation/warning/arrest) and 'warning_issued'
        # (boolean) are alternate encodings of the exact same underlying
        # decision as the target -- neither matched any keyword in
        # id_patterns/leakage_patterns/svm_leakage_patterns above (all tuned
        # to COMPAS's vocabulary: decile_score, charge_degree, priors_count,
        # etc.), so both reached the SVM as ordinary predictors. One-hot
        # encoding 'outcome' produces an 'outcome_citation' dummy that is a
        # literal copy of the label. Confirmed via a real run: 100.0% full-
        # dataset AND validation accuracy on 20.3M rows -- not achievable by
        # a genuine classifier on this task, and it silently made
        # svm_gate.accepted=True mean nothing (the classifier just replayed
        # the target back through its proxy column; pre/post bias scores
        # were bit-identical because svm_fair_target ended up equal to
        # biasclean_target row-for-row). Keyword lists can't be expected to
        # anticipate every dataset's naming convention for "the same
        # decision, phrased differently" -- especially once BiasClean starts
        # seeing datasets outside COMPAS-style recidivism (stop/search data,
        # other domains). Checked statistically instead, independent of
        # column name: any remaining low-cardinality column (<=20 distinct
        # values, observed on a large-enough share of rows to be meaningful)
        # whose per-value majority class alone predicts y with >= 98% purity
        # is excluded as a near-perfect target proxy.
        LEAKAGE_PURITY_THRESHOLD = 0.98
        MIN_LEAKAGE_CHECK_COVERAGE = 0.5  # column must be observed on >=50% of rows to count
        for col in list(X.columns):
            if col in exclude_cols or col not in X.columns:
                continue
            try:
                nunique = X[col].nunique(dropna=True)
            except TypeError:
                continue
            if nunique < 2 or nunique > 20:
                continue
            try:
                crosstab = pd.crosstab(X[col].astype(str), y)
            except Exception:
                continue
            total_observed = crosstab.values.sum()
            if total_observed == 0 or total_observed < MIN_LEAKAGE_CHECK_COVERAGE * len(y):
                continue
            purity = crosstab.max(axis=1).sum() / total_observed
            if purity >= LEAKAGE_PURITY_THRESHOLD:
                exclude_cols.append(col)
                logger.warning(f"   ⚠️  STATISTICAL LEAKAGE: '{col}' predicts the target with "
                      f"{purity:.1%} purity using only its own value -- excluded as a "
                      f"near-perfect target proxy (not caught by name-based patterns).")

        # Step 5: Create clean feature matrix (without protected attributes)
        X_features = X.drop(columns=[c for c in set(exclude_cols) if c in X.columns])

        # Step 6: One-hot encode categorical variables. v3.5.0 FIX: pandas'
        # get_dummies() raises ValueError("No objects to concatenate") on a
        # DataFrame with ZERO columns (a real pandas quirk, not a bug in the
        # input) -- found via a synthetic 1-of-7/2-of-7-feature dataset
        # where every real predictor column was legitimately excluded,
        # leaving nothing to encode. That crash happened BEFORE
        # enforce_fairness's own zero-feature pre-flight check ever got a
        # chance to catch it cleanly, because it's raised one call earlier,
        # inside this method. Skipping the call entirely when there are no
        # columns to encode avoids the crash and leaves X_features as the
        # genuinely-empty (0-column, correct-row-count) frame the pre-flight
        # check expects.
        if X_features.shape[1] > 0:
            X_features = pd.get_dummies(X_features, drop_first=False, dtype=int)

                # Step 7: Handle missing and invalid values
        X_features = X_features.replace([np.inf, -np.inf], np.nan)
        X_features = X_features.fillna(0)

        # ============ STEP 1: LEAKAGE CHECK ============
        logger.warning(f"\n   DEBUG: Checking for leakage columns in features")
        logger.info(f"   Current feature count: {X_features.shape[1]}")

        leakage_cols = ['y_pred', 'y_prob', 'final_result', 'group', 'y_true', 'biasclean_target']
        found_leakage = []

        for col in leakage_cols:
            if col in X_features.columns:
                found_leakage.append(col)
                logger.warning(f"   ⚠️  CRITICAL: Found leakage column '{col}' in features")

        if found_leakage:
            logger.warning(f"   Removing leakage columns: {found_leakage}")
            X_features = X_features.drop(columns=found_leakage)

        logger.info(f"   Clean feature count: {X_features.shape[1]}")
        # ============ END LEAKAGE CHECK ============

        # Store feature columns for later reference
        self.feature_columns = X_features.columns.tolist()

        return X_features, y, group_labels

    def enforce_fairness(self, df: pd.DataFrame, feature_map: Dict[str, str],
                         target_column: str, group_column: Optional[str] = None,
                         validation_split: float = 0.25,
                         all_protected_columns: Optional[List[str]] = None) -> Dict[str, Any]:
        """
        Apply SVM fairness enforcement to corrected dataset.

        Args:
            df: BiasClean corrected DataFrame
            feature_map: Protected feature mappings
            target_column: Target outcome variable
            group_column: Primary protected attribute for monitoring
            validation_split: Proportion for validation holdout (0.0-0.5)
            all_protected_columns: v3.5.0 -- see _prepare_features' docstring.
                Every raw column approved-mapped to any protected feature,
                not just the one feature_map remembers per feature.

        Returns:
            Dictionary containing predictions, metrics, and enhanced DataFrame
        """
        logger.info(f"\n{'='*80}")
        logger.info("SVM FAIRNESS ENFORCEMENT")
        logger.info(f"{'='*80}")

        # Prepare features with leakage prevention
        X_features, y_true, group_labels = self._prepare_features(
            df, feature_map, target_column, group_column,
            all_protected_columns=all_protected_columns
        )

        logger.info(f"   Samples: {len(df):,}")
        logger.info(f"   Features: {X_features.shape[1]}")
        logger.info(f"   Target: '{target_column}' (positive rate: {y_true.mean():.1%})")

        if group_column:
            logger.info(f"   Protected attribute: '{group_column}' (excluded from features)")

        # v3.5.0 hardening: a real dataset can genuinely have ZERO usable
        # predictor columns left after leakage/protected-attribute exclusion
        # (e.g. a minimal dataset with only 1 of the 7 domain features plus
        # the target) -- training a classifier with no features would
        # either crash or, worse, silently degenerate (see the real-COMPAS
        # 'age'/'id' leak this release also fixes -- a classifier starved
        # of real signal collapses to a constant prediction rather than
        # failing loudly). Fail fast, clearly, and safely instead: skip
        # training entirely and let the caller fall back to the rebalanced-
        # only result, exactly like the existing "SVM disabled" path.
        if X_features.shape[1] == 0:
            logger.warning(f"\n   ⏸️  SVM SKIPPED: no usable predictor columns remain after "
                  f"excluding the target, protected attributes, and leakage-prone "
                  f"columns. A classifier with zero features would either crash or "
                  f"silently degenerate to a meaningless constant prediction --")
            logger.info(f"   neither is safe to present as a result. Falling back to the "
                  f"rebalanced-only data for this dataset.")
            return {
                'skipped': True,
                'skip_reason': 'no usable predictor columns remain after exclusions',
                'svm_method_used': None,
                'svm_method_requested': self.svm_method,
                'sample_count': len(df),
                'feature_columns': [],
            }

        # v3.3.0 Smart SVM: decide whether the fairness-constrained path
        # (ExponentiatedGradient, Agarwal et al. ICML 2018) is usable. It
        # needs both the fairlearn package AND a real protected-attribute
        # column to constrain on -- without either, we fall back to the
        # legacy vanilla SVM rather than crash or silently ignore the
        # request.
        use_fair_reduction = (
            self.svm_method == "fair_reduction"
            and FAIRLEARN_AVAILABLE
            and group_labels is not None
        )
        if self.svm_method == "fair_reduction" and not use_fair_reduction:
            reason = ("fairlearn is not installed (`pip install fairlearn`)" if not FAIRLEARN_AVAILABLE
                       else "no protected-attribute column is available to use as sensitive_features")
            logger.info(f"\n   NOTE: Smart SVM (ExponentiatedGradient) requested but unavailable -- {reason}.")
            logger.info(f"   Falling back to legacy SVM (no in-training fairness constraint).")

        if use_fair_reduction:
            constraint = DemographicParity() if self.fairness_constraint == "demographic_parity" else EqualizedOdds()
            logger.info(f"\n   Training Smart SVM: SVC wrapped in fairlearn ExponentiatedGradient")
            logger.info(f"   Fairness constraint: {self.fairness_constraint}")
        else:
            logger.info(f"\n   Training legacy SVM with fairness-aware configuration...")

        # Scale once, up front. ExponentiatedGradient requires a bare
        # estimator (not a Pipeline) -- Pipeline.fit rejects the
        # sample_weight kwarg fairlearn passes through internally, so
        # scaling has to happen outside the model object for both paths.
        scaler = StandardScaler(with_mean=True, with_std=True)
        X_scaled = pd.DataFrame(
            scaler.fit_transform(X_features), columns=X_features.columns, index=X_features.index
        )
        group_arr = np.asarray(group_labels) if group_labels is not None else None

        if validation_split > 0:
            if use_fair_reduction:
                X_train, X_val, y_train, y_val, g_train, _g_val = train_test_split(
                    X_scaled, y_true, group_arr,
                    test_size=validation_split, random_state=self.random_state, stratify=y_true
                )
            else:
                X_train, X_val, y_train, y_val = train_test_split(
                    X_scaled, y_true, test_size=validation_split,
                    random_state=self.random_state, stratify=y_true
                )
                g_train = None

            # ADD THIS FOR SPEED: Subsample training data
            if len(X_train) > 5000:
                X_train_reset = X_train.reset_index(drop=True)
                y_train_reset = pd.Series(y_train).reset_index(drop=True)
                sample_indices = np.random.RandomState(self.random_state).choice(
                    len(X_train_reset), 5000, replace=False
                )
                X_train = X_train_reset.iloc[sample_indices]
                y_train = y_train_reset.iloc[sample_indices].values
                if g_train is not None:
                    g_train = pd.Series(g_train).reset_index(drop=True).iloc[sample_indices].values
                logger.info(f"   Subsample: Using 5,000 samples for SVM training")

            logger.info(f"   Training samples: {len(X_train):,}")
            logger.info(f"   Validation samples: {len(X_val):,}")

            if use_fair_reduction:
                self.model = ExponentiatedGradient(SVC(**self.svm_config), constraints=constraint)
                self.model.fit(X_train, y_train, sensitive_features=g_train)
                val_pred = self.model.predict(X_val, random_state=self.random_state)
            else:
                self.model = SVC(**self.svm_config)
                self.model.fit(X_train, y_train)
                val_pred = self.model.predict(X_val)

            val_acc = (val_pred == y_val).mean()
            logger.info(f"   Validation accuracy: {val_acc:.1%}")

            # Generate predictions on full dataset for fairness enforcement
            if use_fair_reduction:
                y_pred = self.model.predict(X_scaled, random_state=self.random_state).astype(int)
                y_prob = self._exp_gradient_proba(X_scaled)
            else:
                y_pred = self.model.predict(X_scaled).astype(int)
                y_prob = self.model.predict_proba(X_scaled)[:, 1].astype(float)
            full_acc = (y_pred == y_true).mean()

        else:
            if use_fair_reduction:
                self.model = ExponentiatedGradient(SVC(**self.svm_config), constraints=constraint)
                self.model.fit(X_scaled, y_true, sensitive_features=group_arr)
                y_pred = self.model.predict(X_scaled, random_state=self.random_state).astype(int)
                y_prob = self._exp_gradient_proba(X_scaled)
            else:
                self.model = SVC(**self.svm_config)
                self.model.fit(X_scaled, y_true)
                y_pred = self.model.predict(X_scaled).astype(int)
                y_prob = self.model.predict_proba(X_scaled)[:, 1].astype(float)
            full_acc = (y_pred == y_true).mean()
            logger.info(f"   Note: Training on full dataset (no validation split)")
            val_acc = None

        # Compute decision boundary margins
        margin = self._compute_margin(X_scaled.values, use_fair_reduction)

        # Calculate fairness metrics
        fairness_metrics = self._calculate_fairness_metrics(
            y_true, y_pred, group_labels, group_column
        )

        # Prepare results dictionary
        results = {
            'svm_predictions': y_pred,
            'svm_probabilities': y_prob,
            'svm_margins': margin,
            'fairness_metrics': fairness_metrics,
            'feature_columns': self.feature_columns,
            'model_config': self.svm_config,
            'sample_count': len(df),
            'validation_split': validation_split,
            'validation_accuracy': val_acc,
            'full_accuracy': full_acc,
            'svm_method_used': "fair_reduction" if use_fair_reduction else "legacy",
            'fairness_constraint': self.fairness_constraint if use_fair_reduction else None,
            'svm_method_requested': self.svm_method,
        }

        # Create enhanced DataFrame with SVM outputs
        df_svm = df.copy()
        df_svm['svm_y_pred'] = y_pred
        df_svm['svm_y_prob'] = y_prob
        df_svm['svm_margin'] = margin

        results['enhanced_dataframe'] = df_svm
        results['target_column'] = target_column
        if group_column:
            results['group_column'] = group_column

        # Print summary
        logger.info(f"\n   SVM Fairness Enforcement Complete")
        if validation_split > 0 and val_acc is not None:
            logger.info(f"   • Validation accuracy: {val_acc:.1%}")
        logger.info(f"   • Full dataset accuracy: {full_acc:.1%}")
        logger.info(f"   • Positive prediction rate: {y_pred.mean():.1%}")

        if 'disparity' in fairness_metrics:
            logger.info(f"   • Group disparity: {fairness_metrics['disparity']:.3f}")

        logger.info(f"{'='*80}")

        return results

    def _compute_margin(self, X_scaled: np.ndarray, is_fair_reduction: bool = False) -> np.ndarray:
        """
        Compute distance from SVM decision boundary for each sample.
        X_scaled must already be feature-scaled (v3.3.0: scaling moved
        out of the model object -- see enforce_fairness -- so this no
        longer scales internally).

        Args:
            X_scaled: Pre-scaled feature matrix
            is_fair_reduction: True if self.model is an
                ExponentiatedGradient ensemble rather than a bare SVC.

        Returns:
            Array of margin values (signed distances from boundary)
        """
        if self.model is None:
            return np.zeros(X_scaled.shape[0], dtype=float)

        try:
            if is_fair_reduction:
                # ExponentiatedGradient is a randomized ensemble of SVC
                # clones (predictors_) mixed by weights_ that sum to 1.0.
                # The margin consistent with that ensemble is the same
                # weights_-weighted average used for probabilities below.
                margins = np.zeros(X_scaled.shape[0], dtype=float)
                for predictor, weight in zip(self.model.predictors_, self.model.weights_):
                    if weight <= 0:
                        continue
                    margins += weight * predictor.decision_function(X_scaled)
                return margins
            return self.model.decision_function(X_scaled).astype(float)
        except Exception:
            return np.zeros(X_scaled.shape[0], dtype=float)

    def _exp_gradient_proba(self, X_scaled: pd.DataFrame) -> np.ndarray:
        """
        ExponentiatedGradient has no predict_proba of its own -- it only
        exposes a randomized hard .predict(). We approximate a
        probability as the weights_-weighted average of each ensemble
        member's own predict_proba (each member is an
        SVC(probability=True) clone, same base estimator as the legacy
        single-model path), which is consistent with how .predict()
        itself works internally (weighted vote across predictors_).
        Falls back to hard 0/1 predictions if any member lacks
        predict_proba (should not happen given probability=True in
        svm_config, but must never crash the pipeline).
        """
        try:
            probs = np.zeros(len(X_scaled), dtype=float)
            for predictor, weight in zip(self.model.predictors_, self.model.weights_):
                if weight <= 0:
                    continue
                probs += weight * predictor.predict_proba(X_scaled)[:, 1]
            return probs.astype(float)
        except Exception:
            return self.model.predict(X_scaled, random_state=self.random_state).astype(float)

    def _calculate_fairness_metrics(self, y_true: np.ndarray, y_pred: np.ndarray,
                                   group_labels: Optional[np.ndarray],
                                   group_column: Optional[str]) -> Dict[str, float]:
        """
        Calculate fairness metrics for protected group monitoring.

        Args:
            y_true: Ground truth labels
            y_pred: Predicted labels
            group_labels: Protected group identifiers
            group_column: Protected attribute name

        Returns:
            Dictionary of fairness metrics
        """
        metrics = {}

        if group_labels is not None and group_column:
            groups = np.unique(group_labels)
            group_rates = {}

            # Calculate positive prediction rate per group
            for group in groups:
                mask = group_labels == group
                if mask.sum() > 0:
                    group_rate = y_pred[mask].mean()
                    group_rates[str(group)] = group_rate

            # Calculate disparity metric (coefficient of variation)
            if len(group_rates) >= 2:
                rates = np.array(list(group_rates.values()))
                disparity = np.std(rates) / (np.mean(rates) + 1e-10)
                metrics['disparity'] = min(disparity, 1.0)
                metrics['group_rates'] = group_rates

        # Overall performance metrics
        metrics['accuracy'] = float((y_pred == y_true).mean())
        metrics['positive_rate'] = float(y_pred.mean())

        return metrics

    def get_fdk_export(self, df_svm: pd.DataFrame, group_column: str,
                       target_column: str) -> pd.DataFrame:
        """
        Prepare minimal DataFrame for independent Fairness Development Kit (FDK) audit.

        Args:
            df_svm: Enhanced DataFrame with SVM predictions
            group_column: Protected attribute column
            target_column: Target outcome column

        Returns:
            DataFrame formatted for FDK audit
        """
        export_df = pd.DataFrame({
            'group': df_svm[group_column],
            'y_true': df_svm[target_column],
            'y_pred': df_svm['svm_y_pred'],
            'y_prob': df_svm['svm_y_prob']
        })
        return export_df

    def save_results(self, results: Dict[str, Any], output_dir: str = "svm_fairness_results"):
        """
        Save SVM fairness enforcement results for audit trail.

        Args:
            results: Results dictionary from enforce_fairness()
            output_dir: Output directory path

        Returns:
            Output directory path
        """
        os.makedirs(output_dir, exist_ok=True)

        # Save enhanced DataFrame
        df_svm = results['enhanced_dataframe']
        df_svm.to_csv(f"{output_dir}/svm_enhanced_dataset.csv", index=False)

        # Save FDK audit export
        if 'group_column' in results:
            fdk_export = self.get_fdk_export(
                df_svm,
                results['group_column'],
                results['target_column']
            )
            fdk_export.to_csv(f"{output_dir}/svm_for_fdk_audit.csv", index=False)

        # Save metadata
        metadata = {
            'model_config': results['model_config'],
            'fairness_metrics': results['fairness_metrics'],
            'feature_count': len(results['feature_columns']),
            'sample_count': results['sample_count'],
            'domain_weights': self.domain_weights,
            'validation_accuracy': results.get('validation_accuracy'),
            'full_accuracy': results.get('full_accuracy')
        }

        with open(f"{output_dir}/svm_metadata.json", 'w') as f:
            json.dump(metadata, f, indent=2)

        logger.info(f"\nResults saved to: {output_dir}/")
        return output_dir

