# 6.5 V2.7 MONITORING COMPONENTS
# ============================================================================

class EnhancedStageScoreTracker:
    """Tracks bias scores across pipeline stages"""

    def __init__(self, weights: Dict[str, float]):
        self.weights = weights
        self.stages = {}

    @property
    def bias_scores(self) -> Dict[str, float]:
        """Get bias scores for all stages (for backward compatibility)"""
        return {
            stage: data.get('bias_score')
            for stage, data in self.stages.items()
            if data.get('bias_score') is not None
        }

    def record_stage(self, stage_name: str, df: pd.DataFrame,
                    feature_map: Dict, target_col: str,
                    engine=None, bias_score: float = None,
                    confidence_calculator=None):
        """Record bias score for a pipeline stage"""
        try:
            # Use provided bias score or calculate it
            if bias_score is None:
                bias_score = self._calculate_bias_score(df, feature_map, target_col)

            stage_data = {
                'bias_score': bias_score,
                'records': len(df),
                'timestamp': datetime.now().isoformat()
            }

            # Add confidence intervals if calculator provided
            if confidence_calculator is not None and bias_score is not None:
                # Create array of bias scores for CI calculation
                # (simplified - in real usage this would be from bootstrap samples)
                ci_lower, ci_mean, ci_upper = confidence_calculator.calculate_ci(
                    np.array([bias_score] * 100)  # Placeholder
                )
                stage_data['ci_lower'] = ci_lower
                stage_data['ci_upper'] = ci_upper

            self.stages[stage_name] = stage_data

        except Exception as e:
            logger.warning(f"Warning: Could not record stage '{stage_name}': {e}")
            self.stages[stage_name] = {
                'bias_score': None,
                'records': len(df),
                'error': str(e)
            }

    def _calculate_bias_score(self, df: pd.DataFrame,
                             feature_map: Dict, target_col: str) -> float:
        """Calculate weighted bias score"""
        scores = []
        weights_used = []

        for canonical, original in feature_map.items():
            if canonical in self.weights and original in df.columns:
                # Simple disparity calculation
                if df[original].dtype == 'object' or df[original].nunique() < 10:
                    # Categorical feature
                    target_rates = df.groupby(original)[target_col].mean()
                    if len(target_rates) > 1:
                        disparity = target_rates.max() - target_rates.min()
                        scores.append(disparity)
                        weights_used.append(self.weights[canonical])

        if scores:
            weighted_score = np.average(scores, weights=weights_used)
            return float(weighted_score)
        return 0.0

    def get_progression(self) -> Dict:
        """Get bias score progression across stages"""
        return {
            stage: data['bias_score']
            for stage, data in self.stages.items()
        }

    def get_summary(self) -> Dict:
        """Get summary of all stages"""
        return self.stages


class StatisticalConfidenceCalculator:
    """Calculates statistical confidence intervals for bias metrics"""

    def __init__(self, n_bootstrap: int = 500, ci_level: float = 0.95):
        self.n_bootstrap = n_bootstrap
        self.ci_level = ci_level

    def calculate_ci(self, data: np.ndarray) -> Tuple[float, float, float]:
        """
        Calculate confidence interval using bootstrap

        Returns:
            (lower_bound, mean, upper_bound)
        """
        try:
            bootstrap_means = []
            n = len(data)

            for _ in range(self.n_bootstrap):
                sample = np.random.choice(data, size=n, replace=True)
                bootstrap_means.append(np.mean(sample))

            bootstrap_means = np.array(bootstrap_means)
            alpha = 1 - self.ci_level

            lower = np.percentile(bootstrap_means, (alpha/2) * 100)
            upper = np.percentile(bootstrap_means, (1 - alpha/2) * 100)
            mean = np.mean(data)

            return float(lower), float(mean), float(upper)
        except Exception:
            mean = float(np.mean(data))
            return mean, mean, mean


class GroupRateTracker:
    """Tracks outcome rates for different demographic groups"""

    def __init__(self):
        self.group_rates = {}

    def track(self, df: pd.DataFrame, group_col: str,
             target_col: str, stage: str = ""):
        """Track rates for groups in a specific column"""
        try:
            rates = df.groupby(group_col)[target_col].agg(['mean', 'count']).to_dict('index')

            self.group_rates[f"{group_col}_{stage}"] = {
                group: {
                    'rate': float(stats['mean']),
                    'count': int(stats['count'])
                }
                for group, stats in rates.items()
            }
        except Exception as e:
            logger.warning(f"Warning: Could not track group rates for {group_col}: {e}")

    def get_disparities(self, group_key: str) -> Dict:
        """Calculate disparities for a tracked group"""
        if group_key not in self.group_rates:
            return {}

        rates = [data['rate'] for data in self.group_rates[group_key].values()]
        if len(rates) < 2:
            return {}

        return {
            'max_rate': max(rates),
            'min_rate': min(rates),
            'disparity': max(rates) - min(rates),
            'ratio': max(rates) / min(rates) if min(rates) > 0 else float('inf')
        }


class SamplingAttributionLogger:
    """Logs attribution for sampling and rebalancing operations"""

    def __init__(self):
        self.logs = []

    def log_operation(self, operation: str, details: Dict):
        """Log a sampling or rebalancing operation"""
        self.logs.append({
            'timestamp': datetime.now().isoformat(),
            'operation': operation,
            'details': details
        })

    def log_rebalance(self, group: str, original_count: int,
                     new_count: int, method: str):
        """Log a rebalancing operation"""
        self.log_operation('rebalance', {
            'group': group,
            'original_count': original_count,
            'new_count': new_count,
            'change': new_count - original_count,
            'method': method
        })

    def log_sample(self, group: str, n_sampled: int, method: str):
        """Log a sampling operation"""
        self.log_operation('sample', {
            'group': group,
            'n_sampled': n_sampled,
            'method': method
        })

    def log_rebalancing_changes(self, original_df: pd.DataFrame,
                               corrected_df: pd.DataFrame,
                               feature_map: Dict, target_col: str):
        """Log comprehensive rebalancing changes between original and corrected dataframes"""
        try:
            changes = {
                'total_records_before': len(original_df),
                'total_records_after': len(corrected_df),
                'net_change': len(corrected_df) - len(original_df),
                'features_rebalanced': []
            }

            # Track changes for each feature in the feature map
            for canonical, original_col in feature_map.items():
                if original_col in original_df.columns and original_col in corrected_df.columns:
                    # Get group counts before and after
                    before_counts = original_df[original_col].value_counts().to_dict()
                    after_counts = corrected_df[original_col].value_counts().to_dict()

                    # Calculate changes per group
                    all_groups = set(before_counts.keys()) | set(after_counts.keys())
                    group_changes = {}

                    for group in all_groups:
                        before = before_counts.get(group, 0)
                        after = after_counts.get(group, 0)
                        group_changes[str(group)] = {
                            'before': before,
                            'after': after,
                            'change': after - before
                        }

                    changes['features_rebalanced'].append({
                        'feature': original_col,
                        'canonical': canonical,
                        'group_changes': group_changes
                    })

            self.log_operation('rebalancing_summary', changes)

        except Exception as e:
            logger.warning(f"Warning: Could not log rebalancing changes: {e}")
            self.log_operation('rebalancing_summary', {'error': str(e)})

    def log_svm_changes(self, df: pd.DataFrame, original_target: str,
                       svm_target: str):
        """Log changes introduced by SVM fairness enforcement"""
        try:
            if original_target in df.columns and svm_target in df.columns:
                # Compare original target vs SVM predictions
                original = df[original_target]
                svm_pred = df[svm_target]

                changes = {
                    'total_records': len(df),
                    'predictions_changed': int((original != svm_pred).sum()),
                    'change_rate': float((original != svm_pred).mean()),
                    'original_positive_rate': float(original.mean()),
                    'svm_positive_rate': float(svm_pred.mean())
                }

                self.log_operation('svm_enforcement', changes)
            else:
                self.log_operation('svm_enforcement', {
                    'error': f'Target columns not found: {original_target}, {svm_target}'
                })

        except Exception as e:
            logger.warning(f"Warning: Could not log SVM changes: {e}")
            self.log_operation('svm_enforcement', {'error': str(e)})

    def get_summary(self) -> Dict:
        """Get summary of all logged operations"""
        return {
            'total_operations': len(self.logs),
            'operations': self.logs
        }


# ============================================================================
# 7. UNIVERSAL BIASCLEAN PIPELINE v3.0 - AUDIT-FIRST ENHANCEMENT
# ============================================================================

class UniversalBiasClean:
    """Main orchestration pipeline for Universal BiasClean v3.0"""

    def __init__(self, domain: str = "justice", jurisdiction: Optional[str] = None,
                 mode: str = None, enable_svm: bool = None,
                 rebalance_method: str = "reweighing",
                 svm_method: str = "fair_reduction",
                 fairness_constraint: str = "equalized_odds"):
        """
        v3.0: Add audit-first capability

        Args:
            mode: "audit_first" (default), "legacy", or "audit_only"
            enable_svm: Override v2.7 default (False)
            rebalance_method: v3.3.0 added "reweighing" (Kamiran &
                Calders' other technique, realized as row resampling)
                alongside the existing "preferential" (Preferential
                Sampling). v3.3.1 makes "reweighing" the DEFAULT --
                empirically compared against Preferential Sampling on
                real COMPAS data (compas-scores-two-years.csv, target=
                two_year_recid): Reweighing cut the composite bias
                score 61.7% (0.0992 -> 0.0380) vs. Preferential
                Sampling's 29.8% (0.0992 -> 0.0697), a >2x difference
                on the exact same input. "preferential" remains
                available as an explicit opt-in.
            svm_method: v3.3.0 -- "fair_reduction" (default: fairlearn's
                ExponentiatedGradient, an actual fairness-constrained
                classifier) or "legacy" (the old vanilla-SVM path, kept
                for direct comparison). Falls back to "legacy"
                automatically, with a console warning, if fairlearn
                isn't installed or no protected attribute is available
                for the constraint.
            fairness_constraint: v3.3.0 -- "equalized_odds" (default,
                Hardt/Price/Srebro 2016) or "demographic_parity", used
                only when svm_method="fair_reduction".
        """
        self.domain = domain
        self.jurisdiction = jurisdiction
        self.config = DOMAIN_CONFIGS.get(domain, DOMAIN_CONFIGS["justice"])

        # v3.0 parameters
        self.mode = mode if mode is not None else config.DEFAULT_MODE
        self.enable_svm = enable_svm if enable_svm is not None else config.SVM_DEFAULT
        # v3.3.0 parameters
        self.rebalance_method = rebalance_method
        self.svm_method = svm_method
        self.fairness_constraint = fairness_constraint

        # Initialize components (existing v2.7 code)
        self.mapper = HierarchicalMapper(domain=domain)
        self.validator = ConstraintValidator()
        self.ui = MappingConfirmationUI()
        self.viz = VisualizationEngine()
        self.reporter = ReportGenerator(self.config)
        self.engine = BiasCleanEngine(self.config["weights"])

        # State
        self.original_df = None
        self.corrected_df = None
        self.approved_mappings = {}
        self.results = {}

        # v3.2.0: safe defaults so audit_trail.json always has these keys
        # even when mitigation never runs (RED-blocked / audit_only) or SVM
        # is disabled -- populated for real in PHASE 7 / the SVM block.
        self.rebalance_log = []
        self.reversal_checks = {}
        self.svm_reversal_checks = {}
        self.svm_gate = {}
        self.rebalance_gate = {}

        logger.info(f"\n{'='*80}")
        logger.info(f"BIASCLEAN v{__version__} - {self.mode.upper()} MODE")
        logger.info(f"{'='*80}")

    def _compile_audit_only_results(self, audit_results: dict, target: str,
                                     feature_map: Optional[dict] = None) -> dict:
        """Compile results when audit blocks (RED) or audit-only mode, AND
        actually save them.

        This used to just return a small in-memory dict and stop -- no
        call to _save_results() or generate_report() anywhere in this
        path. That meant a BLOCKED (RED) audit, or a deliberate
        audit-only run, produced zero files, no matter how many times
        the pipeline was rerun -- while the console output looked like
        it had finished normally. A RED verdict is arguably the single
        most important case to have a persistent report for (it's the
        pipeline telling someone "don't use this data, here's why"), so
        this now mirrors the normal Phase 9/10 save+report flow, with
        the mitigation-specific fields (validation, corrected dataset)
        left empty/absent since no rebalancing was performed.
        """
        feature_map = feature_map or {}
        self.corrected_df = None
        self._stage_tracker_summary = {}
        self._sampling_summary = {}

        fairness = audit_results.get("baseline_fairness", {})
        bias_score = fairness.get("aggregate_bias", 0)

        self.results = {
            "mode": self.mode,
            "v3_audit": audit_results,
            "audit": audit_results,
            "mitigation_performed": False,
            "target_column": target,
            "target_binarization": (
                {str(k): v for k, v in self.target_binarization_map.items()}
                if getattr(self, "target_binarization_map", None) else None
            ),
            "domain": self.domain,
            "diagnostics": {
                "initial_bias_score": bias_score,
                "final_bias_score": bias_score,
                "feature_tests": {},
            },
            "validation": {
                "data_integrity": {
                    "records_before": len(self.original_df),
                    "records_after": len(self.original_df),
                    "retention_rate": 100.0,
                },
                "fairness_improvement": {},
                "initial_disparities": {},
                "final_disparities": {},
            },
            "svm_validation": {
                "svm_applied": False,
                "reason": "Mitigation was not performed -- " + audit_results.get("recommendation", {}).get("action", "audit did not approve proceeding"),
            },
            "mappings": self.approved_mappings if hasattr(self, "approved_mappings") else {},
            "feature_map": feature_map,
            # v3.10.8 FIX (found during HMDA re-validation, real data): this
            # dict never included a "features" key anywhere in the file --
            # confirmed via exhaustive grep. _detect_mapping_conflicts's
            # selected_columns is built from results.get("features", {}),
            # so "winner" was ALWAYS empty here, meaning the v3.10.4
            # winner-naming fix ("'X' was used for the actual analysis...")
            # and the v3.10.6 item-3 p-value transparency addition BOTH
            # silently fell back to the generic "Only one is actually used
            # for the analysis" message in every delivered report.pdf, for
            # every Phase 5 dataset -- not just no-mitigation ones. This is
            # the minimal population needed (mirrors what features_merged
            # already correctly builds for audit_trail.json, just scoped to
            # the one field _detect_mapping_conflicts actually reads).
            "features": {feature: {"column": col} for feature, col in feature_map.items()},
            "deployment_info": {"deployment_decision": audit_results.get("recommendation", {})},
            "group_rates_final": {},
            "feature_interactions": {},
            "dataset_info": {
                "records": len(self.original_df),
                "columns": len(self.original_df.columns),
            },
        }

        self._save_results()

        logger.info(f"\n{'='*80}")
        logger.info("GENERATING REPORT (mitigation was not performed -- explains why)")
        logger.info(f"{'='*80}")
        report_path = "biasclean_results/report.pdf"
        try:
            logger.info("\n   Generating report...")
            self.reporter.print_console_report(self.results)
            report_path = self.reporter.generate_report(self.results, output_file=report_path, charts={})
        except Exception as e:
            logger.info(f"   Report generation failed: {str(e)}")

        logger.info(f"\n{'='*80}")
        logger.info("PIPELINE STOPPED -- report saved (no mitigation was performed)")
        logger.info(f"{'='*80}")
        logger.info(f"   Results saved to: biasclean_results/")
        logger.info(f"   Audit: {audit_results.get('recommendation', {}).get('traffic_light', 'N/A')}")
        logger.info(f"   • {os.path.basename(report_path):<24} - explains why mitigation didn't run")
        logger.info(f"   • audit_trail.json       - full machine-readable numbers")
        logger.info(f"   (no corrected_dataset.csv -- no mitigation was performed on this data)")
        logger.info(f"{'='*80}\n")

        return self.results

    @staticmethod
    def _select_best_column_per_feature(approved_mappings: Dict[str, Any]) -> Dict[str, str]:
        """
        v3.6.7: When multiple raw columns are all approved-mapped to the
        SAME protected feature (e.g. COMPAS's 'age'/'dob'/'age_cat' all
        -> Age; Communities & Crime's 'state'/'county' both -> Region;
        OK City's 'subject_race'/'raw_dfnd_race' both -> Ethnicity),
        exactly one column has to be picked to actually drive the bias
        analysis. Previously this was a plain dict-overwrite loop
        (`feature_map[feature] = column` for each approved mapping in
        iteration order), so whichever column happened to be approved
        LAST silently won -- completely ignoring both mapping confidence
        AND the validation statistics already computed for every
        candidate. This is the "residual limitation...not fixed here"
        flagged in the 3.6.2->3.6.3 changelog (for the outcome tier) and
        the "latent risk worth a future cardinality guard" flagged in
        the 3.6.5->3.6.6 changelog (for protected features) -- both
        pointed at this exact gap.

        Confirmed on real data this previously picked the WRONG column
        twice: Communities & Crime's Region landed on 'county' (108
        groups, min_group_size=1, p=0.13 -- not significant; UCI's own
        documentation flags 'county' as sparse/non-predictive) instead
        of 'state' (46 groups, p=1.2e-72 -- extremely significant), and
        OK City's Ethnicity landed on 'raw_dfnd_race' (85% confidence)
        over 'subject_race' (92.5% confidence) purely because of column
        order, already disclosed in the 3.6.5->3.6.6 changelog as an
        expected-but-undesirable consequence of this same gap. COMPAS's
        Age happened to land on 'age_cat' (the right choice) only by
        equally-accidental file-order luck, not because anything
        preferred it.

        Fix: rank each candidate by (no small-group-size warning first,
        then higher mapping confidence), and only keep the new column if
        it is STRICTLY better than whichever is already selected -- so a
        genuine tie (identical warning-status AND identical confidence,
        e.g. nothing left to distinguish two candidates on) still falls
        back to whichever was encountered first, deterministically,
        instead of an arbitrary last-wins overwrite. This directly
        reuses validation statistics (min_group_size / warnings) that
        were already computed during PHASE 3 for every candidate and
        were previously discarded at this step without ever being
        looked at.

        Verified against both real cases above: this produces 'age_cat'
        for COMPAS Age (only candidate with no small-group warning) and
        'state' for Communities & Crime Region (both candidates carry
        the same small-group warning at identical 95% confidence, so
        'state' wins as the first-encountered column in file order --
        matching the real UCI column order, state before county). See
        test_regression.py::test_feature_map_prefers_valid_groups_over_
        file_order for a synthetic, deterministic reproduction of both
        shapes (a clean-vs-degenerate-grouping tie, and a genuine
        equal-quality tie) that doesn't depend on which real dataset
        happens to be on disk.

        Known residual limitation, not fixed here: if two candidates
        have identical warning-status AND identical p-value AND
        identical confidence (a true coin-flip tie), the choice still
        falls back to file order. This is now a deliberate, documented
        last resort rather than the only mechanism, but it isn't
        eliminated -- flag any such case encountered during the Phase 2
        validation the same way the 3.6.3 changelog flagged NIJ's four
        same-pattern Recidivism_* columns, rather than treating it as
        silently resolved.

        v3.10.4 UPDATE: p-value inserted as the tiebreaker between the
        warning-status gate and confidence (see the ranking tuple's own
        comment below for the real-data case -- German Credit's
        SocioeconomicStatus -- that motivated this). This also happens
        to resolve the Communities & Crime Region case documented above
        on its merits (state's p=1.2e-72 vs county's p=0.13) rather than
        by the file-order accident this docstring previously described
        as the deciding factor -- the outcome is unchanged (state still
        wins) but for the right reason now, not a coincidence of column
        order.
        """
        feature_map: Dict[str, str] = {}
        feature_quality: Dict[str, Any] = {}
        for column, mapping in approved_mappings.items():
            feature = mapping.get("feature")
            if not feature or feature in ("__outcome__", "__exclude__", None):
                continue
            validation = mapping.get("validation", {}) or {}
            warnings = validation.get("warnings", []) or []
            has_small_group_warning = any("Small group size" in w for w in warnings)
            confidence = mapping.get("confidence", 0)
            # v3.10.4: p-value inserted as the primary tiebreaker, ahead
            # of raw mapping confidence. Root cause found on German
            # Credit (Finance): confidence only measures how sure the
            # keyword-matcher is that a column NAMES the right feature
            # (Tier 1/universal patterns score 85-98%, Tier 2/domain
            # patterns cap at a flat 75%) -- it says nothing about
            # whether that column's DATA actually shows a real
            # disparity. With 6 columns all correctly identified as
            # SocioeconomicStatus, confidence-first selection picked
            # InstallmentRatePctOfDisposableIncome (95%, p=0.140 -- the
            # WEAKEST evidence of the six) over Property (75%,
            # p=0.0000286), Housing (75%, p=0.000112), and
            # PresentEmploymentSince (75%, p=0.00105) -- all three
            # 100-5000x more statistically compelling, all three lost
            # purely because their pattern match happened to sit in the
            # lower-confidence domain tier. Once a column already passed
            # the small-group-size gate (i.e. its statistics are
            # considered reliable enough to trust at all), which column
            # actually shows the stronger real disparity should decide
            # -- not which one merely sounds more certainly named.
            # Missing/failed statistical tests (no p_value recorded)
            # rank as if p=1.0 -- no evidence, not an advantage.
            p_value = (validation.get("statistics", {}) or {}).get("p_value")
            if p_value is None:
                p_value = 1.0
            # Sorts ascending: no-warning (False) beats has-warning (True)
            # first; within the same warning-status, lower p-value
            # (stronger evidence) wins; within an exact p-value tie,
            # higher confidence (stored negated) wins. Equal tuples never
            # satisfy strict '<', so the first-encountered column is kept
            # on a true coin-flip tie -- same documented last-resort
            # fallback as before, just harder to reach now.
            candidate_quality = (has_small_group_warning, p_value, -confidence)
            if feature not in feature_quality or candidate_quality < feature_quality[feature]:
                feature_map[feature] = column
                feature_quality[feature] = candidate_quality
        return feature_map

    def process_dataset(self, file_path: str = None, df: pd.DataFrame = None,
                       target_column: Optional[str] = None,
                       auto_approve_threshold: float = 0.80) -> Dict[str, Any]:
        """
        Complete pipeline execution with v3.0 audit-first enhancement

        Args:
            file_path: Path to CSV file (optional if df provided)
            df: DataFrame to process (optional if file_path provided)
            target_column: Outcome variable column name (required as of
                v3.10.1 -- no auto-detection; omitting this raises
                ValueError)
            auto_approve_threshold: Confidence threshold for auto-approval

        Returns:
            Complete results dictionary with v3.0 monitoring
        """
        try:
            # Workstream F: fresh per-run log file alongside audit_trail.json,
            # attached before any phase output so the whole run is captured.
            self._log_file_path = _setup_run_file_logging()

            # ================================================================
            # PHASE 1: DATASET LOADING
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 1: DATASET LOADING")
            logger.info(f"{'='*80}")

            if df is not None:
                self.original_df = df.copy()
                logger.info(f"Loaded DataFrame from memory")
            elif file_path:
                self.original_df = smart_read_csv(file_path)
                logger.info(f"Loaded CSV: {file_path}")
            else:
                raise ValueError("Must provide either file_path or df")

            logger.info(f"   Records:  {len(self.original_df):,}")
            logger.info(f"   Columns:  {len(self.original_df.columns)}")
            logger.info(f"   Memory:   {self.original_df.memory_usage(deep=True).sum() / 1024**2:.2f} MB")

            # ================================================================
            # PHASE 2: HIERARCHICAL MAPPING
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 2: HIERARCHICAL FEATURE MAPPING")
            logger.info(f"{'='*80}")

            raw_mappings = self.mapper.map_dataset(self.original_df)

            # Count by tier
            tier_counts = {}
            for mapping in raw_mappings.values():
                tier = mapping.get("tier", "unknown")
                tier_counts[tier] = tier_counts.get(tier, 0) + 1

            logger.info(f"   Analyzed {len(raw_mappings)} columns:")
            for tier, count in sorted(tier_counts.items()):
                logger.info(f"     • {tier.title()}: {count}")

            # ================================================================
            # PHASE 2.5: CONTINUOUS PROTECTED-ATTRIBUTE BUCKETING
            # ================================================================
            # v3.10.5: for any column mapped to Age or SocioeconomicStatus
            # (the two canonical features repeatedly found across Phase 5
            # real-data validation to arrive as raw, near-continuous
            # values -- raw per-year Age in NC/Business/German Credit/
            # Heart Disease/bar_pass, raw per-dollar Income in Governance,
            # the latter reaching min_group_size=1 and a negative-dollar
            # "group" after SVM) that's numeric and would otherwise trip
            # the excessive-cardinality skip below, bucket it into a
            # small number of quantile-based groups FIRST, in place,
            # before validation computes any statistics against it. This
            # runs before PHASE 3 specifically so validation naturally
            # sees the bucketed labels as an ordinary low-cardinality
            # categorical column -- no other phase needs to know
            # bucketing happened. Scoped narrowly to these two features
            # (not every numeric protected-attribute match) for the same
            # reason the Finance SES keyword fix was scoped to Finance
            # only: minimize blast radius to the features actually
            # demonstrated to need it, rather than a blanket rule.
            BUCKETABLE_FEATURES = {"Age", "SocioeconomicStatus"}
            self.bucketed_columns = {}  # column -> bucketing info, for audit_trail transparency
            for column, mapping in raw_mappings.items():
                feature = mapping.get("feature")
                if feature not in BUCKETABLE_FEATURES:
                    continue
                if not pd.api.types.is_numeric_dtype(self.original_df[column]):
                    continue
                n_unique = self.original_df[column].nunique(dropna=True)
                min_observed_group = self.original_df[column].value_counts(dropna=True).min() if n_unique else None
                if min_observed_group is None or min_observed_group >= config.THRESHOLDS["min_samples_per_group"]:
                    continue  # every group already clears the floor, e.g. a pre-bucketed age_band -- leave untouched
                bucketed, info = _quantile_bucket_numeric_column(
                    self.original_df[column], max_bins=4,
                    min_bin_size=int(config.THRESHOLDS["min_samples_per_group"])
                )
                if bucketed is None:
                    continue  # dataset too small even for 2 viable bins -- falls through to the existing skip below, unchanged
                logger.info(f"   📊 Bucketing '{column}' ({feature}): {n_unique} raw values -> "
                      f"{info['n_bins']} groups {info['bin_labels']} (min group size: {info['min_bin_size']})")
                self.original_df[column] = bucketed
                self.bucketed_columns[column] = {"feature": feature, **info}

            logger.info("PHASE 3: CONSTRAINT VALIDATION")
            logger.info(f"{'='*80}")

            # Determine target column.
            #
            # If the user names a column explicitly, that's final -- try to
            # coerce it and fail loudly if it isn't usable (no silent
            # substitution when someone has told us exactly what they want).
            #
            # If we're auto-detecting, don't just take the single top
            # keyword-confidence match and commit to it: try every
            # candidate in descending order (outcome-pattern matches
            # first, then any other 2-category column as fallback) and
            # skip whichever ones can't actually be coerced to binary --
            # e.g. a column named 'outcome' with 3 categories (warning/
            # citation/arrest) should be skipped in favor of a clean
            # boolean column like 'arrest_made', rather than auto-detect
            # committing to 'outcome' and immediately failing the whole
            # run. This is what makes "just press Enter" actually work
            # on real-world data instead of only on pre-cleaned samples.
            target_binarization_map = None
            self._tied_outcome_candidates = []
            if target_column and target_column in self.original_df.columns:
                final_target = target_column
                logger.info(f"   Using specified target: '{final_target}'")
                try:
                    coerced_target, target_binarization_map = coerce_binary_target(self.original_df, final_target)
                    self.original_df[final_target] = coerced_target
                except ValueError as e:
                    raise ValueError(f"Cannot use '{final_target}' as the target column.\n{e}") from e
            elif target_column:
                # Workstream G (Phase 4): this branch used to not exist --
                # a target_column that was truthy but NOT present in
                # self.original_df.columns fell straight through to the
                # auto-detection `else` below, silently ignoring the
                # user's explicit request and picking a DIFFERENT column
                # instead, with nothing in the console output or
                # audit_trail.json indicating the requested column was
                # ever missing. This directly contradicted this exact
                # function's own comment two lines above ("no silent
                # substitution when someone has told us exactly what
                # they want"): the code and its own documented intent had
                # drifted apart. A no-code user with a typo'd column name
                # (or a column dropped during their own upstream cleanup)
                # would get a complete-looking report auditing bias
                # against a column they never asked for, with no
                # indication anything had gone differently than
                # requested -- silent wrong-behavior, not a crash, and
                # arguably worse for exactly that reason. Found via
                # Workstream G's own audit rather than a hard failure.
                available_preview = ", ".join(list(self.original_df.columns)[:15])
                more = "" if len(self.original_df.columns) <= 15 else f", ... and {len(self.original_df.columns) - 15} more"
                raise ValueError(
                    f"Target column '{target_column}' was not found in this "
                    f"dataset. Available columns include: {available_preview}"
                    f"{more}. Check for a typo and re-run with the correct "
                    f"column name -- BiasClean does not auto-detect the "
                    f"target column, so this must be specified exactly."
                )
            else:
                # ------------------------------------------------------------
                # AUTO-DETECTION REMOVED (v3.10.1).
                #
                # This branch used to rank outcome-pattern keyword matches,
                # then fall back to picking among all remaining binary
                # columns. Real-data findings showed both tiers are
                # undefensible:
                #
                #   (1) Hiring/OpenIntro_resume.csv: the true target
                #       'received_callback' scored the SAME 20%
                #       low-confidence bucket as 22 unrelated columns (no
                #       ranking within that bucket at all). The binary
                #       fallback then picked 'job_fed_contractor' -- not
                #       because it was more target-like, but purely because
                #       it sits earlier in the CSV's column order. 20 of
                #       this dataset's 30 columns are binary, so "is
                #       binary" has zero separating power here; there was
                #       no other signal to rank on.
                #   (2) COMPAS: is_recid / is_violent_recid /
                #       two_year_recid tied at 90% confidence with no
                #       statistical basis for preferring one recidivism
                #       definition over another -- a domain judgment call,
                #       not something inferable from the data (v3.7.4 only
                #       made this tie visible; it never had a principled
                #       way to break it).
                #
                # No dataset-side signal -- keyword match, cardinality, or
                # column position -- can substitute for knowing what a
                # dataset actually measures. This matches how the
                # established fairness toolkits already work: AIF360's
                # label_name, Fairlearn's y_true, and Aequitas's
                # label_value are all required, user-supplied inputs with
                # no auto-detection attempted. A ranked "top candidates"
                # shortlist was considered and rejected for the same
                # reason -- it would still imply a confidence this tier
                # cannot honestly claim.
                #
                # target_column is therefore a required argument. Fail
                # loudly and explain why, rather than silently guessing.
                # ------------------------------------------------------------
                available_preview = ", ".join(list(self.original_df.columns)[:15])
                more = "" if len(self.original_df.columns) <= 15 else f", ... and {len(self.original_df.columns) - 15} more"
                raise ValueError(
                    "A target column must be specified -- BiasClean does not "
                    "auto-detect the outcome/target column.\n"
                    "Only you know what this dataset measures and what "
                    "decision it represents (e.g. which column records "
                    "whether an applicant received a callback, a loan was "
                    "approved, or a defendant reoffended). No column-name "
                    "pattern or statistic can reliably substitute for that "
                    "knowledge -- this matches how AIF360, Fairlearn, and "
                    "Aequitas all require an explicit target/label column "
                    "with no auto-detection.\n"
                    f"Available columns include: {available_preview}{more}.\n"
                    "Please re-run with target_column set to the correct "
                    "column name for your dataset."
                )

            self.target_binarization_map = target_binarization_map
            if target_binarization_map:
                mapping_str = ", ".join(f"'{k}'→{v}" for k, v in target_binarization_map.items())
                logger.info(f"   Target '{final_target}' converted to binary: {mapping_str}")

            # Validate outcome
            outcome_validation = self.validator.validate_outcome(self.original_df, final_target)

            if outcome_validation.get("errors"):
                logger.info(f"   Outcome validation errors:")
                for error in outcome_validation["errors"]:
                    logger.info(f"      • {error}")

            if outcome_validation.get("warnings"):
                logger.info(f"   Outcome validation warnings:")
                for warning in outcome_validation["warnings"][:3]:  # Show first 3
                    logger.warning(f"      • {warning}")

            # Validate all mappings
            validated_proposals = {}
            validation_summary = {"passed": 0, "warnings": 0, "errors": 0}

            for column, mapping in raw_mappings.items():
                if column == final_target:
                    validated_proposals[column] = [{
                        **mapping,
                        "feature": "__outcome__",
                        "validation": outcome_validation
                    }]
                else:
                    feature = mapping.get("feature")
                    # v3.10.6 FIX (open item 6): this condition excluded
                    # "__exclude__" and None but not "__outcome__" -- so any
                    # column that Tier-2 pattern-matched as a plausible-but-
                    # unchosen outcome candidate (e.g. predicted_loan_approved
                    # on HMDA, not the actual final_target) still fell through
                    # into validate_protected_attribute(feature="__outcome__"),
                    # a nonsensical protected-attribute validation against a
                    # sentinel string. Confirmed inert/cosmetic: the resulting
                    # validation dict was already discarded downstream by
                    # _select_best_column_per_feature's own "__outcome__"
                    # skip (see that function's filter), so no delivered
                    # result was ever affected -- but it's dead, misleading
                    # work that shows up in column_mappings output. Now
                    # excluded here too, routing these columns to the same
                    # unvalidated-passthrough branch as __exclude__/None.
                    if feature and feature not in ["__exclude__", "__outcome__", None]:
                        validation = self.validator.validate_protected_attribute(
                            self.original_df, column, final_target, feature
                        )

                        if validation.get("errors"):
                            validation_summary["errors"] += 1
                        elif validation.get("warnings"):
                            validation_summary["warnings"] += 1
                        else:
                            validation_summary["passed"] += 1

                        # v3.10.6 FIX (open item 5): Tier 2 (domain-specific
                        # contextual_patterns) matches were flat-capped at
                        # 0.75 confidence regardless of how strong the
                        # match's actual statistical evidence turned out to
                        # be -- meaning even a domain match with an
                        # extremely low, highly significant p-value could
                        # never clear the 0.80 default auto-approval
                        # threshold on confidence alone (this is exactly
                        # why German Credit needed a manual
                        # auto_approve_threshold=0.70 override to include
                        # its real SES columns, see the v3.10.3->v3.10.4
                        # saga above). Now, once validation has actually
                        # run and a p-value is available, a Tier-2 match's
                        # confidence is adjusted upward from its 0.75 base
                        # by an amount that scales with how strong that
                        # evidence is -- capped at 0.81, deliberately kept
                        # just above the 0.80 default threshold but still
                        # below Tier 1/universal's 0.85 floor, so a
                        # domain-specific match can never outrank a
                        # universal one even at its strongest, and only
                        # genuinely strong evidence (p<0.001) can clear
                        # auto-approval without a manual override -- a
                        # weak or non-significant Tier-2 match stays at
                        # its original 0.75 and still requires one, which
                        # is the conservative behavior a fairness tool
                        # should default to. The original tier-assigned
                        # confidence is preserved under "base_confidence"
                        # for audit-trail transparency; this never touches
                        # Tier 1/universal matches (those already vary
                        # 85-98% via a different, pre-existing mechanism)
                        # or the __outcome__ tier (excluded from this
                        # branch entirely, see the item-6 fix above).
                        if mapping.get("tier") == "domain":
                            p_value = (validation.get("statistics", {}) or {}).get("p_value")
                            if p_value is not None:
                                if p_value < 0.001:
                                    bonus = 0.06
                                elif p_value < 0.01:
                                    bonus = 0.04
                                elif p_value < 0.05:
                                    bonus = 0.02
                                else:
                                    bonus = 0.0
                                base_confidence = mapping.get("confidence", 0.75)
                                mapping = {
                                    **mapping,
                                    "base_confidence": base_confidence,
                                    "confidence": min(base_confidence + bonus, 0.81),
                                }

                        validated_proposals[column] = [{
                            **mapping,
                            "validation": validation
                        }]
                    else:
                        validated_proposals[column] = [mapping]

            logger.info(f"\n   Validation Summary:")
            logger.info(f"     Passed:   {validation_summary['passed']}")
            logger.info(f"     Warnings: {validation_summary['warnings']}")
            logger.info(f"     Errors:   {validation_summary['errors']}")

            # ================================================================
            # PHASE 4: MAPPING CONFIRMATION (AUTO-APPROVAL)
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 4: MAPPING CONFIRMATION")
            logger.info(f"{'='*80}")

            self.approved_mappings = self.ui.auto_approve_high_confidence(
                validated_proposals, threshold=auto_approve_threshold,
                total_records=len(self.original_df)
            )

            if not self.approved_mappings:
                raise ValueError("No mappings approved. Lower threshold or check data quality.")

            # ================================================================
            # PHASE 5: PREPARE FOR BIAS ANALYSIS
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 5: PREPARATION FOR BIAS ANALYSIS")
            logger.info(f"{'='*80}")

            # Build feature map (exclude outcome and excluded columns).
            # v3.6.7: selection is now validation-aware (see
            # _select_best_column_per_feature) instead of a blind
            # last-approved-wins overwrite -- see that method's
            # docstring for the real-data cases this fixes.
            feature_map = self._select_best_column_per_feature(self.approved_mappings)

            # v3.5.0: feature_map is ONE column per canonical feature.
            # Real-data finding: this left the raw numeric 'age' column
            # completely unexcluded from the SVM's own predictor set -- a
            # genuine protected-attribute leak through an unmapped alias
            # column, found by directly inspecting what the classifier was
            # actually training on. self.all_protected_columns keeps EVERY
            # raw column that was approved-mapped to any protected feature,
            # so the SVM stage can exclude all of them, not just the one
            # feature_map happens to remember.
            self.all_protected_columns = [
                column for column, mapping in self.approved_mappings.items()
                if mapping.get("feature") not in ["__outcome__", "__exclude__", None]
            ]

            self.engine._feature_map = feature_map
            self.engine._target_column = final_target

            logger.info(f"   Target column: '{final_target}'")
            logger.info(f"   Features for analysis (with domain weights):")
            for feature, column in feature_map.items():
                weight = self.config["weights"].get(feature, 0.05)
                logger.info(f"     • {feature:25} ← {column:30} (weight: {weight:.2f})")

            # ================================================================
            # PHASE 3.5: PRE-MITIGATION AUDIT (v3.0 NEW)
            # ================================================================
            if self.mode in [config.MODE_AUDIT_FIRST, config.MODE_AUDIT_ONLY]:
                logger.info(f"\n{'='*80}")
                logger.info("PHASE 3.5: PRE-MITIGATION AUDIT (v3.0)")
                logger.info(f"{'='*80}")

                # Convert approved_mappings to feature_map format for auditor
                # (v3.6.7: same validation-aware selection as PHASE 5, so the
                # audit path can't disagree with the actual analysis about
                # which column represents each feature)
                audit_feature_map = self._select_best_column_per_feature(self.approved_mappings)

                auditor = PreMitigationAuditor(self.config["weights"])
                audit_results = auditor.audit(
                    self.original_df,
                    final_target,
                    audit_feature_map
                )

                # Store for results
                self.audit_results = audit_results

                # Block if RED
                if not audit_results["recommendation"]["proceed"]:
                    logger.info(f"\n🛑 MITIGATION BLOCKED by v3.0 Audit")
                    return self._compile_audit_only_results(audit_results, final_target, feature_map)

                # Stop if audit-only mode
                if self.mode == config.MODE_AUDIT_ONLY:
                    logger.info(f"\n🔍 AUDIT-ONLY MODE - STOPPING")
                    return self._compile_audit_only_results(audit_results, final_target, feature_map)

                logger.info(f"\n✅ AUDIT APPROVED - PROCEEDING")

            # ================================================================
            # PHASE 6: BIAS DETECTION & STATISTICAL DIAGNOSIS (v2.7 ENHANCED)
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 6: BIAS DETECTION & STATISTICAL DIAGNOSIS")
            logger.info(f"{'='*80}")

            # Initialize v2.7 monitoring components
            stage_tracker = EnhancedStageScoreTracker(self.config["weights"])
            confidence_calculator = StatisticalConfidenceCalculator(n_bootstrap=500, ci_level=0.95)
            group_tracker = GroupRateTracker()
            sampling_logger = SamplingAttributionLogger()

            # Run enhanced statistical diagnosis
            diagnostic_results = self._run_statistical_diagnosis_v27(feature_map, final_target)

            # v2.7: Record initial stage
            stage_tracker.record_stage(
                'initial',
                self.original_df,
                feature_map,
                final_target,
                self.engine,
                diagnostic_results['initial_bias_score'],
                confidence_calculator
            )

            logger.info(f"\n   Initial Bias Score: {diagnostic_results['initial_bias_score']:.4f}")
            logger.info(f"   Significant Biases: {diagnostic_results['significant_bias_count']}")

            # v2.7: Print statistical confidence
            if 'statistical_confidence' in diagnostic_results:
                conf = diagnostic_results['statistical_confidence'].get('initial', {})
                if conf:
                    bias_score = conf.get('bias_score', 0)
                    ci_lower = conf.get('ci_lower', 0)
                    ci_upper = conf.get('ci_upper', 0)
                    logger.info(f"   Statistical Confidence: {bias_score:.4f} [{ci_lower:.4f}, {ci_upper:.4f}] (95% CI)")
                    if conf.get('significant', False):
                        logger.info(f"   ✓ Statistically significant bias detected")

            if diagnostic_results.get("feature_tests"):
                logger.info(f"\n   Statistical Tests (sorted by domain weight):")
                # Sort by weight
                sorted_tests = sorted(
                    diagnostic_results["feature_tests"].items(),
                    key=lambda x: self.config["weights"].get(x[0], 0),
                    reverse=True
                )
                for feature, test in sorted_tests:
                    sig = "SIGNIFICANT" if test.get("significant_bias") else "OK"
                    p_val = test.get("p_value", 1.0)
                    weight = self.config["weights"].get(feature, 0.05)
                    threshold = test.get("threshold_used", 0.05)  # Show weight-adjusted threshold
                    logger.info(f"     • {feature:25} p={p_val:.6f}  {sig}  (weight: {weight:.2f}, threshold: {threshold:.3f})")

            # ============================================================================
            # PHASE 7: BIAS MITIGATION (WEIGHT-PRIORITIZED) + SVM FAIRNESS ENFORCEMENT
            # ============================================================================
            if diagnostic_results["requires_mitigation"]:
                logger.info(f"\n{'='*80}")
                logger.info("PHASE 7: WEIGHT-PRIORITIZED BIAS MITIGATION + SVM FAIRNESS ENFORCEMENT")
                logger.info(f"{'='*80}")

                logger.info(f"   Applying weight-prioritized rebalancing...")

                self.corrected_df = self.engine.transform_industry(
                    self.original_df, diagnostic_results, rebalance_method=self.rebalance_method
                )

                # v3.2.0: capture Preferential Sampling's per-feature method/
                # exclusion log and the rebalancing-stage reversal check,
                # both computed inside transform_industry(). Read here (not
                # deferred to _save_results) so a post-SVM reversal check can
                # be layered on top of the same self.reversal_checks dict
                # below, without the SVM block needing engine internals.
                self.rebalance_log = list(self.engine.rebalance_log)
                self.reversal_checks = dict(getattr(self.engine, "reversal_checks", {}) or {})

                # v3.4.0 Fairness Regulator ("the thermostat" -- proactive
                # clip in _rebalance_feature_weighted/_rebalance_feature_
                # reweighing) already prevents each feature's OWN pass from
                # overshooting past parity. v3.10.5 REBALANCE-STAGE FUSE
                # (reactive, inside transform_industry itself): actively
                # excludes and reverts any feature whose rebalancing still
                # produced an actionable reversal -- e.g. via a LATER
                # feature's pass perturbing an EARLIER feature's row
                # composition through row-level overlap, which the
                # per-feature thermostat can't see -- and redoes the
                # remaining features' correction from the original data
                # without it. Replaces the old v3.4.0 flag-only behavior
                # (found insufficient on real Governance/ACS data: Hamid's
                # explicit direction was that a thermostat/fuse design
                # built to prevent the pipeline creating new victims must
                # not just disclose an overcorrection and still deliver
                # it). self.reversal_checks and self.rebalance_log here
                # already reflect transform_industry's FINAL attempt, so
                # normally nothing is left to report as still-actionable --
                # only the (rare) case where the bounded retry limit was
                # reached still surfaces here.
                threshold_by_feature = {
                    e.get("feature"): e.get("disparity_threshold")
                    for e in self.rebalance_log if e.get("disparity_threshold") is not None
                }
                actionable_reversals = []
                near_parity_reversals = []
                for feature, check in self.reversal_checks.items():
                    if not (check and check.get("reversed")):
                        continue
                    threshold = threshold_by_feature.get(feature)
                    gap = check.get("after_gap")
                    if threshold is not None and gap is not None and gap < threshold:
                        near_parity_reversals.append(feature)
                    else:
                        actionable_reversals.append(feature)

                excluded_features = list(getattr(self.engine, "rebalance_excluded_features", []) or [])

                if actionable_reversals:
                    # Retry limit was reached with a reversal still
                    # unresolved -- same honest last-resort disclosure as
                    # before, now explicitly noting exclusion was already
                    # attempted first.
                    reason = (
                        f"the rebalance-stage fuse excluded {len(excluded_features)} feature(s) "
                        f"but still could not fully resolve a reversal in: "
                        f"{', '.join(actionable_reversals)} -- needs manual review before "
                        f"trusting these features' rebalanced rates"
                    ) if excluded_features else (
                        f"regulator did not fully prevent a reversal in: "
                        f"{', '.join(actionable_reversals)} -- needs manual review before "
                        f"trusting these features' rebalanced rates"
                    )
                elif excluded_features:
                    names = ", ".join(e["feature"] for e in excluded_features)
                    reason = (
                        f"rebalance-stage fuse excluded {len(excluded_features)} feature(s) that "
                        f"reversed the disadvantaged group during correction ({names}) -- reverted "
                        f"to original (uncorrected) values for those, then successfully rebalanced "
                        f"the remaining feature(s) without reversal"
                    )
                else:
                    reason = "no actionable reversal detected after rebalancing (regulator held)"

                self.rebalance_gate = {
                    "accepted": len(actionable_reversals) == 0,
                    "reason": reason,
                    "reversed_features": actionable_reversals,
                    "near_parity_reversals": near_parity_reversals,
                    "excluded_features": excluded_features,
                }
                if excluded_features:
                    for e in excluded_features:
                        logger.warning(f"\n   ⛔ REBALANCE FUSE: '{e['feature']}' was excluded and "
                              f"reverted to its original values after reversing the disadvantaged "
                              f"group ('{e['disadvantaged_before']}' -> '{e['disadvantaged_after']}').")
                if actionable_reversals:
                    logger.warning(f"\n   ⛔ REBALANCE GATE: still unresolved after the fuse's retry "
                          f"limit -- reversal remains in: {', '.join(actionable_reversals)}. Flagged "
                          f"for manual review -- see audit_trail.json's rebalance_gate block.")
                if near_parity_reversals:
                    logger.warning(f"\n   ℹ️  Near-parity rank swap (not gated -- gap below this feature's "
                          f"own disparity threshold): {', '.join(near_parity_reversals)}")

                # v2.7: Log rebalancing sampling changes
                sampling_logger.log_rebalancing_changes(
                    self.original_df, self.corrected_df, feature_map, final_target
                )

                # Calculate final bias score
                final_bias = self.engine.score(self.corrected_df, final_target)
                diagnostic_results["final_bias_score"] = final_bias

                # Record post-rebalancing scores for monitoring (v2.7).
                # Pass the already-computed final_bias explicitly rather
                # than None -- leaving this None made record_stage fall
                # back to EnhancedStageScoreTracker's own bias formula
                # (a different, weight-normalized-range calculation, not
                # the CV-based weighted sum every other stage and the
                # report use), which could make the 'rebalanced' stage
                # look worse than 'initial' even when the real, consistent
                # final_bias_score had genuinely improved.
                stage_tracker.record_stage(
                    'rebalanced',
                    self.corrected_df,  # After rebalancing
                    feature_map,
                    final_target,
                    self.engine,
                    final_bias,
                    confidence_calculator
                )

                initial_bias = diagnostic_results["initial_bias_score"]
                improvement = ((initial_bias - final_bias) / initial_bias * 100) if initial_bias > 0 else 0

                logger.info(f"\n   Bias Score: {initial_bias:.4f} → {final_bias:.4f}")
                logger.info(f"   Improvement: {improvement:+.1f}%")

                # Validate results
                validation = self.engine.validate_industry_readiness(
                    self.original_df, self.corrected_df, diagnostic_results
                )

                logger.info(f"\n   Data Integrity:")
                logger.info(f"     • Records: {validation['data_integrity']['records_before']:,} → {validation['data_integrity']['records_after']:,}")
                logger.info(f"     • Retention: {validation['data_integrity']['retention_rate']:.1f}%")

                if validation.get("fairness_improvement"):
                    logger.info(f"\n   Fairness Improvements (sorted by weight):")
                    # Sort by weight
                    sorted_improvements = sorted(
                        validation["fairness_improvement"].items(),
                        key=lambda x: self.config["weights"].get(x[0], 0),
                        reverse=True
                    )
                    for feature, imp in sorted_improvements:
                        icon = "✅" if imp > 0 else "⚠️"
                        weight = self.config["weights"].get(feature, 0.05)
                        logger.info(f"     {icon} {feature:25} {imp:+.1f}%  (weight: {weight:.2f})")

                # ========================================================================
                # SVM FAIRNESS ENFORCEMENT (v3.0: Configurable)
                # ========================================================================
                if self.enable_svm:
                    logger.info(f"\n   Applying SVM fairness enforcement...")

                    # Determine primary protected attribute for SVM monitoring
                    primary_protected_attr = None
                    max_weight = 0
                    for feature, weight in self.config["weights"].items():
                        if feature in feature_map and weight > max_weight:
                            max_weight = weight
                            primary_protected_attr = feature_map[feature]

                    try:
                        # Initialize SVM enforcer with domain weights
                        svm_enforcer = SVMFairnessEnforcer(
                            domain_weights=self.config["weights"],
                            random_state=42,
                            svm_method=self.svm_method,
                            fairness_constraint=self.fairness_constraint
                        )

                        # Apply SVM fairness enforcement to corrected dataset
                        svm_results = svm_enforcer.enforce_fairness(
                            df=self.corrected_df,
                            feature_map=feature_map,
                            target_column=final_target,
                            group_column=primary_protected_attr,
                            validation_split=0.25,
                            all_protected_columns=getattr(self, "all_protected_columns", None)
                        )

                        # v3.5.0: enforce_fairness() cleanly skips (rather
                        # than crashing or training on zero features) when
                        # no usable predictor columns remain. Route to a
                        # dedicated except clause below for accurate
                        # fallback + messaging, distinct from a genuine
                        # crash.
                        if svm_results.get('skipped'):
                            raise _SVMSkippedNoFeatures(svm_results.get('skip_reason', 'no usable predictor columns'))

                        # Update corrected_df with SVM-enhanced version
                        self.corrected_df = svm_results['enhanced_dataframe']
                        # CRITICAL FIX: Preserve BiasClean's corrected target, add SVM predictions as separate column
                        self.corrected_df['biasclean_target'] = self.corrected_df[final_target].copy()
                        self.corrected_df['svm_fair_target'] = svm_results['svm_predictions']

                        # v2.7: Log SVM prediction changes
                        sampling_logger.log_svm_changes(
                            self.corrected_df, final_target, 'svm_fair_target'
                        )

                        # BUG FIX (v3.2.2): this call used to pass bias_score=None,
                        # which made record_stage() fall back to
                        # EnhancedStageScoreTracker._calculate_bias_score() --
                        # a DIFFERENT formula than every other stage. 'initial'
                        # and 'rebalanced' both get their score from
                        # BiasCleanEngine.score(): a raw weighted SUM
                        # (weight * disparity, no normalization -- see that
                        # method's own docstring for why). The None-triggered
                        # fallback instead computes a weighted AVERAGE
                        # (np.average(disparities, weights=weights), i.e.
                        # divided by the SUM of weights used -- 0.45 for
                        # Justice's 3 present features). Dividing by 0.45
                        # inflates the number by ~2.2x relative to the SUM
                        # formula 'initial' uses. Confirmed on real COMPAS
                        # data: engine.score() on the exact same post-SVM
                        # dataframe gives 0.132; the None-fallback gave 0.443
                        # -- the number bias_scores.final has been reporting,
                        # and the number every "SVM made bias N% worse" claim
                        # in this pipeline's reports has been computed from,
                        # since before this fix existed. The DIRECTION of the
                        # finding (SVM increases disparity, causes reversals)
                        # is unaffected -- that was independently confirmed
                        # via raw group rates and the reversal_checks block,
                        # neither of which used this formula. Only the
                        # MAGNITUDE shown in bias_scores.final and the
                        # improvement-% figure was wrong, because it compared
                        # a SUM-formula initial score against an
                        # AVERAGE-formula final score -- two different scales.
                        svm_bias_score_correct = self.engine.score(self.corrected_df, 'svm_fair_target')
                        stage_tracker.record_stage(
                            'svm',
                            self.corrected_df,  # After SVM
                            feature_map,
                            'svm_fair_target',  # Use SVM predictions
                            self.engine,
                            svm_bias_score_correct,  # explicit -- see fix note above
                            confidence_calculator
                        )
                        stage_tracker.stages['final'] = stage_tracker.stages['svm']

                        # CRITICAL FIX: diagnostic_results["final_bias_score"] was
                        # being left frozen at the post-rebalancing value computed
                        # at line ~3262 -- the SVM block updated stage_tracker's
                        # 'final' stage but never touched diagnostic_results. Two
                        # things downstream both read diagnostic_results instead
                        # of stage_tracker: (1) the top-level "bias_scores.final"
                        # in audit_trail.json, which is what the plain-language
                        # PDF summary shows, and (2) _compute_feature_interactions'
                        # compensatory-trade-off / worsened-features detection.
                        # Net effect: when SVM enforcement made things dramatically
                        # WORSE (observed on the COMPAS dataset: bias score went
                        # from 0.066 after rebalancing to 0.445 after SVM -- worse
                        # than even the original unmitigated 0.095), the report
                        # still confidently displayed "+31% improvement, 0.07"
                        # using the stale pre-SVM number, completely hiding the
                        # regression from the one place a no-code user would
                        # actually look.
                        pre_svm_bias = diagnostic_results.get("final_bias_score", final_bias)
                        svm_bias_score = stage_tracker.stages['svm'].get('bias_score')
                        if svm_bias_score is not None:
                            diagnostic_results["final_bias_score"] = svm_bias_score

                        svm_worsened_fairness = (
                            svm_bias_score is not None and svm_bias_score > pre_svm_bias
                        )
                        if svm_worsened_fairness:
                            logger.warning(f"\n   ⚠️  WARNING: SVM enforcement INCREASED measured bias "
                                  f"({pre_svm_bias:.4f} → {svm_bias_score:.4f}). The SVM stage "
                                  f"reports disparity in its OWN predictions, not the rebalanced "
                                  f"data's real outcome rates -- a poorly-fit or miscalibrated "
                                  f"classifier (e.g. very strong regularization) can easily be "
                                  f"less fair than the data it was trained on. Consider disabling "
                                  f"SVM enforcement for this dataset, or reviewing its accuracy "
                                  f"below before trusting 'svm_fair_target'.")

                        # Store SVM results for reporting
                        svm_validation = {
                            'svm_applied': True,
                            'svm_accuracy': svm_results.get('full_accuracy', 0),
                            'svm_validation_accuracy': svm_results.get('validation_accuracy', 0),
                            'svm_fairness_metrics': svm_results['fairness_metrics'],
                            'svm_model_config': svm_results['model_config'],
                            'svm_feature_count': len(svm_results['feature_columns']),
                            'pre_svm_bias_score': pre_svm_bias,
                            'post_svm_bias_score': svm_bias_score,
                            # v3.10.10 FIX: post_svm_bias_score gets overwritten to
                            # pre_svm_bias_score below (~line 7826, the v3.6.2 fix)
                            # whenever the gate rejects, so any consumer that needs
                            # the classifier's ACTUAL computed score -- not the
                            # after-fallback number -- has nowhere left to read it
                            # from. report.pdf's "Why this recommendation" narrative
                            # is exactly that consumer (see plain_reasons ~line
                            # 5037): it needs the true pre/post numbers to explain
                            # HOW MUCH worse SVM made things, and was silently
                            # degenerating into "from 0.030 to 0.030" once
                            # post_svm_bias_score got overwritten on rejection. This
                            # key is set once here and never touched again.
                            'raw_svm_bias_score': svm_bias_score,
                            'svm_worsened_fairness': svm_worsened_fairness,
                        }

                        # v3.2.0: reversal check for the SVM stage too, same
                        # logic as the rebalancing-stage one -- SVM predictions
                        # live in their own 'svm_fair_target' column
                        # (self.corrected_df[final_target] is untouched, see
                        # the CRITICAL FIX above), so this is compared against
                        # the ORIGINAL pre-mitigation data, not the rebalanced
                        # data, to answer "did SVM end up disadvantaging a
                        # different group than the one disadvantaged before
                        # any correction at all." Deliberately wrapped in its
                        # own try/except, separate from _detect_reversal's
                        # internal one: this whole block must never be able
                        # to reach the outer SVM try/except below, which
                        # would discard an otherwise-successful SVM result
                        # and silently reintroduce the exact bias_scores
                        # .final mismatch the 3.1.2 fix exists to prevent.
                        self.svm_reversal_checks = {}
                        try:
                            for feature, column in feature_map.items():
                                self.svm_reversal_checks[feature] = self.engine._detect_reversal(
                                    self.original_df, self.corrected_df, column, 'svm_fair_target',
                                    target_before=final_target
                                )
                        except Exception as e:
                            logger.warning(f"       (Post-SVM reversal check unavailable: {e})")

                        # v3.3.0: mandatory validation gate. A classifier stage
                        # that claims to improve fairness must actually be
                        # checked against the stage it's replacing -- silently
                        # trusting whatever the SVM/ExponentiatedGradient
                        # produced is exactly how the bias_scores.final
                        # formula bug (v3.2.2) and every prior "SVM made
                        # things worse but the report didn't say so" case
                        # happened. Reject (fall back to rebalanced
                        # predictions) if EITHER: (a) the correctly-computed
                        # composite score got worse, or (b) SVM introduced a
                        # NEW reversal not already present after rebalancing.
                        # Both self.reversal_checks (rebalancing stage) and
                        # self.svm_reversal_checks (SVM stage) are computed
                        # against the SAME original-raw-data baseline (see
                        # target_before= usage above), so "already reversed"
                        # vs. "newly reversed" is a same-basis comparison.
                        new_reversals = []
                        for feature, svm_check in (self.svm_reversal_checks or {}).items():
                            if not svm_check or not svm_check.get('reversed'):
                                continue
                            reb_check = (self.reversal_checks or {}).get(feature)
                            already_reversed = bool(reb_check and reb_check.get('reversed'))
                            if not already_reversed:
                                new_reversals.append(feature)

                        # v3.5.0: explicit degenerate-classifier detection.
                        # Real-data finding: fairlearn's ExponentiatedGradient
                        # can collapse to predicting the SAME class for every
                        # single row when starved of real predictive signal
                        # (observed on real COMPAS: svm_positive_rate=0.0,
                        # 7,238/7,238 rows predicted identically). A constant
                        # prediction trivially reads as "0 disparity" and
                        # previously only got caught BY ACCIDENT, when the
                        # reversal check's tie-breaking among identically-
                        # scored groups happened to flip which one looked
                        # "lowest". That's not reliable -- a collapsed
                        # classifier that happens to preserve the original
                        # tie-break order would have been silently ACCEPTED.
                        # Checked directly and deterministically instead: a
                        # classifier with only one unique predicted value
                        # has zero discriminative value regardless of what
                        # the reversal/score checks say.
                        svm_predictions_arr = svm_results.get('svm_predictions')
                        svm_collapsed = (
                            svm_predictions_arr is not None
                            and len(set(np.asarray(svm_predictions_arr).tolist())) <= 1
                        )

                        svm_gate_accept = (
                            not svm_worsened_fairness
                            and len(new_reversals) == 0
                            and not svm_collapsed
                        )

                        if svm_gate_accept:
                            self.svm_gate = {
                                'accepted': True,
                                'reason': 'SVM stage composite score did not worsen fairness and introduced no new reversals.',
                                'svm_method_used': svm_results.get('svm_method_used'),
                                'new_reversals': [],
                            }
                        else:
                            gate_reasons = []
                            if svm_collapsed:
                                gate_reasons.append(
                                    "classifier collapsed to a single constant prediction across all "
                                    f"{len(svm_predictions_arr):,} rows -- no discriminative value"
                                )
                            if svm_worsened_fairness:
                                gate_reasons.append(
                                    f"composite bias score worsened ({pre_svm_bias:.4f} -> {svm_bias_score:.4f})"
                                )
                            if new_reversals:
                                gate_reasons.append(
                                    "introduced new disadvantaged-group reversal(s) not present after "
                                    f"rebalancing: {', '.join(new_reversals)}"
                                )
                            gate_reason_text = "; ".join(gate_reasons)
                            logger.warning(f"\n   ⛔ VALIDATION GATE: rejecting SVM/classifier output -- {gate_reason_text}.")
                            logger.info(f"   Falling back to rebalanced predictions for the final stage.")
                            self.svm_gate = {
                                'accepted': False,
                                'reason': gate_reason_text,
                                'svm_method_used': svm_results.get('svm_method_used'),
                                'new_reversals': new_reversals,
                            }
                            # Fall back to the rebalanced stage -- same pattern
                            # already used when SVM is disabled or errors out.
                            self.corrected_df['svm_fair_target'] = self.corrected_df['biasclean_target']
                            diagnostic_results["final_bias_score"] = pre_svm_bias
                            stage_tracker.stages['final'] = stage_tracker.stages['rebalanced']
                            svm_validation['gate_rejected'] = True
                            # v3.6.2 FIX: svm_validation['post_svm_bias_score'] was
                            # set earlier (before the gate check) to the REJECTED
                            # classifier's own score and never touched again on
                            # this branch -- so audit_trail.json's
                            # svm_enforcement.post_svm_bias_score kept reporting
                            # a number that was explicitly thrown away, while
                            # bias_scores.final (from diagnostic_results, fixed
                            # two lines up) correctly showed the fallback. Real
                            # instance: a degenerate/collapsed classifier scored
                            # 0.0 (trivially "fair" by predicting one constant
                            # value for every row) and got rejected for exactly
                            # that reason -- but svm_enforcement still showed
                            # "post_svm_bias_score": 0.0 next to bias_scores.final
                            # 0.068, which a reader could easily mistake for "SVM
                            # nearly eliminated bias" instead of "SVM's number was
                            # discarded." Same class of bug as the 3.2.2 fix
                            # (report and audit_trail must never show two
                            # different numbers both implicitly labeled "what
                            # actually happened"), just the other side of the
                            # accept/reject branch never having had a real-data
                            # regression test that exercised gate rejection until
                            # this validation round's collapsed-classifier case
                            # ran through the (newly import-fixed) regression
                            # suite for the first time.
                            svm_validation['post_svm_bias_score'] = pre_svm_bias

                        logger.info(f"\n   SVM Fairness Enforcement Complete:")
                        if svm_results.get('validation_accuracy'):
                            logger.info(f"     • Validation accuracy: {svm_results['validation_accuracy']:.1%}")
                        logger.info(f"     • Full dataset accuracy: {svm_results['full_accuracy']:.1%}")
                        logger.info(f"     • SVM method: {svm_results.get('svm_method_used', 'legacy')}")
                        logger.warning(f"     • Validation gate: {'ACCEPTED' if self.svm_gate.get('accepted') else 'REJECTED (' + self.svm_gate.get('reason', '') + ')'}")
                        logger.info(f"     • SVM fairness predictions added as 'svm_fair_target' column")
                        logger.info(f"     • BiasClean predictions preserved as 'biasclean_target' column")
                        if 'disparity' in svm_results['fairness_metrics']:
                            logger.info(f"     • Group disparity: {svm_results['fairness_metrics']['disparity']:.3f}")

                    except _SVMSkippedNoFeatures as e:
                        # v3.5.0: a clean, deliberate skip -- NOT a crash.
                        # Distinct except clause so this gets accurate
                        # messaging/labeling instead of "SVM enforcement
                        # failed", which would misrepresent a safe,
                        # intentional decision as an error.
                        logger.info(f"\n   ⏸️  SVM SKIPPED: {e}")
                        logger.info(f"   Continuing with BiasClean-only mitigation...")
                        svm_validation = {
                            'svm_applied': False,
                            'reason': f'SVM skipped -- {e}',
                            'post_svm_bias_score': self.engine.score(self.corrected_df, final_target),
                        }
                        self.svm_gate = {
                            'accepted': None,
                            'reason': f'SVM skipped -- {e} -- gate not applicable.',
                            'svm_method_used': None,
                            'new_reversals': [],
                        }
                        self.corrected_df['biasclean_target'] = self.corrected_df[final_target].copy()
                        self.corrected_df['svm_fair_target'] = self.corrected_df[final_target].copy()
                        stage_tracker.record_stage(
                            'svm', self.corrected_df, feature_map, 'svm_fair_target',
                            self.engine, svm_validation['post_svm_bias_score'], confidence_calculator
                        )
                        stage_tracker.stages['final'] = stage_tracker.stages['svm']
                    except Exception as e:
                        logger.warning(f"\n   ⚠️ SVM enforcement failed: {str(e)}")
                        logger.info(f"   Continuing with BiasClean-only mitigation...")
                        svm_validation = {
                            'svm_error': str(e),
                            'svm_applied': False
                        }
                        self.svm_gate = {
                            'accepted': False,
                            'reason': f'SVM enforcement raised an exception before a result could be gated: {e}',
                            'svm_method_used': None,
                            'new_reversals': [],
                        }
                        # Use rebalanced data as final output
                        self.corrected_df['biasclean_target'] = self.corrected_df[final_target].copy()
                        self.corrected_df['svm_fair_target'] = self.corrected_df[final_target].copy()
                        stage_tracker.stages['final'] = stage_tracker.stages['rebalanced']
                else:
                    logger.info(f"\n   ⏸️  SVM DISABLED - USING REBALANCED PREDICTIONS")
                    svm_validation = {
                        'svm_applied': False,
                        'reason': 'Using rebalanced predictions directly',
                        'post_svm_bias_score': self.engine.score(self.corrected_df, final_target)
                    }
                    self.svm_gate = {
                        'accepted': None,
                        'reason': 'SVM disabled -- gate not applicable.',
                        'svm_method_used': None,
                        'new_reversals': [],
                    }
                    # Use rebalanced data as final output (no SVM corruption)
                    self.corrected_df['biasclean_target'] = self.corrected_df[final_target].copy()
                    self.corrected_df['svm_fair_target'] = self.corrected_df[final_target].copy()  # Same as rebalanced
                    logger.info(f"   ✓ Final bias score: {svm_validation['post_svm_bias_score']:.4f}")

                    # v2.7: Record stage with rebalanced data
                    stage_tracker.record_stage(
                        'svm',
                        self.corrected_df,  # Using rebalanced data
                        feature_map,
                        'svm_fair_target',
                        self.engine,
                        svm_validation['post_svm_bias_score'],
                        confidence_calculator
                    )
                    stage_tracker.stages['final'] = stage_tracker.stages['svm']

                # BUG FIX (v3.7.2): validation['final_disparities'] (and the
                # fairness_improvement / absolute_disparity_reduction derived
                # from it) were computed once above at PHASE 7's rebalancing
                # step, BEFORE the SVM block even starts, and never revisited
                # -- see the v3.7.2 changelog entry for the full root-cause
                # writeup and the real Communities & Crime run that surfaced
                # it. Recompute the "final" side against whichever column
                # actually holds the pipeline's true final predictions:
                # 'svm_fair_target' when self.corrected_df has it (every SVM
                # branch above sets it -- accepted, gate-rejected [already
                # falls back to biasclean_target inside that same column],
                # skipped, errored, or disabled all leave 'svm_fair_target'
                # holding the correct effective-final values), else
                # final_target (only when no SVM stage of any kind ran).
                # initial_disparities is untouched -- it's computed against
                # self.original_df, which SVM never touches, so it was never
                # wrong; only the final/improvement side needs redoing.
                effective_final_target = (
                    'svm_fair_target'
                    if (self.corrected_df is not None and 'svm_fair_target' in self.corrected_df.columns)
                    else final_target
                )
                if effective_final_target != final_target and self.corrected_df is not None:
                    for feature, test_result in diagnostic_results.get("feature_tests", {}).items():
                        if not test_result.get("significant_bias", False):
                            continue
                        column_name = test_result.get("column_name")
                        if not column_name or column_name not in self.corrected_df.columns:
                            continue
                        before = validation["initial_disparities"].get(feature)
                        after = self.engine._calculate_disparity_direct(
                            self.corrected_df, column_name, effective_final_target
                        )
                        validation["final_disparities"][feature] = after
                        if before is not None and before > 0:
                            validation["fairness_improvement"][feature] = ((before - after) / before) * 100
                            validation["absolute_disparity_reduction"][feature] = before - after

                        # PHASE 3.5, Workstream C: the worst-group figure
                        # needs the same post-SVM recompute as the CV
                        # figure just above it, for the same reason bug #6
                        # existed -- otherwise this new field would freeze
                        # at the pre-SVM snapshot on day one.
                        worst_before = validation["initial_worst_group_deviation"].get(feature)
                        worst_group_after, worst_after = self.engine._calculate_worst_group_deviation_direct(
                            self.corrected_df, column_name, effective_final_target
                        )
                        validation["final_worst_group"][feature] = worst_group_after
                        validation["final_worst_group_deviation"][feature] = worst_after
                        if worst_before is not None and worst_before > 0:
                            validation["worst_group_improvement_pct"][feature] = (
                                (worst_before - worst_after) / worst_before
                            ) * 100

                # PHASE 3.5, Workstream A: worst-group safeguard (warn-only).
                # This is deliberately NOT a gate yet -- per the Phase 3.5
                # SOP, the plan is to see what this actually flags across
                # real datasets first, before deciding whether it should
                # ever reject a correction the way svm_gate already does
                # for identity-reversals. This check asks a different
                # question than reversal_checks: not "did the disadvantaged
                # group's IDENTITY change" but "did ANY group's OWN
                # deviation from parity get WORSE in magnitude" -- the
                # exact gap reversal_checks cannot see, since a feature's
                # composite/CV score can improve even while a specific
                # group is left worse off (the real North Carolina Gender
                # case that motivated this: a near-null 0.0025 raw gap
                # widened to 0.0060 after correction, invisible to every
                # existing gate because the dataset's other features
                # carried the composite average).
                #
                # Two trigger conditions, matching the SOP's proposed
                # tolerance: (1) the worst group's own deviation got more
                # than 10% relatively worse, or (2) the gap started under
                # the near-null floor (reusing 0.05, the same number as
                # the composite mitigation threshold, so this project has
                # one shared definition of "near-null" rather than two)
                # and widened at all, however small the relative percentage
                # looks. Condition 2 exists because a tiny absolute change
                # on an already-tiny base can look like a huge percentage
                # (or a deceptively small one) and either way deserves a
                # human's attention, not a threshold's assumption.
                self.worst_group_regressions = []
                _tolerance_pct = -10.0
                _near_null_floor = 0.05
                for feature in validation.get("initial_worst_group_deviation", {}):
                    before_dev = validation["initial_worst_group_deviation"].get(feature)
                    after_dev = validation["final_worst_group_deviation"].get(feature)
                    if before_dev is None or after_dev is None:
                        continue
                    pct = validation.get("worst_group_improvement_pct", {}).get(feature)
                    reason = None
                    if pct is not None and pct < _tolerance_pct:
                        reason = f"worst-group deviation worsened by {abs(pct):.1f}% (relative)"
                    elif before_dev < _near_null_floor and after_dev > before_dev:
                        reason = f"a near-null gap ({before_dev:.4f}) widened to {after_dev:.4f}"
                    if reason:
                        group = validation.get("final_worst_group", {}).get(feature)

                        # PHASE 3.5, Workstream A+B integration (Hamid's
                        # chosen option: wire Workstream B in as an
                        # ADDITIONAL signal alongside Workstream A's
                        # existing magnitude check, not as a replacement
                        # for requires_mitigation's composite pre-check,
                        # which is deliberately left untouched). Cross-
                        # references this regression against Workstream
                        # B's dual-criteria test on the SAME feature's
                        # post-correction data: is the resulting gap
                        # itself still statistically AND practically
                        # distinguishable from parity, or is Workstream A
                        # flagging a real relative worsening that landed
                        # on an absolute gap too small to matter? These
                        # can genuinely disagree -- verified on real North
                        # Carolina data: Gender is a relative 136.6%
                        # regression (Workstream A fires) whose resulting
                        # ratio (1.005) is still practically negligible
                        # (Workstream B's dual test says False) -- both
                        # true at once, not a contradiction. Two
                        # independent lenses agreeing (as they do on this
                        # project's Age/Region findings) is a much
                        # stronger signal for a reviewer than either
                        # alone; two lenses disagreeing (as on Gender) is
                        # itself useful context, not noise to suppress.
                        dual_significant_final = None
                        test_result = diagnostic_results.get("feature_tests", {}).get(feature, {})
                        column_name = test_result.get("column_name")
                        if column_name and self.corrected_df is not None and effective_final_target:
                            ci_result = self.engine._worst_group_ratio_ci_direct(
                                self.corrected_df, column_name, effective_final_target
                            )
                            if ci_result:
                                dual_significant_final = ci_result.get("dual_criteria_significant")

                        self.worst_group_regressions.append({
                            "feature": feature,
                            "worst_group": group,
                            "deviation_initial": before_dev,
                            "deviation_final": after_dev,
                            "reason": reason,
                            "dual_criteria_significant_final": dual_significant_final,
                        })
                        _dual_note = (
                            "the resulting gap is ALSO statistically and practically significant -- two independent checks agree this needs attention"
                            if dual_significant_final is True
                            else "but the resulting gap itself is not statistically+practically significant (may be a relative worsening of an already-small gap)"
                            if dual_significant_final is False
                            else "dual-criteria significance could not be computed for this feature"
                        )
                        logger.warning(f"   ⚠️  WORST-GROUP SAFEGUARD (warn-only, not gated): {feature}'s "
                              f"worst-off group ('{group}') -- {reason}. This can happen even "
                              f"when the feature's own average/composite score improved. "
                              f"Needs manual review -- {_dual_note}.")

            # ============================================================================
            # PHASE 8: RESULTS COMPILATION WITH v3.0 ENHANCEMENTS
            # ============================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 8: COMPILING RESULTS (v3.0 ENHANCED)")
            logger.info(f"{'='*80}")

            # FIX: Ensure svm_validation exists even if no mitigation
            if not diagnostic_results.get("requires_mitigation", False):
                # No mitigation was performed at all.
                #
                # v3.10.4: this used to say "No significant bias detected"
                # unconditionally -- but requires_mitigation is False for
                # TWO different reasons (significant_bias_count > 0 AND
                # initial_bias_score > 0.05, both required), and only one
                # of them actually means "nothing significant was found."
                # Found on real data twice (HMDA, German Credit): both
                # runs had 2 statistically significant features sitting
                # elsewhere in the very same report, while this line
                # claimed none were detected -- a direct, visible
                # contradiction between the executive summary and the
                # statistical tests table right below it. The real reason
                # in both cases was the SECOND condition: the combined/
                # composite score across all features stayed under 0.05
                # even though individual features cleared their own
                # significance bar. Branching on which condition actually
                # failed gives an accurate reason either way.
                sig_count = diagnostic_results.get("significant_bias_count", 0)
                composite_score = diagnostic_results.get("initial_bias_score", 0)
                if sig_count == 0:
                    no_mitigation_reason = "No significant bias detected in any feature - no mitigation performed"
                else:
                    no_mitigation_reason = (
                        f"{sig_count} feature{'s' if sig_count != 1 else ''} showed statistically "
                        f"significant bias, but the combined score across all features "
                        f"({composite_score:.4f}) stayed below the 0.05 threshold that triggers "
                        f"automatic mitigation - no mitigation performed. Review the individually "
                        f"significant feature(s) below even though no correction was attempted."
                    )
                svm_validation = {
                    'svm_applied': False,
                    'reason': no_mitigation_reason,
                    'post_svm_bias_score': diagnostic_results.get('initial_bias_score', 0)
                }
                # v3.6.4 FIX: diagnostic_results["final_bias_score"] is
                # normally set inside PHASE 7 (see the mitigation-happened
                # path a few hundred lines up, "diagnostic_results
                # ['final_bias_score'] = final_bias"). That path never runs
                # when requires_mitigation is False, so without this line
                # the key stays unset -- and _save_results' audit_trail
                # ["bias_scores"]["final"] = diagnostics.get
                # ("final_bias_score", 0) then silently falls back to the
                # literal default 0, not to initial_bias_score. Found on
                # real NIJ data (nij-challenge2021_full_dataset.csv,
                # v3.6.3 re-run): all 4 protected features showed
                # significant_bias=True by p-value, but the composite
                # initial_bias_score (0.0373) was under the 0.05
                # requires_mitigation threshold, so mitigation was
                # correctly skipped -- yet audit_trail.json reported
                # bias_scores.final: 0 right next to svm_enforcement.
                # post_svm_bias_score: 0.0373 for the exact same
                # unchanged number, implying bias had been eliminated
                # when in fact none was ever attempted. No mitigation ran,
                # so the true final score IS the initial score --
                # matching what svm_validation['post_svm_bias_score']
                # above, and every other final-score fallback in this file
                # (lines ~2718, ~3157, ~5626), already default to.
                diagnostic_results['final_bias_score'] = diagnostic_results.get('initial_bias_score', 0)
                # Create empty validation dict since no mitigation occurred
                validation = {
                    'fairness_improvement': {},
                    'absolute_disparity_reduction': {},
                    'initial_disparities': {},
                    'final_disparities': {},
                    'data_integrity': {
                        'records_before': len(self.original_df),
                        'records_after': len(self.original_df),
                        'retention_rate': 100.0
                    }
                }
                # Set corrected_df to original if no mitigation
                self.corrected_df = self.original_df.copy()

            # Compile v3.0 enhanced results
            self.results = self._compile_v30_results(
                diagnostic_results, validation, svm_validation,
                final_target, feature_map, auto_approve_threshold,
                stage_tracker if 'stage_tracker' in locals() else None
            )

            logger.info(f"   Results compiled successfully")

            # FIXED: Check if svm_validation exists and if SVM was applied
            if svm_validation.get('svm_applied', False):
                logger.info(f"   • SVM fairness enforcement included")
            else:
                logger.info(f"   • BiasClean-only mitigation")
                if svm_validation.get('reason'):
                    logger.info(f"   • Reason: {svm_validation['reason']}")

            # ================================================================
            # PHASE 9: SAVE RESULTS (v3.1 consolidated data export)
            # ================================================================
            # Stash the stage tracker / sampling logger summaries so
            # _save_results can fold them into the one audit_trail.json
            # (see UniversalBiasClean._save_results for the rest of the
            # consolidation).
            self._stage_tracker_summary = stage_tracker.get_summary() if 'stage_tracker' in locals() else {}
            self._sampling_summary = sampling_logger.get_summary() if 'sampling_logger' in locals() else {}
            self._save_results()

            # ================================================================
            # PHASE 10: GENERATE REPORT (charts embedded, no separate PNGs)
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PHASE 10: GENERATING REPORT")
            logger.info(f"{'='*80}")

            # Generate visualizations as in-memory base64 PNGs
            charts = {}
            try:
                logger.info("\n   Generating charts...")
                charts["Outcome Rates by Group, Before vs. After"] = self.viz.plot_disparity_comparison(
                    self.original_df, self.corrected_df, feature_map, final_target
                )
                if validation.get("fairness_improvement"):
                    charts["Fairness Improvement by Feature"] = self.viz.plot_feature_improvements(validation)
                charts["Record Count Before vs. After"] = self.viz.plot_data_integrity(validation)
                logger.info(f"   {sum(1 for v in charts.values() if v)} chart(s) generated")
            except Exception as e:
                logger.info(f"   Chart generation failed: {str(e)}")

            # Generate reports: one console summary + one report.pdf
            # (plain-language summary, then technical detail on its own
            # page -- offline and printable, since this is a
            # scientific/governance document, not a web page)
            report_path = "biasclean_results/report.pdf"
            try:
                logger.info("\n   Generating report...")
                self.reporter.print_console_report(self.results)
                report_path = self.reporter.generate_report(
                    self.results,
                    output_file=report_path,
                    charts=charts
                )
            except Exception as e:
                logger.info(f"   Report generation failed: {str(e)}")

            # ================================================================
            # FINAL SUCCESS MESSAGE
            # ================================================================
            logger.info(f"\n{'='*80}")
            logger.info("PIPELINE COMPLETED SUCCESSFULLY!")
            logger.info(f"{'='*80}")
            logger.info(f"   Results saved to: biasclean_results/")
            if hasattr(self, 'audit_results'):
                logger.info(f"   Audit: {self.audit_results['recommendation']['traffic_light']}")
            logger.info(f"   • {os.path.basename(report_path):<24} - open this first (Summary + Technical Detail)")
            logger.info(f"   • corrected_dataset.csv  - rebalanced data")
            logger.info(f"   • audit_trail.json       - full machine-readable numbers")
            logger.info(f"{'='*80}\n")

            return self.results

        except Exception as e:
            logger.info(f"\n{'='*80}")
            logger.error(f"PIPELINE FAILED")
            logger.info(f"{'='*80}")
            logger.error(f"Error: {str(e)}")
            logger.info(f"{'='*80}\n")
            raise

    def _run_statistical_diagnosis_v27(self, feature_map: Dict, target_column: str) -> Dict:
        """Run comprehensive statistical tests for bias detection with v2.7 enhancements"""
        diagnostic_results = {
            "feature_tests": {},
            "significant_bias_count": 0,
            "requires_mitigation": False,
            "target_column_used": target_column,
            "statistical_confidence": {},  # v2.7
            "group_rates_initial": {}      # v2.7
        }

        # FIXED: Calculate min p-value threshold based on domain max weight
        max_weight = max(self.config["weights"].values()) if self.config["weights"] else 0.25
        min_p_threshold = 0.05  # Minimum threshold for highest weight features
        max_p_threshold = 0.15  # Maximum threshold for lowest weight features


        # v2.7: Record initial group rates (simplified)
        group_rates_initial = {}
        for feature, column in feature_map.items():
            if column in self.original_df.columns:
                rates = {}
                for group in self.original_df[column].dropna().unique():
                    group_data = self.original_df[self.original_df[column] == group]
                    if len(group_data) >= 10:
                        rates[str(group)] = group_data[target_column].mean()
                if rates:
                    group_rates_initial[feature] = rates

        diagnostic_results['group_rates_initial'] = group_rates_initial

        for feature, column in feature_map.items():
            try:
                # Create contingency table
                contingency = pd.crosstab(
                    self.original_df[column],
                    self.original_df[target_column]
                )

                # Choose appropriate test
                if contingency.shape == (2, 2):
                    _, p_value = fisher_exact(contingency)
                    test_used = "fisher-exact"
                else:
                    chi2, p_value, _, _ = chi2_contingency(contingency)
                    test_used = "chi-square"

                # Weight-adjusted significance threshold. Higher weight
                # = HIGHER (more lenient) p-value threshold, making it
                # easier for the most important protected attributes to
                # register as statistically significant. (The previous
                # comment here said "lower threshold" and called that
                # "more sensitive" -- those two claims contradict each
                # other, since a lower p-value threshold is stricter,
                # not more sensitive. The formula itself was correct;
                # only the comment was wrong.)
                weight = self.config["weights"].get(feature, 0.05)

                # Calculate dynamic threshold based on weight
                weight_factor = weight / max_weight  # Normalize to [0, 1]
                p_threshold = min_p_threshold + (weight_factor * (max_p_threshold - min_p_threshold))
                p_threshold = max(min_p_threshold, min(max_p_threshold, p_threshold))

                # Determine significance using weight-adjusted threshold
                significant = p_value < p_threshold

                diagnostic_results["feature_tests"][feature] = {
                    "p_value": p_value,
                    "significant_bias": significant,
                    "test_used": test_used,
                    "column_name": column,
                    "weight_used": weight,
                    "threshold_used": p_threshold  # Store threshold for display
                }

                if significant:
                    diagnostic_results["significant_bias_count"] += 1

            except Exception as e:
                diagnostic_results["feature_tests"][feature] = {
                    "error": str(e),
                    "significant_bias": False,
                    "test_used": "failed"
                }

        # Calculate overall bias score
        initial_bias_score = self.engine.score(self.original_df, target_column)
        diagnostic_results["initial_bias_score"] = initial_bias_score

        # Determine if mitigation is needed
        diagnostic_results["requires_mitigation"] = (
            diagnostic_results["significant_bias_count"] > 0 and
            diagnostic_results["initial_bias_score"] > 0.05
        )

        return diagnostic_results

    def _compile_v30_results(self, diagnostic_results: Dict, validation: Dict,
                           svm_validation: Dict, final_target: str,
                           feature_map: Dict, auto_approve_threshold: float,
                           stage_tracker: Any) -> Dict:
        """Compile v3.0 enhanced results package"""

        # Prepare basic results structure
        results = {
            "original_df": self.original_df,
            "corrected_df": self.corrected_df,
            "mappings": self.approved_mappings,
            "diagnostics": diagnostic_results,
            "validation": validation,
            "svm_validation": svm_validation,
            # v3.2.0: same source as audit_trail.json's rebalance_log /
            # reversal_checks -- carried in `results` too so generate_report
            # can surface a reversal in the plain-language summary, the same
            # way the 3.1.3 fix surfaced an SVM regression.
            "rebalance_log": getattr(self, "rebalance_log", []),
            "reversal_checks": getattr(self, "reversal_checks", {}),
            "svm_reversal_checks": getattr(self, "svm_reversal_checks", {}),
            # BUG FIX (v3.7.4): other outcome-pattern columns that tied at
            # the same top confidence as the auto-selected target_column,
            # if any -- see PHASE 3's tie-break comment for the full
            # root-cause writeup. Empty list means either the target was
            # specified explicitly, or auto-detection had no ambiguity.
            "tied_outcome_candidates": getattr(self, "_tied_outcome_candidates", []),
            # PHASE 3.5, Workstream A: warn-only worst-group safeguard --
            # see PHASE 7's comment for the full design writeup. Empty
            # list means no group's own deviation from parity got worse
            # by more than the tolerance, or mitigation never ran.
            "worst_group_regressions": getattr(self, "worst_group_regressions", []),
            # v3.3.0: the Smart SVM validation gate's accept/reject decision --
            # see the gate logic in PHASE 7 for what it checks and why.
            "svm_gate": getattr(self, "svm_gate", {}),
            # v3.4.0: the rebalancing-stage Fairness Regulator's backstop
            # check -- "accepted": False means the proactive clip didn't
            # fully prevent a reversal and it needs manual review; see
            # rebalance_log's per-feature "regulator_capped" entries for
            # where the clip DID engage successfully.
            "rebalance_gate": getattr(self, "rebalance_gate", {}),
            "target_column": final_target,
            "target_binarization": (
                {str(k): v for k, v in self.target_binarization_map.items()}
                if getattr(self, "target_binarization_map", None) else None
            ),
            "feature_map": feature_map,
            # v3.10.8 FIX -- see the matching comment at the no-mitigation
            # results dict above for the full root-cause writeup. Same fix,
            # same reasoning, applied to this (the main/mitigated-path)
            # results dict, which had the identical gap.
            "features": {feature: {"column": col} for feature, col in feature_map.items()},
            "metadata": {
                "domain": self.domain,
                "jurisdiction": self.jurisdiction,
                "timestamp": datetime.now().isoformat(),
                "auto_approve_threshold": auto_approve_threshold,
                "svm_enabled": svm_validation.get('svm_applied', False) if 'svm_validation' in locals() else False,
                "version": "3.0",
                "mode": self.mode,
                "v30_features": [
                    "pre_mitigation_audit",
                    "traffic_light_recommendation",
                    "governance_reporting"
                ]
            }
        }

        # Add audit results if available
        if hasattr(self, 'audit_results'):
            results['v3_audit'] = self.audit_results

            # Populate deployment_decision from the already-computed
            # traffic-light recommendation, rather than leaving it
            # unset -- ReportGenerator reads this to display a
            # deployment score/confidence, and previously always fell
            # back to score=0/"NOT RECOMMENDED" regardless of the real
            # audit outcome because this key was never actually set.
            # Note: Legacy mode has no traffic-light governance step by
            # design, so audit_results (and this deployment_info) is
            # only ever present for audit_first/audit_only runs.
            rec = self.audit_results.get('recommendation', {})
            traffic_light = rec.get('traffic_light', '')
            if 'GREEN' in traffic_light.upper():
                score, confidence, risk_level = 90, 'high', 'low'
            elif 'YELLOW' in traffic_light.upper():
                score, confidence, risk_level = 60, 'medium', 'medium'
            else:
                score, confidence, risk_level = 20, 'low', 'high'

            results['deployment_info'] = {
                'deployment_decision': {
                    'recommended': rec.get('proceed', False),
                    'score': score,
                    'confidence': confidence,
                    'risk_factors': {'risk_level': risk_level},
                    'reasons': [r for r in rec.get('rationale', []) if r],
                    'warnings': [] if rec.get('proceed', False) else [r for r in rec.get('rationale', []) if r]
                }
            }
            # Note: the plain-language governance recommendation is now
            # rendered directly inside report.pdf's Summary section
            # (see ReportGenerator.generate_report) instead of a
            # separate GOVERNANCE_REPORT.txt file -- part of the v3.1
            # consolidation down to one human-facing report.

        # Compute group rates after mitigation and a feature-interaction
        # summary here, once, so both the report and audit_trail.json
        # can reuse the exact same numbers instead of recomputing them
        # (or, previously, never persisting them anywhere at all).
        feature_map = results.get("feature_map", {})
        target_column = results.get("target_column")
        # BUG FIX (v3.7.2): group_rates_final used to always read from
        # target_column (== final_target, the pre-SVM rebalancing-stage
        # target) even when SVM ran and produced a different, real final
        # result in the separate 'svm_fair_target' column. Since this feeds
        # BOTH audit_trail.json's per-feature group_rates_final AND
        # report.pdf's plain-language findings (_plain_feature_findings
        # reads results["group_rates_final"] directly), every per-feature
        # narrative silently reported the pre-SVM snapshot -- see the
        # v3.7.2 changelog entry for the real Communities & Crime run that
        # surfaced this (report said a group's gap "stayed essentially
        # unchanged at 94.1 percentage points" while audit_trail.json's own
        # svm_reversal_checks already showed it had closed to ~40%).
        effective_target_column = (
            'svm_fair_target'
            if (self.corrected_df is not None and 'svm_fair_target' in self.corrected_df.columns)
            else target_column
        )
        if self.corrected_df is not None and effective_target_column:
            results["group_rates_final"] = self._compute_group_rates(self.corrected_df, feature_map, effective_target_column)
        else:
            results["group_rates_final"] = {}
        results["feature_interactions"] = self._compute_feature_interactions(diagnostic_results, validation)

        return results

    def _compute_group_rates(self, df: pd.DataFrame, feature_map: Dict, target_column: str) -> Dict:
        """Outcome rate per group for each mapped protected feature."""
        group_rates = {}
        for feature, column in feature_map.items():
            if column not in df.columns or target_column not in df.columns:
                continue
            rates = {}
            for group in df[column].dropna().unique():
                group_data = df[df[column] == group]
                if len(group_data) >= 10:
                    rates[str(group)] = group_data[target_column].mean()
            if rates:
                group_rates[feature] = rates
        return group_rates

    def _compute_feature_interactions(self, diagnostic_results: Dict, validation: Dict) -> Dict:
        """Which features improved vs. worsened during mitigation, and
        whether the overall composite score improved despite some
        individual feature(s) worsening (a compensatory trade-off, as
        opposed to every feature improving together)."""
        fairness_improvement = validation.get("fairness_improvement", {})
        worsened = [f for f, v in fairness_improvement.items() if v is not None and v < 0]
        improved = [f for f, v in fairness_improvement.items() if v is not None and v > 0]
        initial_score = diagnostic_results.get("initial_bias_score", 0)
        final_score = diagnostic_results.get("final_bias_score", initial_score)
        compensatory = bool(worsened) and final_score < initial_score
        return {
            "improved_features": improved,
            "worsened_features": worsened,
            "compensatory_pattern_detected": compensatory,
            "note": ("One or more features got worse individually while the overall "
                     "composite score improved -- the remaining features' gains "
                     "outweighed this feature's regression in the weighted total."
                     if compensatory else
                     "No compensatory trade-off detected: no feature worsened, or the "
                     "overall composite score did not improve.")
        }

    def _save_results(self):
        """Save the pipeline's data-export layer: the corrected dataset
        plus one merged audit_trail.json.

        v3.1 consolidation: this used to write feature_mappings.json,
        pipeline_summary.json, GOVERNANCE_REPORT.txt, and a
        v27_exports/ directory containing 6 more separate JSON files --
        11 files total, several of them overlapping, which was easy for
        a user to partially lose track of (see the earlier missed-files
        issue). Everything from those files is preserved here, just
        merged into one JSON. report.pdf (written separately, in Phase
        10, since it also needs the chart images) is the human-facing
        counterpart to this machine-readable file."""
        os.makedirs("biasclean_results", exist_ok=True)

        if self.corrected_df is not None:
            # BUG FIX (v3.7.3): this comment used to say
            # 'biasclean_target'/'svm_fair_target' "are exact duplicates
            # of the real target column" -- true only when SVM never ran
            # or was gate-rejected. When SVM ran AND was accepted as
            # genuinely different from rebalancing, self.corrected_df's
            # named target column (e.g. 'HighCrime') is DELIBERATELY never
            # overwritten with SVM's output (see PHASE 7's CRITICAL FIX
            # comment) -- only 'svm_fair_target' holds the true final
            # predictions. Dropping 'svm_fair_target' here without first
            # copying it into the named target column meant
            # corrected_dataset.csv -- the file external tools/auditors
            # actually read -- silently exported the pre-SVM rebalancing
            # snapshot under the target column's real name, even after the
            # v3.7.2 fix corrected the report/audit_trail.json. Found when
            # handing Communities & Crime's v3.7.2 corrected_dataset.csv to
            # AIF360/Aequitas for Phase 3 judging: group 23/24's HighCrime
            # values in the exported CSV matched the RAW data exactly,
            # while audit_trail.json already showed 0.353/0.75 post-SVM --
            # the export was a third, still-unfixed manifestation of bug
            # #6's root cause. Fixed: write 'svm_fair_target' into the
            # named target column before export whenever it exists and
            # differs, so corrected_dataset.csv always reflects the
            # pipeline's true final result under its own real column name
            # -- no downstream consumer needs to know to look for a
            # separate 'svm_y_pred'/'svm_fair_target' column instead.
            export_df = self.corrected_df.copy()
            target_col = self.results.get("target_column")
            if (
                target_col
                and "svm_fair_target" in export_df.columns
                and target_col in export_df.columns
                and not export_df[target_col].equals(export_df["svm_fair_target"])
            ):
                export_df[target_col] = export_df["svm_fair_target"]
            # 'biasclean_target'/'svm_fair_target' are internal bookkeeping
            # columns the pipeline adds so later stages (stage_tracker,
            # sampling_logger) have a stable column name to reference
            # regardless of which target column this dataset actually
            # uses. Now that the true final values have been copied into
            # the named target column above, these are redundant in the
            # export and would throw off the column count reported in
            # audit_trail.json -- drop them from the export only;
            # self.corrected_df itself is untouched for anything upstream.
            export_df = export_df.drop(
                columns=[c for c in ("biasclean_target", "svm_fair_target") if c in export_df.columns]
            )
            export_df.to_csv("biasclean_results/corrected_dataset.csv", index=False)

        diagnostics = self.results.get("diagnostics", {})
        validation = self.results.get("validation", {})
        feature_map = self.results.get("feature_map", {})
        feature_tests = diagnostics.get("feature_tests", {})
        initial_disparities = validation.get("initial_disparities", {})
        final_disparities = validation.get("final_disparities", {})
        fairness_improvement = validation.get("fairness_improvement", {})
        # PHASE 3.5, Workstream C
        initial_worst_group = validation.get("initial_worst_group", {})
        final_worst_group = validation.get("final_worst_group", {})
        initial_worst_group_deviation = validation.get("initial_worst_group_deviation", {})
        final_worst_group_deviation = validation.get("final_worst_group_deviation", {})
        worst_group_improvement_pct = validation.get("worst_group_improvement_pct", {})

        # PHASE 3.5, Workstream B: same effective-target logic as the
        # v3.7.2 fix (bug #6) -- read from svm_fair_target when present,
        # else the named target column, so this CI is computed against
        # the pipeline's true final result, not a frozen pre-SVM snapshot.
        _target_col = self.results.get("target_column")
        _effective_target_col = (
            'svm_fair_target'
            if (self.corrected_df is not None and 'svm_fair_target' in self.corrected_df.columns)
            else _target_col
        )

        features_merged = {}
        for feature, column in feature_map.items():
            test = feature_tests.get(feature, {})

            ci_initial = None
            ci_final = None
            if self.original_df is not None and _target_col:
                ci_initial = self.engine._worst_group_ratio_ci_direct(
                    self.original_df, column, _target_col
                )
            if self.corrected_df is not None and _effective_target_col:
                ci_final = self.engine._worst_group_ratio_ci_direct(
                    self.corrected_df, column, _effective_target_col
                )

            features_merged[feature] = {
                "column": column,
                "weight": self.config["weights"].get(feature, 0.05),
                "p_value": test.get("p_value"),
                "significant_bias": test.get("significant_bias"),
                "threshold_used": test.get("threshold_used"),
                "disparity_initial": initial_disparities.get(feature),
                "disparity_final": final_disparities.get(feature),
                "improvement_pct": fairness_improvement.get(feature),
                "group_rates_initial": diagnostics.get("group_rates_initial", {}).get(feature),
                "group_rates_final": self.results.get("group_rates_final", {}).get(feature),
                # PHASE 3.5, Workstream C: disparity_initial/disparity_final
                # above are BiasClean's long-standing coefficient-of-
                # variation figure -- an average across all groups. That
                # average can improve while a single group gets worse (see
                # this method's docstring on _calculate_worst_group_deviation_direct
                # for the real North Carolina Ethnicity case that motivated
                # this addition). These four fields report which single
                # group deviates furthest from parity, before and after,
                # so that case is visible in BiasClean's own output rather
                # than only discoverable by an external judge computing a
                # second metric BiasClean didn't report.
                "worst_group_initial": initial_worst_group.get(feature),
                "worst_group_final": final_worst_group.get(feature),
                "worst_group_deviation_initial": initial_worst_group_deviation.get(feature),
                "worst_group_deviation_final": final_worst_group_deviation.get(feature),
                "worst_group_improvement_pct": worst_group_improvement_pct.get(feature),
                # PHASE 3.5, Workstream B: a second, sample-size-aware
                # significance lens (log relative-risk CI, Katz method,
                # per Besse et al. 2018) alongside significant_bias above
                # (which uses BiasClean's existing chi-square/fisher-exact
                # test). ci_significance_initial/final report whether this
                # feature's worst-group-vs-reference-group ratio is
                # statistically distinguishable from parity AT THIS
                # FEATURE'S OWN ACTUAL SAMPLE SIZE -- unlike the fixed 0.05
                # composite threshold, which doesn't adapt to sample size
                # at all. Reporting-only for now: does not change
                # requires_mitigation or significant_bias.
                "ci_significance_initial": ci_initial,
                "ci_significance_final": ci_final,
            }

        audit_trail = {
            "generated_at": datetime.now().isoformat(),
            "pipeline_version": __version__,
            "domain": self.domain,
            "mode": self.mode,
            "target_column": self.results.get("target_column"),
            "target_binarization": self.results.get("target_binarization"),
            # BUG FIX (v3.7.4): other outcome-pattern columns tied at the
            # same top confidence as target_column, if auto-detection had
            # to break a tie -- empty list if the target was specified
            # explicitly or there was no ambiguity. See PHASE 3 for the
            # root-cause writeup.
            "tied_outcome_candidates": self.results.get("tied_outcome_candidates", []),
            # PHASE 3.5, Workstream A: see PHASE 7's comment for the full
            # design writeup. Warn-only for now -- not yet a gate.
            "worst_group_regressions": self.results.get("worst_group_regressions", []),
            "dataset": {
                "original_records": len(self.original_df),
                "corrected_records": len(self.corrected_df) if self.corrected_df is not None else len(self.original_df),
                # Matches the actual column count of corrected_dataset.csv
                # (i.e. export_df, after dropping the internal
                # biasclean_target/svm_fair_target bookkeeping columns),
                # not the raw in-memory working frame.
                "columns": len(export_df.columns) if self.corrected_df is not None else len(self.original_df.columns),
                "retention_rate": validation.get("data_integrity", {}).get("retention_rate"),
            },
            "bias_scores": {
                "initial": diagnostics.get("initial_bias_score", 0),
                "final": diagnostics.get("final_bias_score", 0),
            },
            "audit": self.audit_results["recommendation"] if hasattr(self, 'audit_results') else None,
            "deployment_decision": self.results.get("deployment_info", {}).get("deployment_decision"),
            "features": features_merged,
            "feature_interactions": self.results.get("feature_interactions", {}),
            "stage_bias_scores": self._stage_tracker_summary if hasattr(self, "_stage_tracker_summary") else {},
            "sampling_attribution": self._sampling_summary if hasattr(self, "_sampling_summary") else {},
            "column_mappings": self.approved_mappings,
            # Surfaces the SVM regression check in the machine-readable
            # output itself, not just a console line that scrolls by --
            # a no-code user reading only audit_trail.json/report.pdf
            # (not the terminal log) needs to be able to see that SVM
            # enforcement made the measured bias score worse, since
            # "bias_scores.final" now reflects the post-SVM number too.
            "svm_enforcement": {
                "applied": self.results.get("svm_validation", {}).get("svm_applied", False),
                "pre_svm_bias_score": self.results.get("svm_validation", {}).get("pre_svm_bias_score"),
                "post_svm_bias_score": self.results.get("svm_validation", {}).get("post_svm_bias_score"),
                "worsened_fairness": self.results.get("svm_validation", {}).get("svm_worsened_fairness", False),
            },
            # v3.3.0: Smart SVM validation gate. "accepted": True means the
            # SVM/ExponentiatedGradient result was used as the final stage;
            # False means it was rejected and the pipeline fell back to the
            # rebalanced-stage predictions instead -- "reason" explains why,
            # "new_reversals" lists any protected feature where SVM flipped
            # who is disadvantaged in a way rebalancing alone did not.
            "svm_gate": getattr(self, "svm_gate", {}),
            # v3.4.0: rebalancing-stage Fairness Regulator backstop.
            # "accepted": True means no reversal survived the proactive
            # clip; False means one did and needs manual review (see
            # "reversed_features"). Check rebalance_log's per-feature
            # "regulator_capped" entries to see where the clip itself
            # engaged -- most of the time that's where the real work
            # happens, and this gate stays "accepted".
            "rebalance_gate": getattr(self, "rebalance_gate", {}),
            # v3.2.0: Preferential Sampling method + group-size-floor
            # exclusions, per feature, from the rebalancing stage.
            "rebalance_log": getattr(self, "rebalance_log", []),
            # v3.2.0: did the SAME group stay disadvantaged before vs. after
            # mitigation, per protected feature? (None = not enough groups
            # with enough samples to tell.) "after_rebalancing" reflects the
            # rebalancing-only stage; "after_svm" is only populated when SVM
            # enforcement actually ran, compared against the ORIGINAL
            # pre-mitigation data.
            "reversal_checks": {
                feature: {
                    "after_rebalancing": getattr(self, "reversal_checks", {}).get(feature),
                    "after_svm": getattr(self, "svm_reversal_checks", {}).get(feature),
                }
                for feature in set(list(getattr(self, "reversal_checks", {}).keys())
                                    + list(getattr(self, "svm_reversal_checks", {}).keys()))
            },
        }

        with open("biasclean_results/audit_trail.json", "w") as f:
            json.dump(audit_trail, f, indent=2, default=json_serializer)

        # Only claim corrected_dataset.csv was saved if it actually was --
        # this used to print unconditionally, so a blocked (RED) audit
        # with no mitigation performed (self.corrected_df is None) would
        # falsely claim a corrected dataset was saved, directly
        # contradicting the correct "(no corrected_dataset.csv...)" note
        # printed moments later in the same run.
        if self.corrected_df is not None:
            logger.info(f"   Results saved to biasclean_results/ (corrected_dataset.csv, audit_trail.json)")
        else:
            logger.info(f"   Results saved to biasclean_results/ (audit_trail.json only -- no mitigation was performed)")

# ============================================================================
# GOVERNANCE REPORT GENERATOR (v3.0 NEW)
# ============================================================================

def generate_governance_report(results: dict) -> str:
    """
    Non-technical traffic-light report for decision-makers
    """
    report = []
    report.append("="*80)
    report.append("BIASCLEAN v3.0: GOVERNANCE RECOMMENDATION")
    report.append("="*80)
    report.append("")

    # Extract traffic light
    if "v3_audit" in results:
        audit = results["v3_audit"]
        rec = audit["recommendation"]

        report.append(f"DECISION: {rec['traffic_light']}")
        report.append(f"ACTION: {rec['action']}")
        report.append("")

        if "🟢" in rec['traffic_light']:
            report.append("✅ APPROVED FOR DEPLOYMENT")
            report.append("The bias mitigation is safe and effective.")
            report.append("No significant harm to subgroups detected.")

        elif "🟡" in rec['traffic_light']:
            report.append("⚠️  EXPERT REVIEW REQUIRED")
            report.append("Moderate concerns identified.")
            report.append("Consult domain experts before deployment.")

        elif "🔴" in rec['traffic_light']:
            report.append("🛑 DO NOT DEPLOY")
            report.append("Serious issues detected.")
            report.append("Address these concerns before proceeding:")
            for reason in rec['rationale']:
                if reason:
                    report.append(f"  • {reason}")

    else:
        report.append("⚪ LEGACY v2.7 MODE")
        report.append("Audit-first diagnostics not performed.")
        report.append("Consider re-running with mode='audit_first'.")

    report.append("")
    report.append("="*80)
    report.append("For detailed analysis: biasclean_results/pipeline_summary.json")

    return "\n".join(report)

"""# Part 3"""

# ============================================================================
# 8. SAMPLE DATASET GENERATOR (For Testing - 7 DOMAINS)
# ============================================================================

def create_sample_justice_dataset(n_samples: int = 2000, seed: int = 42) -> pd.DataFrame:
    """Create realistic justice dataset with inherent bias for testing"""
    np.random.seed(seed)

    print(f"\n{'='*80}")
    print(f"GENERATING SAMPLE JUSTICE DATASET")
    print(f"{'='*80}")
    print(f"   Records: {n_samples:,}")
    print(f"   Seed: {seed}")

    # Generate base demographics
    data = {
        "person_id": range(n_samples),
        "defendant_name": [f"Defendant_{i}" for i in range(n_samples)],
        "race": np.random.choice(
            ["White", "Black", "Hispanic", "Asian", "Other"],
            n_samples,
            p=[0.50, 0.30, 0.15, 0.04, 0.01]
        ),
        "age": np.random.randint(18, 75, n_samples),
        "sex": np.random.choice(["Male", "Female"], n_samples, p=[0.70, 0.30]),
        "priors_count": np.random.randint(0, 25, n_samples),
        "c_charge_desc": np.random.choice(
            ["Aggravated Assault", "Burglary", "Drug Possession", "Theft", "Battery", "Fraud"],
            n_samples
        ),
        "screening_date": pd.date_range("2020-01-01", periods=n_samples, freq="H")
    }

    df = pd.DataFrame(data)

    # Create biased recidivism outcome
    base_rate = 0.35
    race_biases = {
        "White": base_rate * 1.50,
        "Black": base_rate * 0.30,
        "Hispanic": base_rate * 1.15,
        "Asian": base_rate * 0.70,
        "Other": base_rate * 1.00
    }

    def age_factor(age):
        if age < 25: return 1.30
        elif age < 40: return 1.00
        elif age < 60: return 0.85
        else: return 0.70

    def priors_factor(priors):
        if priors == 0: return 0.60
        elif priors < 3: return 0.90
        elif priors < 6: return 1.10
        else: return 1.40

    recidivism = []
    for idx, row in df.iterrows():
        prob = race_biases[row["race"]]
        prob *= age_factor(row["age"])
        prob *= priors_factor(row["priors_count"])
        prob *= np.random.uniform(0.90, 1.10)
        prob = np.clip(prob, 0.05, 0.95)
        recidivism.append(np.random.binomial(1, prob))

    df["two_year_recid"] = recidivism

    print(f"\n   Recidivism Rates by Race (Showing Bias):")
    recid_by_race = df.groupby("race")["two_year_recid"].mean().sort_values(ascending=False)
    for race, rate in recid_by_race.items():
        deviation = ((rate - base_rate) / base_rate) * 100
        print(f"     • {race:15} {rate:.1%}  (deviation: {deviation:+.0f}%)")

    print(f"\n   Overall Recidivism Rate: {df['two_year_recid'].mean():.1%}")
    print(f"   Max Disparity: {recid_by_race.max() - recid_by_race.min():.1%}")
    print(f"{'='*80}\n")

    return df

def create_sample_health_dataset(n_samples: int = 2000, seed: int = 42) -> pd.DataFrame:
    """Create realistic healthcare dataset with inherent bias for testing"""
    np.random.seed(seed)

    print(f"\n{'='*80}")
    print(f"GENERATING SAMPLE HEALTHCARE DATASET")
    print(f"{'='*80}")
    print(f"   Records: {n_samples:,}")
    print(f"   Seed: {seed}")

    data = {
        "patient_id": range(n_samples),
        "patient_name": [f"Patient_{i}" for i in range(n_samples)],
        "ethnicity": np.random.choice(
            ["White", "Black", "Asian", "Other"],
            n_samples,
            p=[0.75, 0.15, 0.07, 0.03]
        ),
        "age": np.random.randint(18, 90, n_samples),
        "gender": np.random.choice(["Male", "Female"], n_samples, p=[0.48, 0.52]),
        "postcode": np.random.choice(["Urban", "Rural", "Suburban"], n_samples),
        "bmi": np.random.normal(26, 5, n_samples).clip(18, 45),
        "smoking_status": np.random.choice(["Never", "Former", "Current"], n_samples, p=[0.50, 0.30, 0.20]),
        "family_history": np.random.binomial(1, 0.25, n_samples),
        "socioeconomic_score": np.random.randint(1, 10, n_samples),
        "visit_date": pd.date_range("2022-01-01", periods=n_samples, freq="H")
    }

    df = pd.DataFrame(data)

    base_rate = 0.20
    ethnic_biases = {
        "White": base_rate * 1.50,
        "Black": base_rate * 0.30,
        "Asian": base_rate * 0.95,
        "Other": base_rate * 1.10
    }

    def bmi_factor(bmi):
        if bmi < 18.5: return 0.90
        elif bmi < 25: return 0.85
        elif bmi < 30: return 1.10
        else: return 1.40

    def smoking_factor(status):
        if status == "Never": return 0.80
        elif status == "Former": return 1.10
        else: return 1.50

    diagnoses = []
    for idx, row in df.iterrows():
        prob = ethnic_biases[row["ethnicity"]]
        prob *= bmi_factor(row["bmi"])
        prob *= smoking_factor(row["smoking_status"])
        prob *= (1 + (row["family_history"] * 0.3))
        prob *= np.random.uniform(0.90, 1.10)
        prob = np.clip(prob, 0.05, 0.80)
        diagnoses.append(np.random.binomial(1, prob))

    df["diagnosis_positive"] = diagnoses

    print(f"\n   Diagnosis Rates by Ethnicity (Showing Bias):")
    diagnosis_by_ethnicity = df.groupby("ethnicity")["diagnosis_positive"].mean().sort_values(ascending=False)
    for ethnicity, rate in diagnosis_by_ethnicity.items():
        deviation = ((rate - base_rate) / base_rate) * 100
        print(f"     • {ethnicity:15} {rate:.1%}  (deviation: {deviation:+.0f}%)")

    print(f"\n   Overall Diagnosis Rate: {df['diagnosis_positive'].mean():.1%}")
    print(f"   Max Disparity: {diagnosis_by_ethnicity.max() - diagnosis_by_ethnicity.min():.1%}")
    print(f"{'='*80}\n")

    return df

def create_sample_finance_dataset(n_samples: int = 2000, seed: int = 42) -> pd.DataFrame:
    """Create realistic finance dataset with inherent bias for testing"""
    np.random.seed(seed)

    print(f"\n{'='*80}")
    print(f"GENERATING SAMPLE FINANCE DATASET")
    print(f"{'='*80}")
    print(f"   Records: {n_samples:,}")
    print(f"   Seed: {seed}")

    data = {
        "applicant_id": range(n_samples),
        "applicant_name": [f"Applicant_{i}" for i in range(n_samples)],
        "ethnicity": np.random.choice(
            ["White", "Black", "Asian", "Other"],
            n_samples,
            p=[0.70, 0.15, 0.10, 0.05]
        ),
        "age": np.random.randint(20, 70, n_samples),
        "gender": np.random.choice(["Male", "Female"], n_samples, p=[0.55, 0.45]),
        "postcode": np.random.choice(["Urban", "Rural", "Suburban"], n_samples),
        "annual_income": np.random.normal(50000, 20000, n_samples).clip(20000, 150000),
        "credit_score": np.random.randint(300, 850, n_samples),
        "debt_to_income": np.random.uniform(0.1, 0.8, n_samples),
        "employment_years": np.random.randint(0, 40, n_samples),
        "application_date": pd.date_range("2023-01-01", periods=n_samples, freq="H")
    }

    df = pd.DataFrame(data)

    base_rate = 0.65
    ethnic_biases = {
        "White": base_rate * 1.50,
        "Black": base_rate * 0.30,
        "Asian": base_rate * 0.95,
        "Other": base_rate * 0.85
    }

    def credit_factor(score):
        if score < 500: return 0.40
        elif score < 600: return 0.70
        elif score < 700: return 0.90
        elif score < 750: return 1.10
        else: return 1.30

    def dti_factor(dti):
        if dti < 0.3: return 1.20
        elif dti < 0.5: return 1.00
        elif dti < 0.7: return 0.80
        else: return 0.60

    approvals = []
    for idx, row in df.iterrows():
        prob = ethnic_biases[row["ethnicity"]]
        prob *= credit_factor(row["credit_score"])
        prob *= dti_factor(row["debt_to_income"])
        prob *= np.random.uniform(0.95, 1.05)
        prob = np.clip(prob, 0.05, 0.95)
        approvals.append(np.random.binomial(1, prob))

    df["loan_approved"] = approvals

    print(f"\n   Loan Approval Rates by Ethnicity (Showing Bias):")
    approval_by_ethnicity = df.groupby("ethnicity")["loan_approved"].mean().sort_values(ascending=False)
    for ethnicity, rate in approval_by_ethnicity.items():
        deviation = ((rate - base_rate) / base_rate) * 100
        print(f"     • {ethnicity:15} {rate:.1%}  (deviation: {deviation:+.0f}%)")

    print(f"\n   Overall Approval Rate: {df['loan_approved'].mean():.1%}")
    print(f"   Max Disparity: {approval_by_ethnicity.max() - approval_by_ethnicity.min():.1%}")
    print(f"{'='*80}\n")

    return df

def create_sample_hiring_dataset(n_samples: int = 2000, seed: int = 42) -> pd.DataFrame:
    """Create realistic hiring dataset with inherent bias for testing"""
    np.random.seed(seed)

    print(f"\n{'='*80}")
    print(f"GENERATING SAMPLE HIRING DATASET")
    print(f"{'='*80}")
    print(f"   Records: {n_samples:,}")
    print(f"   Seed: {seed}")

    data = {
        "candidate_id": range(n_samples),
        "candidate_name": [f"Candidate_{i}" for i in range(n_samples)],
        "ethnicity": np.random.choice(
            ["White", "Black", "Asian", "Other"],
            n_samples,
            p=[0.65, 0.20, 0.10, 0.05]
        ),
        "age": np.random.randint(20, 65, n_samples),
        "gender": np.random.choice(["Male", "Female"], n_samples, p=[0.60, 0.40]),
        "postcode": np.random.choice(["Urban", "Rural", "Suburban"], n_samples),
        "education_years": np.random.randint(10, 22, n_samples),
        "years_experience": np.random.randint(0, 30, n_samples),
        "resume_score": np.random.randint(50, 100, n_samples),
        "interview_score": np.random.randint(40, 100, n_samples),
        "skill_match_percent": np.random.uniform(0.5, 1.0, n_samples),
        "application_date": pd.date_range("2023-01-01", periods=n_samples, freq="H"),
        "disability_status": np.random.choice(["None", "Physical", "Cognitive", "Sensory"],
                                            n_samples, p=[0.85, 0.08, 0.05, 0.02]),
        "migration_status": np.random.choice(["Citizen", "Permanent Resident", "Work Visa", "Other"],
                                           n_samples, p=[0.70, 0.15, 0.10, 0.05])
    }

    df = pd.DataFrame(data)

    base_rate = 0.40
    ethnic_biases = {
        "White": base_rate * 1.50,
        "Black": base_rate * 0.30,
        "Asian": base_rate * 0.90,
        "Other": base_rate * 0.75
    }

    gender_biases = {
        "Male": base_rate * 1.15,
        "Female": base_rate * 0.85
    }

    def experience_factor(years):
        if years < 2: return 0.70
        elif years < 5: return 0.90
        elif years < 10: return 1.10
        elif years < 15: return 1.25
        else: return 1.15

    def education_factor(years):
        if years < 12: return 0.80
        elif years < 16: return 1.00
        elif years < 18: return 1.15
        else: return 1.25

    def disability_factor(status):
        if status == "None": return 1.00
        else: return 0.80

    hiring_decisions = []
    for idx, row in df.iterrows():
        prob = ethnic_biases[row["ethnicity"]]
        prob *= gender_biases[row["gender"]]
        prob *= experience_factor(row["years_experience"])
        prob *= education_factor(row["education_years"])
        prob *= disability_factor(row["disability_status"])
        prob *= (0.5 + (row["skill_match_percent"] * 0.5))
        prob *= np.random.uniform(0.95, 1.05)
        prob = np.clip(prob, 0.05, 0.95)
        hiring_decisions.append(np.random.binomial(1, prob))

    df["hired"] = hiring_decisions

    print(f"\n   Hiring Rates by Ethnicity (Showing Bias):")
    hiring_by_ethnicity = df.groupby("ethnicity")["hired"].mean().sort_values(ascending=False)
    for ethnicity, rate in hiring_by_ethnicity.items():
        deviation = ((rate - base_rate) / base_rate) * 100
        print(f"     • {ethnicity:15} {rate:.1%}  (deviation: {deviation:+.0f}%)")

    print(f"\n   Hiring Rates by Gender:")
    hiring_by_gender = df.groupby("gender")["hired"].mean().sort_values(ascending=False)
    for gender, rate in hiring_by_gender.items():
        deviation = ((rate - base_rate) / base_rate) * 100
        print(f"     • {gender:15} {rate:.1%}  (deviation: {deviation:+.0f}%)")

    print(f"\n   Overall Hiring Rate: {df['hired'].mean():.1%}")
    print(f"   Max Ethnicity Disparity: {hiring_by_ethnicity.max() - hiring_by_ethnicity.min():.1%}")
    print(f"   Gender Disparity: {hiring_by_gender.max() - hiring_by_gender.min():.1%}")
    print(f"{'='*80}\n")

    return df

