def run_interactive_pipeline():
    """Interactive interface for Colab users with v3.0 enhancements"""
    try:
        from google.colab import files
        import io
        colab_available = True
    except ImportError:
        colab_available = False
        files = None
        print("Note: Google Colab not available. Running in local mode.")

    print(f"\n{'='*80}")
    print(f"UNIVERSAL BIASCLEAN v{__version__} - INTERACTIVE MODE")
    print(f"{'='*80}\n")

    print("✨ v3.0 NEW FEATURES:")
    print("  • Pre-mitigation audit with traffic-light recommendation")
    print("  • Audit-first, legacy, and audit-only modes")
    print("  • Configurable SVM fairness enforcement")
    print("  • Governance reporting for decision-makers")
    print()

    print("Choose data source:")
    print("  1. Upload your own CSV file")
    print("  2. Generate sample justice dataset")
    print("  3. Generate sample healthcare dataset")
    print("  4. Generate sample finance dataset")
    print("  5. Generate sample hiring dataset")
    print("  6. Generate sample education dataset")
    print("  7. Generate sample business dataset")
    print("  8. Generate sample governance dataset")
    print()

    choice = input("Enter choice (1-8): ").strip()

    df = None
    file_name = None

    if choice == "1":
        if colab_available:
            print("\nPlease upload your CSV file...")
            uploaded = files.upload()

            if not uploaded:
                print("No file uploaded. Exiting.")
                return None

            file_name = list(uploaded.keys())[0]
            df = smart_read_csv(io.BytesIO(uploaded[file_name]))
        else:
            file_path = input("\nEnter path to CSV file: ").strip()

            import os
            if not os.path.exists(file_path):
                print(f"File not found: {file_path}")
                return None

            df = smart_read_csv(file_path)
            file_name = os.path.basename(file_path)

        print(f"\n✓ File loaded: {file_name}")
        print(f"  Records: {len(df):,}")
        print(f"  Columns: {len(df.columns)}")

        # Show column preview
        print(f"\n  Columns: {', '.join(df.columns[:10])}")
        if len(df.columns) > 10:
            print(f"  ... and {len(df.columns) - 10} more")

    elif choice == "2":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_justice_dataset(n_samples=n_samples)
        file_name = "sample_justice_data.csv"

    elif choice == "3":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_health_dataset(n_samples=n_samples)
        file_name = "sample_health_data.csv"

    elif choice == "4":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_finance_dataset(n_samples=n_samples)
        file_name = "sample_finance_data.csv"

    elif choice == "5":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_hiring_dataset(n_samples=n_samples)
        file_name = "sample_hiring_data.csv"

    elif choice == "6":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_education_dataset(n_samples=n_samples)
        file_name = "sample_education_data.csv"

    elif choice == "7":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_business_dataset(n_samples=n_samples)
        file_name = "sample_business_data.csv"

    elif choice == "8":
        n_samples = input("\nEnter number of samples (default: 2000): ").strip()
        n_samples = int(n_samples) if n_samples else 2000
        df = create_sample_governance_dataset(n_samples=n_samples)
        file_name = "sample_governance_data.csv"

    else:
        print("Invalid choice. Exiting.")
        return None

    # Required (v3.10.1): Specify target column -- no auto-detection.
    # See the decision record in process_dataset's target-column block
    # (and the 3.10.0 -> 3.10.1 changelog entry at the top of this file)
    # for why: no column-name pattern or statistic can substitute for
    # knowing what this dataset actually measures -- only you know that.
    print(f"\n{'='*80}")
    print("TARGET COLUMN SELECTION")
    print(f"{'='*80}")
    print("Available columns:")
    for idx, col in enumerate(df.columns, 1):
        try:
            uniq = int(df[col].nunique(dropna=True))
        except Exception:
            uniq = -1
        dtype = str(df[col].dtype)
        print(f"  {idx:2}. {col:30} (unique: {uniq:5}, dtype: {dtype})")

    print()
    print("BiasClean does not auto-detect which column is your outcome/target.")
    print("Only you know what this dataset measures -- e.g. which column records")
    print("whether an applicant received a callback, a loan was approved, or a")
    print("defendant reoffended. Please choose the correct column from the list above --")
    print("either its row number (e.g. '17') or its exact name.")
    print()
    target_column = ""
    while not target_column:
        target_input = input("Enter target column NUMBER or exact name (required): ").strip()
        if not target_input:
            print("A target column is required -- BiasClean will not guess this for you.")
            continue
        # Exact name match takes priority (covers the rare case of a
        # column literally named e.g. "17"). Otherwise, accept a row
        # number from the list above -- a digit is much harder to
        # mistype than a case-sensitive, underscore-heavy column name,
        # and this matches the numbered-choice pattern already used
        # for domain selection below.
        if target_input in df.columns:
            target_column = target_input
            continue
        if target_input.isdigit():
            row_num = int(target_input)
            if 1 <= row_num <= len(df.columns):
                resolved = df.columns[row_num - 1]
                print(f"   -> column {row_num} is '{resolved}'")
                target_column = resolved
                continue
            else:
                print(f"'{target_input}' is not a valid row number (must be between 1 and {len(df.columns)}).")
                continue
        print(f"'{target_input}' was not found in this dataset's columns. Please check for a typo, "
              f"or enter its row number from the list above instead.")

    # Optional: Auto-approval threshold
    print()
    threshold_input = input("Enter auto-approval threshold (0.0-1.0, default: 0.80): ").strip()

    try:
        threshold = float(threshold_input) if threshold_input else 0.80
        threshold = max(0.0, min(1.0, threshold))
    except ValueError:
        print("Invalid threshold. Using default 0.80")
        threshold = 0.80

    print("\nSelect domain:")
    print("  1. Justice (default)")
    print("  2. Healthcare")
    print("  3. Finance")
    print("  4. Hiring")
    print("  5. Education")
    print("  6. Business")
    print("  7. Governance")
    domain_choice = input("Enter choice (1-7, default: 1): ").strip()

    domain_map = {
        "1": "justice",
        "2": "health",
        "3": "finance",
        "4": "hiring",
        "5": "education",
        "6": "business",
        "7": "governance"
    }

    domain_key = domain_map.get(domain_choice, "justice")

    # v3.0 Mode selection
    print("\nBiasClean v3.0 Mode:")
    print("  1. Audit-First (Recommended) - Validate before mitigating")
    print("  2. Legacy v2.7 - Original behavior")
    print("  3. Audit-Only - Diagnostics without mitigation")

    mode_choice = input("Select (1-3, default: 1): ").strip()
    if mode_choice == "2":
        mode = "legacy"
    elif mode_choice == "3":
        mode = "audit_only"
    else:
        mode = "audit_first"

    # SVM option (only if mitigating)
    if mode != "audit_only":
        svm_choice = input("Enable SVM fairness enforcement? (y/N): ").strip().lower()
        enable_svm = (svm_choice == 'y')
    else:
        svm_choice = input("Enable SVM fairness enforcement? (y/N, default: N): ").strip().lower()
        enable_svm = (svm_choice == 'y')

    print(f"SVM: {'ENABLED' if enable_svm else 'DISABLED (default)'}")

    # Initialize with v3.0 parameters
    print(f"\n{'='*80}")
    print(f"🚀 INITIALIZING {domain_key.upper()} BIASCLEAN v{__version__}")
    print(f"{'='*80}\n")

    pipeline = UniversalBiasClean(
        domain=domain_key,
        mode=mode,
        enable_svm=enable_svm
    )

    # Run pipeline. process_dataset() already prints its own complete,
    # accurate summary internally (audit verdict, bias scores, data
    # integrity, fairness improvements, and the final file list) via
    # ReportGenerator.print_console_report and the "PIPELINE COMPLETED
    # SUCCESSFULLY!" block -- there used to be a SECOND summary printed
    # here on top of that, left over from before that console report
    # existed. It was not just redundant: it called generate_governance_
    # report() and printed "Governance report saved to:
    # biasclean_results/GOVERNANCE_REPORT.txt" even though nothing
    # actually writes that file anymore (that write was removed from
    # _save_results during the reporting consolidation), and it ended
    # with Colab-era "Open Files tab (folder icon on left)" instructions
    # that make no sense when running locally in a terminal -- exactly
    # the kind of stale, contradictory reporting this whole redesign was
    # meant to eliminate. Removed entirely; process_dataset's own output
    # is the single source of truth for what ran and what got saved.
    results = pipeline.process_dataset(
        df=df,
        target_column=target_column,
        auto_approve_threshold=threshold
    )

    return results

# ============================================================================
# 10. MAIN EXECUTION BLOCK v3.0
# ============================================================================
#

# ============================================================================
# PRODUCTION USER INTERFACE
# ============================================================================

def run_biasclean_interactive():
    """
    Interactive interface for non-technical users.
    Guides through domain selection, target identification, and audit execution.
    """
    print("="*80)
    print(f"BiasClean v{__version__} - Interactive Fairness Audit")
    print("="*80)
    print("\nThis tool helps you audit and mitigate bias in your dataset.")
    print("No coding knowledge required.\n")

    # Step 1: Load data
    print("STEP 1: LOAD YOUR DATA")
    print("-" * 40)
    file_path = input("Enter CSV file path (or 'demo' for sample): ").strip()

    if file_path.lower() == 'demo':
        # Create demo dataset
        import numpy as np
        df = pd.DataFrame({
            'ethnicity': np.random.choice(['A', 'B', 'C'], 1000),
            'age': np.random.randint(18, 70, 1000),
            'gender': np.random.choice(['M', 'F'], 1000),
            'outcome': np.random.binomial(1, 0.5, 1000)
        })
        print("✓ Demo dataset loaded (1000 records)")
    else:
        try:
            df = smart_read_csv(file_path)
            print(f"✓ Loaded: {len(df):,} records, {len(df.columns)} columns")
        except Exception as e:
            print(f"❌ Error loading file: {e}")
            return

    # Step 2: Domain selection
    print("\nSTEP 2: SELECT YOUR DOMAIN")
    print("-" * 40)
    domains = [
        ("1", "justice", "Criminal justice, recidivism, sentencing"),
        ("2", "health", "Healthcare, diagnosis, treatment allocation"),
        ("3", "finance", "Credit scoring, loan approval, insurance"),
        ("4", "hiring", "Recruitment, job offers, promotions"),
        ("5", "education", "Admissions, grading, academic outcomes"),
        ("6", "business", "Funding, contracts, procurement"),
        ("7", "governance", "Elections, appointments, representation")
    ]

    for num, key, desc in domains:
        print(f"  {num}. {key.title():15} - {desc}")

    domain_choice = input("\nEnter choice (1-7, default=1): ").strip() or "1"
    domain = [d[1] for d in domains if d[0] == domain_choice][0] if domain_choice in "1234567" else "justice"
    print(f"✓ Selected: {domain.title()}")

    # Step 3: Target column
    print("\nSTEP 3: IDENTIFY TARGET COLUMN")
    print("-" * 40)
    print("Your columns:")
    for i, col in enumerate(df.columns, 1):
        sample = df[col].iloc[0] if len(df) > 0 else "N/A"
        uniq = df[col].nunique()
        print(f"  {i:2}. {col:30} (unique: {uniq:5}, sample: {sample})")

    target = input("\nEnter target column name (or press Enter for auto): ").strip() or None

    # Step 4: Mode selection
    print("\nSTEP 4: SELECT AUDIT MODE")
    print("-" * 40)
    print("  1. Audit-First (Recommended) - Check before fixing")
    print("  2. Audit-Only - Just diagnose, don't fix")
    print("  3. Legacy - Skip audit, use v2.7 behavior")

    mode_choice = input("\nEnter choice (1-3, default=1): ").strip() or "1"
    mode_map = {"1": "audit_first", "2": "audit_only", "3": "legacy"}
    mode = mode_map.get(mode_choice, "audit_first")

    # Step 5: SVM option
    print("\nSTEP 5: SVM FAIRNESS ENFORCEMENT")
    print("-" * 40)
    print("SVM adds model-level fairness (experimental)")
    enable_svm = input("Enable SVM? (y/N): ").strip().lower() == 'y'

    # Step 6: Run pipeline
    print("\n" + "="*80)
    print("RUNNING BIASCLEAN")
    print("="*80)

    try:
        pipeline = UniversalBiasClean(
            domain=domain,
            mode=mode,
            enable_svm=enable_svm
        )

        results = pipeline.process_dataset(
            df=df,
            target_column=target,
            auto_approve_threshold=0.80
        )

        # Display results
        print("\n" + "="*80)
        print("RESULTS SUMMARY")
        print("="*80)

        if mode in ["audit_first", "audit_only"]:
            if "audit" in results:
                audit = results["audit"]
                rec = audit["recommendation"]
                print(f"\n🎯 {rec['traffic_light']}")
                print(f"📋 {rec['action']}")
                print(f"\nBias Score: {audit['baseline_fairness']['aggregate_bias']:.3f}")
                print(f"Records: {audit['data_quality']['n_records']:,}")
                print(f"Vulnerable Groups: {audit['vulnerable_subgroups']['count']}")

                if rec['rationale']:
                    print("\nReasons:")
                    for reason in rec['rationale']:
                        if reason:
                            print(f"  • {reason}")

        print(f"\n💾 Full results saved to: biasclean_results/")
        print("="*80)

        return results

    except Exception as e:
        print(f"\n❌ Error: {e}")
        import traceback
        traceback.print_exc()
        return None

# Add convenience function
def quick_audit(csv_path, domain="justice", target=None):
    """
    Quick audit for Python users.

    NOTE (v3.10.1): `target` is required in practice -- there is no
    auto-detection fallback. Omitting it (or leaving it None) will raise
    a ValueError from process_dataset explaining why and listing the
    dataset's available columns. The default of None is kept here only
    so a missing target fails with that clear message rather than a
    TypeError; it is not usable as an actual default.

    Example:
        results = quick_audit("data.csv", domain="health", target="diagnosis")
    """
    df = smart_read_csv(csv_path)
    pipeline = UniversalBiasClean(domain=domain, mode="audit_only")
    return pipeline.process_dataset(df=df, target_column=target)


if __name__ == "__main__":
    run_interactive_pipeline()
